insert into public.lessons (id, module_id, position, title_fr, objective_fr, difficulty, est_minutes, kind, published) values ('m1l1', 1, 1, 'Alif et la famille de bā’', 'Reconnaître, nommer et prononcer : ا ب ت ث', 1, 6, 'lesson', true) on conflict (id) do update set title_fr = excluded.title_fr, objective_fr = excluded.objective_fr, difficulty = excluded.difficulty, est_minutes = excluded.est_minutes, kind = excluded.kind, position = excluded.position;
insert into public.lesson_contents (lesson_id, content) values ('m1l1', '{"steps":[{"kind":"explain","text":"L’arabe s’écrit et se lit de droite à gauche. Il compte 28 lettres, toutes des consonnes (alif, wāw et yā’ servent aussi à noter les voyelles longues). Beaucoup de lettres partagent le même tracé et ne se distinguent que par leurs points : c’est le cas de ب, ت et ث."},{"kind":"letter","letterId":"alif"},{"kind":"letter","letterId":"ba"},{"kind":"letter","letterId":"ta"},{"kind":"letter","letterId":"tha"},{"kind":"tip","text":"Même tracé, points différents : ب un point dessous, ت deux points dessus, ث trois points dessus. Regardez toujours les points en premier."}],"exercises":[{"id":"m1l1-listen-alif","type":"choice","format":"listen","prompt":"Écoutez puis choisissez la lettre entendue","options":[{"id":"dad","ar":"ض","why":"ض est ḍād : « d » emphatique, son grave et plein ; lettre réputée propre à l’arabe. Repère visuel : un point au-dessus."},{"id":"nun","ar":"ن","why":"ن est nūn : « n » comme dans « nez ». Repère visuel : un point au-dessus."},{"id":"alif","ar":"ا"},{"id":"ghayn","ar":"غ","why":"غ est ghayn : « r » grasseyé comme le « r » parisien de « Paris ». Repère visuel : un point au-dessus."}],"answer":"alif","explanation":"ا se nomme alif (أَلِف) et se transcrit « ā » : pas de son propre : support de la voyelle longue « â » ou de la hamza (attaque de voyelle). Repère visuel : aucun point.","audio":"letter:alif","textFallback":"Quelle lettre se prononce pas de son propre : support de la voyelle longue « â » ou de la hamza (attaque de voyelle) ?","reviewKey":"letter:alif"},{"id":"m1l1-name-alif","type":"choice","format":"visual","prompt":"Quelle lettre s''appelle « alif » ?","options":[{"id":"dad","ar":"ض","why":"ض est ḍād : « d » emphatique, son grave et plein ; lettre réputée propre à l’arabe. Repère visuel : un point au-dessus."},{"id":"tta","ar":"ط","why":"ط est ṭā’ : « t » emphatique : son grave, arrière de la langue relevé. Repère visuel : aucun point."},{"id":"ha","ar":"ه","why":"ه est hā’ : « h » léger et expiré, comme l’anglais « hello ». Repère visuel : aucun point."},{"id":"alif","ar":"ا"}],"answer":"alif","explanation":"ا se nomme alif (أَلِف) et se transcrit « ā » : pas de son propre : support de la voyelle longue « â » ou de la hamza (attaque de voyelle). Repère visuel : aucun point.","reviewKey":"letter:alif"},{"id":"m1l1-listen-ba","type":"choice","format":"listen","prompt":"Écoutez puis choisissez la lettre entendue","options":[{"id":"ba","ar":"ب"},{"id":"ta","ar":"ت","why":"ت est tā’ : « t » comme dans « table ». Repère visuel : deux points au-dessus."},{"id":"qaf","ar":"ق","why":"ق est qāf : « k » prononcé très au fond, contre la luette. Repère visuel : deux points au-dessus."},{"id":"tha","ar":"ث","why":"ث est thā’ : « th » de l’anglais « think » : langue entre les dents, sans voix. Repère visuel : trois points au-dessus."}],"answer":"ba","explanation":"ب se nomme bā’ (بَاء) et se transcrit « b » : « b » comme dans « bateau ». Repère visuel : un point en dessous.","audio":"letter:ba","textFallback":"Quelle lettre se prononce « b » comme dans « bateau » ?","reviewKey":"letter:ba"},{"id":"m1l1-name-ba","type":"choice","format":"visual","prompt":"Quelle lettre s''appelle « bā’ » ?","options":[{"id":"tha","ar":"ث","why":"ث est thā’ : « th » de l’anglais « think » : langue entre les dents, sans voix. Repère visuel : trois points au-dessus."},{"id":"ta","ar":"ت","why":"ت est tā’ : « t » comme dans « table ». Repère visuel : deux points au-dessus."},{"id":"ba","ar":"ب"},{"id":"nun","ar":"ن","why":"ن est nūn : « n » comme dans « nez ». Repère visuel : un point au-dessus."}],"answer":"ba","explanation":"ب se nomme bā’ (بَاء) et se transcrit « b » : « b » comme dans « bateau ». Repère visuel : un point en dessous.","reviewKey":"letter:ba"},{"id":"m1l1-listen-ta","type":"choice","format":"listen","prompt":"Écoutez puis choisissez la lettre entendue","options":[{"id":"tha","ar":"ث","why":"ث est thā’ : « th » de l’anglais « think » : langue entre les dents, sans voix. Repère visuel : trois points au-dessus."},{"id":"ta","ar":"ت"},{"id":"ba","ar":"ب","why":"ب est bā’ : « b » comme dans « bateau ». Repère visuel : un point en dessous."},{"id":"dhal","ar":"ذ","why":"ذ est dhāl : « th » de l’anglais « this » : langue entre les dents, avec la voix. Repère visuel : un point au-dessus."}],"answer":"ta","explanation":"ت se nomme tā’ (تَاء) et se transcrit « t » : « t » comme dans « table ». Repère visuel : deux points au-dessus.","audio":"letter:ta","textFallback":"Quelle lettre se prononce « t » comme dans « table » ?","reviewKey":"letter:ta"},{"id":"m1l1-name-ta","type":"choice","format":"visual","prompt":"Quelle lettre s''appelle « tā’ » ?","options":[{"id":"ba","ar":"ب","why":"ب est bā’ : « b » comme dans « bateau ». Repère visuel : un point en dessous."},{"id":"ta","ar":"ت"},{"id":"tha","ar":"ث","why":"ث est thā’ : « th » de l’anglais « think » : langue entre les dents, sans voix. Repère visuel : trois points au-dessus."},{"id":"dal","ar":"د","why":"د est dāl : « d » comme dans « dos ». Repère visuel : aucun point."}],"answer":"ta","explanation":"ت se nomme tā’ (تَاء) et se transcrit « t » : « t » comme dans « table ». Repère visuel : deux points au-dessus.","reviewKey":"letter:ta"},{"id":"m1l1-listen-tha","type":"choice","format":"listen","prompt":"Écoutez puis choisissez la lettre entendue","options":[{"id":"zza","ar":"ظ","why":"ظ est ẓā’ : « th » de « this » prononcé de façon emphatique (grave). Repère visuel : un point au-dessus."},{"id":"tha","ar":"ث"},{"id":"ta","ar":"ت","why":"ت est tā’ : « t » comme dans « table ». Repère visuel : deux points au-dessus."},{"id":"ba","ar":"ب","why":"ب est bā’ : « b » comme dans « bateau ». Repère visuel : un point en dessous."}],"answer":"tha","explanation":"ث se nomme thā’ (ثَاء) et se transcrit « th » : « th » de l’anglais « think » : langue entre les dents, sans voix. Repère visuel : trois points au-dessus.","audio":"letter:tha","textFallback":"Quelle lettre se prononce « th » de l’anglais « think » : langue entre les dents, sans voix ?","reviewKey":"letter:tha"},{"id":"m1l1-name-tha","type":"choice","format":"visual","prompt":"Quelle lettre s''appelle « thā’ » ?","options":[{"id":"kha","ar":"خ","why":"خ est khā’ : « r » raclé au fond du palais, comme la « jota » espagnole ou le « ch » allemand de « Bach ». Repère visuel : un point au-dessus."},{"id":"ba","ar":"ب","why":"ب est bā’ : « b » comme dans « bateau ». Repère visuel : un point en dessous."},{"id":"tha","ar":"ث"},{"id":"ta","ar":"ت","why":"ت est tā’ : « t » comme dans « table ». Repère visuel : deux points au-dessus."}],"answer":"tha","explanation":"ث se nomme thā’ (ثَاء) et se transcrit « th » : « th » de l’anglais « think » : langue entre les dents, sans voix. Repère visuel : trois points au-dessus.","reviewKey":"letter:tha"},{"id":"m1l1-sound-alif","type":"choice","format":"mcq","prompt":"Quel son correspond à cette lettre ?","options":[{"id":"alif","label":"« ā »"},{"id":"ghayn","label":"« gh »","why":"غ est ghayn : « r » grasseyé comme le « r » parisien de « Paris ». Repère visuel : un point au-dessus."},{"id":"sin","label":"« s »","why":"س est sīn : « s » comme dans « sel ». Repère visuel : aucun point."},{"id":"waw","label":"« w / ū »","why":"و est wāw : « w » comme dans « watt », ou voyelle longue « oû ». Repère visuel : aucun point."}],"answer":"alif","explanation":"ا se nomme alif (أَلِف) et se transcrit « ā » : pas de son propre : support de la voyelle longue « â » ou de la hamza (attaque de voyelle). Repère visuel : aucun point.","ar":"ا","reviewKey":"letter:alif"},{"id":"m1l1-sound-ba","type":"choice","format":"mcq","prompt":"Quel son correspond à cette lettre ?","options":[{"id":"ta","label":"« t »","why":"ت est tā’ : « t » comme dans « table ». Repère visuel : deux points au-dessus."},{"id":"ya","label":"« y / ī »","why":"ي est yā’ : « y » comme dans « yaourt », ou voyelle longue « î ». Repère visuel : deux points en dessous."},{"id":"ba","label":"« b »"},{"id":"tha","label":"« th »","why":"ث est thā’ : « th » de l’anglais « think » : langue entre les dents, sans voix. Repère visuel : trois points au-dessus."}],"answer":"ba","explanation":"ب se nomme bā’ (بَاء) et se transcrit « b » : « b » comme dans « bateau ». Repère visuel : un point en dessous.","ar":"ب","reviewKey":"letter:ba"},{"id":"m1l1-match","type":"match","prompt":"Associez chaque lettre à son nom","pairs":[{"left":{"id":"l-alif","ar":"ا"},"right":{"id":"r-alif","label":"alif"}},{"left":{"id":"l-ba","ar":"ب"},"right":{"id":"r-ba","label":"bā’"}},{"left":{"id":"l-ta","ar":"ت"},"right":{"id":"r-ta","label":"tā’"}},{"left":{"id":"l-tha","ar":"ث"},"right":{"id":"r-tha","label":"thā’"}}],"explanation":"ا = alif · ب = bā’ · ت = tā’ · ث = thā’"}],"summary":["ا — alif : « ā » (aucun point)","ب — bā’ : « b » (un point en dessous)","ت — tā’ : « t » (deux points au-dessus)","ث — thā’ : « th » (trois points au-dessus)"]}'::jsonb) on conflict (lesson_id) do update set content = excluded.content, version = public.lesson_contents.version + 1, updated_at = now();
insert into public.lessons (id, module_id, position, title_fr, objective_fr, difficulty, est_minutes, kind, published) values ('m1l2', 1, 2, 'La famille de jīm', 'Reconnaître, nommer et prononcer : ج ح خ', 1, 6, 'lesson', true) on conflict (id) do update set title_fr = excluded.title_fr, objective_fr = excluded.objective_fr, difficulty = excluded.difficulty, est_minutes = excluded.est_minutes, kind = excluded.kind, position = excluded.position;
insert into public.lesson_contents (lesson_id, content) values ('m1l2', '{"steps":[{"kind":"explain","text":"ج, ح et خ partagent le même corps. Deux d’entre elles produisent des sons qui n’existent pas en français : ح (souffle serré) et خ (raclement)."},{"kind":"letter","letterId":"jim"},{"kind":"letter","letterId":"hha"},{"kind":"letter","letterId":"kha"},{"kind":"tip","text":"ج point dessous, ح aucun point, خ point dessus. Pour ح, soufflez fort en serrant le milieu de la gorge, sans racler."}],"exercises":[{"id":"m1l2-listen-jim","type":"choice","format":"listen","prompt":"Écoutez puis choisissez la lettre entendue","options":[{"id":"jim","ar":"ج"},{"id":"kha","ar":"خ","why":"خ est khā’ : « r » raclé au fond du palais, comme la « jota » espagnole ou le « ch » allemand de « Bach ». Repère visuel : un point au-dessus."},{"id":"hha","ar":"ح","why":"ح est ḥā’ : « h » soufflé et serré au milieu de la gorge, comme pour embuer une vitre très fort. Repère visuel : aucun point."},{"id":"lam","ar":"ل","why":"ل est lām : « l » comme dans « lune ». Repère visuel : aucun point."}],"answer":"jim","explanation":"ج se nomme jīm (جِيم) et se transcrit « j » : « dj » comme dans « djinn ». Repère visuel : un point en dessous.","audio":"letter:jim","textFallback":"Quelle lettre se prononce « dj » comme dans « djinn » ?","reviewKey":"letter:jim"},{"id":"m1l2-name-jim","type":"choice","format":"visual","prompt":"Quelle lettre s''appelle « jīm » ?","options":[{"id":"jim","ar":"ج"},{"id":"zay","ar":"ز","why":"ز est zāy : « z » comme dans « zéro ». Repère visuel : un point au-dessus."},{"id":"hha","ar":"ح","why":"ح est ḥā’ : « h » soufflé et serré au milieu de la gorge, comme pour embuer une vitre très fort. Repère visuel : aucun point."},{"id":"kha","ar":"خ","why":"خ est khā’ : « r » raclé au fond du palais, comme la « jota » espagnole ou le « ch » allemand de « Bach ». Repère visuel : un point au-dessus."}],"answer":"jim","explanation":"ج se nomme jīm (جِيم) et se transcrit « j » : « dj » comme dans « djinn ». Repère visuel : un point en dessous.","reviewKey":"letter:jim"},{"id":"m1l2-listen-hha","type":"choice","format":"listen","prompt":"Écoutez puis choisissez la lettre entendue","options":[{"id":"ha","ar":"ه","why":"ه est hā’ : « h » léger et expiré, comme l’anglais « hello ». Repère visuel : aucun point."},{"id":"kha","ar":"خ","why":"خ est khā’ : « r » raclé au fond du palais, comme la « jota » espagnole ou le « ch » allemand de « Bach ». Repère visuel : un point au-dessus."},{"id":"jim","ar":"ج","why":"ج est jīm : « dj » comme dans « djinn ». Repère visuel : un point en dessous."},{"id":"hha","ar":"ح"}],"answer":"hha","explanation":"ح se nomme ḥā’ (حَاء) et se transcrit « ḥ » : « h » soufflé et serré au milieu de la gorge, comme pour embuer une vitre très fort. Repère visuel : aucun point.","audio":"letter:hha","textFallback":"Quelle lettre se prononce « h » soufflé et serré au milieu de la gorge, comme pour embuer une vitre très fort ?","reviewKey":"letter:hha"},{"id":"m1l2-name-hha","type":"choice","format":"visual","prompt":"Quelle lettre s''appelle « ḥā’ » ?","options":[{"id":"jim","ar":"ج","why":"ج est jīm : « dj » comme dans « djinn ». Repère visuel : un point en dessous."},{"id":"ha","ar":"ه","why":"ه est hā’ : « h » léger et expiré, comme l’anglais « hello ». Repère visuel : aucun point."},{"id":"kha","ar":"خ","why":"خ est khā’ : « r » raclé au fond du palais, comme la « jota » espagnole ou le « ch » allemand de « Bach ». Repère visuel : un point au-dessus."},{"id":"hha","ar":"ح"}],"answer":"hha","explanation":"ح se nomme ḥā’ (حَاء) et se transcrit « ḥ » : « h » soufflé et serré au milieu de la gorge, comme pour embuer une vitre très fort. Repère visuel : aucun point.","reviewKey":"letter:hha"},{"id":"m1l2-listen-kha","type":"choice","format":"listen","prompt":"Écoutez puis choisissez la lettre entendue","options":[{"id":"kha","ar":"خ"},{"id":"waw","ar":"و","why":"و est wāw : « w » comme dans « watt », ou voyelle longue « oû ». Repère visuel : aucun point."},{"id":"jim","ar":"ج","why":"ج est jīm : « dj » comme dans « djinn ». Repère visuel : un point en dessous."},{"id":"hha","ar":"ح","why":"ح est ḥā’ : « h » soufflé et serré au milieu de la gorge, comme pour embuer une vitre très fort. Repère visuel : aucun point."}],"answer":"kha","explanation":"خ se nomme khā’ (خَاء) et se transcrit « kh » : « r » raclé au fond du palais, comme la « jota » espagnole ou le « ch » allemand de « Bach ». Repère visuel : un point au-dessus.","audio":"letter:kha","textFallback":"Quelle lettre se prononce « r » raclé au fond du palais, comme la « jota » espagnole ou le « ch » allemand de « Bach » ?","reviewKey":"letter:kha"},{"id":"m1l2-name-kha","type":"choice","format":"visual","prompt":"Quelle lettre s''appelle « khā’ » ?","options":[{"id":"jim","ar":"ج","why":"ج est jīm : « dj » comme dans « djinn ». Repère visuel : un point en dessous."},{"id":"hha","ar":"ح","why":"ح est ḥā’ : « h » soufflé et serré au milieu de la gorge, comme pour embuer une vitre très fort. Repère visuel : aucun point."},{"id":"kha","ar":"خ"},{"id":"ya","ar":"ي","why":"ي est yā’ : « y » comme dans « yaourt », ou voyelle longue « î ». Repère visuel : deux points en dessous."}],"answer":"kha","explanation":"خ se nomme khā’ (خَاء) et se transcrit « kh » : « r » raclé au fond du palais, comme la « jota » espagnole ou le « ch » allemand de « Bach ». Repère visuel : un point au-dessus.","reviewKey":"letter:kha"},{"id":"m1l2-sound-jim","type":"choice","format":"mcq","prompt":"Quel son correspond à cette lettre ?","options":[{"id":"jim","label":"« j »"},{"id":"dhal","label":"« dh »","why":"ذ est dhāl : « th » de l’anglais « this » : langue entre les dents, avec la voix. Repère visuel : un point au-dessus."},{"id":"hha","label":"« ḥ »","why":"ح est ḥā’ : « h » soufflé et serré au milieu de la gorge, comme pour embuer une vitre très fort. Repère visuel : aucun point."},{"id":"kha","label":"« kh »","why":"خ est khā’ : « r » raclé au fond du palais, comme la « jota » espagnole ou le « ch » allemand de « Bach ». Repère visuel : un point au-dessus."}],"answer":"jim","explanation":"ج se nomme jīm (جِيم) et se transcrit « j » : « dj » comme dans « djinn ». Repère visuel : un point en dessous.","ar":"ج","reviewKey":"letter:jim"},{"id":"m1l2-sound-hha","type":"choice","format":"mcq","prompt":"Quel son correspond à cette lettre ?","options":[{"id":"tta","label":"« ṭ »","why":"ط est ṭā’ : « t » emphatique : son grave, arrière de la langue relevé. Repère visuel : aucun point."},{"id":"kha","label":"« kh »","why":"خ est khā’ : « r » raclé au fond du palais, comme la « jota » espagnole ou le « ch » allemand de « Bach ». Repère visuel : un point au-dessus."},{"id":"hha","label":"« ḥ »"},{"id":"jim","label":"« j »","why":"ج est jīm : « dj » comme dans « djinn ». Repère visuel : un point en dessous."}],"answer":"hha","explanation":"ح se nomme ḥā’ (حَاء) et se transcrit « ḥ » : « h » soufflé et serré au milieu de la gorge, comme pour embuer une vitre très fort. Repère visuel : aucun point.","ar":"ح","reviewKey":"letter:hha"},{"id":"m1l2-match","type":"match","prompt":"Associez chaque lettre à son nom","pairs":[{"left":{"id":"l-jim","ar":"ج"},"right":{"id":"r-jim","label":"jīm"}},{"left":{"id":"l-hha","ar":"ح"},"right":{"id":"r-hha","label":"ḥā’"}},{"left":{"id":"l-kha","ar":"خ"},"right":{"id":"r-kha","label":"khā’"}}],"explanation":"ج = jīm · ح = ḥā’ · خ = khā’"}],"summary":["ج — jīm : « j » (un point en dessous)","ح — ḥā’ : « ḥ » (aucun point)","خ — khā’ : « kh » (un point au-dessus)"]}'::jsonb) on conflict (lesson_id) do update set content = excluded.content, version = public.lesson_contents.version + 1, updated_at = now();
insert into public.lessons (id, module_id, position, title_fr, objective_fr, difficulty, est_minutes, kind, published) values ('m1l3', 1, 3, 'Dāl, dhāl, rā’ et zāy', 'Reconnaître, nommer et prononcer : د ذ ر ز', 2, 6, 'lesson', true) on conflict (id) do update set title_fr = excluded.title_fr, objective_fr = excluded.objective_fr, difficulty = excluded.difficulty, est_minutes = excluded.est_minutes, kind = excluded.kind, position = excluded.position;
insert into public.lesson_contents (lesson_id, content) values ('m1l3', '{"steps":[{"kind":"explain","text":"Ces quatre lettres ont une particularité importante : elles ne se lient jamais à la lettre qui les suit. Vous le verrez au module 2."},{"kind":"letter","letterId":"dal"},{"kind":"letter","letterId":"dhal"},{"kind":"letter","letterId":"ra"},{"kind":"letter","letterId":"zay"},{"kind":"tip","text":"د et ذ sont posées sur la ligne ; ر et ز descendent sous la ligne. Le point fait la différence dans chaque paire."}],"exercises":[{"id":"m1l3-listen-dal","type":"choice","format":"listen","prompt":"Écoutez puis choisissez la lettre entendue","options":[{"id":"dhal","ar":"ذ","why":"ذ est dhāl : « th » de l’anglais « this » : langue entre les dents, avec la voix. Repère visuel : un point au-dessus."},{"id":"dal","ar":"د"},{"id":"sin","ar":"س","why":"س est sīn : « s » comme dans « sel ». Repère visuel : aucun point."},{"id":"fa","ar":"ف","why":"ف est fā’ : « f » comme dans « fil ». Repère visuel : un point au-dessus."}],"answer":"dal","explanation":"د se nomme dāl (دَال) et se transcrit « d » : « d » comme dans « dos ». Repère visuel : aucun point.","audio":"letter:dal","textFallback":"Quelle lettre se prononce « d » comme dans « dos » ?","reviewKey":"letter:dal"},{"id":"m1l3-name-dal","type":"choice","format":"visual","prompt":"Quelle lettre s''appelle « dāl » ?","options":[{"id":"dal","ar":"د"},{"id":"dhal","ar":"ذ","why":"ذ est dhāl : « th » de l’anglais « this » : langue entre les dents, avec la voix. Repère visuel : un point au-dessus."},{"id":"ba","ar":"ب","why":"ب est bā’ : « b » comme dans « bateau ». Repère visuel : un point en dessous."},{"id":"zza","ar":"ظ","why":"ظ est ẓā’ : « th » de « this » prononcé de façon emphatique (grave). Repère visuel : un point au-dessus."}],"answer":"dal","explanation":"د se nomme dāl (دَال) et se transcrit « d » : « d » comme dans « dos ». Repère visuel : aucun point.","reviewKey":"letter:dal"},{"id":"m1l3-listen-dhal","type":"choice","format":"listen","prompt":"Écoutez puis choisissez la lettre entendue","options":[{"id":"dal","ar":"د","why":"د est dāl : « d » comme dans « dos ». Repère visuel : aucun point."},{"id":"kha","ar":"خ","why":"خ est khā’ : « r » raclé au fond du palais, comme la « jota » espagnole ou le « ch » allemand de « Bach ». Repère visuel : un point au-dessus."},{"id":"dhal","ar":"ذ"},{"id":"nun","ar":"ن","why":"ن est nūn : « n » comme dans « nez ». Repère visuel : un point au-dessus."}],"answer":"dhal","explanation":"ذ se nomme dhāl (ذَال) et se transcrit « dh » : « th » de l’anglais « this » : langue entre les dents, avec la voix. Repère visuel : un point au-dessus.","audio":"letter:dhal","textFallback":"Quelle lettre se prononce « th » de l’anglais « this » : langue entre les dents, avec la voix ?","reviewKey":"letter:dhal"},{"id":"m1l3-name-dhal","type":"choice","format":"visual","prompt":"Quelle lettre s''appelle « dhāl » ?","options":[{"id":"sad","ar":"ص","why":"ص est ṣād : « s » emphatique : bouche arrondie, arrière de la langue relevé, son plus grave. Repère visuel : aucun point."},{"id":"ha","ar":"ه","why":"ه est hā’ : « h » léger et expiré, comme l’anglais « hello ». Repère visuel : aucun point."},{"id":"dhal","ar":"ذ"},{"id":"dal","ar":"د","why":"د est dāl : « d » comme dans « dos ». Repère visuel : aucun point."}],"answer":"dhal","explanation":"ذ se nomme dhāl (ذَال) et se transcrit « dh » : « th » de l’anglais « this » : langue entre les dents, avec la voix. Repère visuel : un point au-dessus.","reviewKey":"letter:dhal"},{"id":"m1l3-listen-ra","type":"choice","format":"listen","prompt":"Écoutez puis choisissez la lettre entendue","options":[{"id":"zay","ar":"ز","why":"ز est zāy : « z » comme dans « zéro ». Repère visuel : un point au-dessus."},{"id":"dhal","ar":"ذ","why":"ذ est dhāl : « th » de l’anglais « this » : langue entre les dents, avec la voix. Repère visuel : un point au-dessus."},{"id":"hha","ar":"ح","why":"ح est ḥā’ : « h » soufflé et serré au milieu de la gorge, comme pour embuer une vitre très fort. Repère visuel : aucun point."},{"id":"ra","ar":"ر"}],"answer":"ra","explanation":"ر se nomme rā’ (رَاء) et se transcrit « r » : « r » roulé du bout de la langue, comme en espagnol. Repère visuel : aucun point.","audio":"letter:ra","textFallback":"Quelle lettre se prononce « r » roulé du bout de la langue, comme en espagnol ?","reviewKey":"letter:ra"},{"id":"m1l3-name-ra","type":"choice","format":"visual","prompt":"Quelle lettre s''appelle « rā’ » ?","options":[{"id":"ra","ar":"ر"},{"id":"ghayn","ar":"غ","why":"غ est ghayn : « r » grasseyé comme le « r » parisien de « Paris ». Repère visuel : un point au-dessus."},{"id":"zay","ar":"ز","why":"ز est zāy : « z » comme dans « zéro ». Repère visuel : un point au-dessus."},{"id":"kaf","ar":"ك","why":"ك est kāf : « k » comme dans « kilo ». Repère visuel : aucun point."}],"answer":"ra","explanation":"ر se nomme rā’ (رَاء) et se transcrit « r » : « r » roulé du bout de la langue, comme en espagnol. Repère visuel : aucun point.","reviewKey":"letter:ra"},{"id":"m1l3-listen-zay","type":"choice","format":"listen","prompt":"Écoutez puis choisissez la lettre entendue","options":[{"id":"ra","ar":"ر","why":"ر est rā’ : « r » roulé du bout de la langue, comme en espagnol. Repère visuel : aucun point."},{"id":"ya","ar":"ي","why":"ي est yā’ : « y » comme dans « yaourt », ou voyelle longue « î ». Repère visuel : deux points en dessous."},{"id":"jim","ar":"ج","why":"ج est jīm : « dj » comme dans « djinn ». Repère visuel : un point en dessous."},{"id":"zay","ar":"ز"}],"answer":"zay","explanation":"ز se nomme zāy (زَاي) et se transcrit « z » : « z » comme dans « zéro ». Repère visuel : un point au-dessus.","audio":"letter:zay","textFallback":"Quelle lettre se prononce « z » comme dans « zéro » ?","reviewKey":"letter:zay"},{"id":"m1l3-name-zay","type":"choice","format":"visual","prompt":"Quelle lettre s''appelle « zāy » ?","options":[{"id":"ra","ar":"ر","why":"ر est rā’ : « r » roulé du bout de la langue, comme en espagnol. Repère visuel : aucun point."},{"id":"ha","ar":"ه","why":"ه est hā’ : « h » léger et expiré, comme l’anglais « hello ». Repère visuel : aucun point."},{"id":"sad","ar":"ص","why":"ص est ṣād : « s » emphatique : bouche arrondie, arrière de la langue relevé, son plus grave. Repère visuel : aucun point."},{"id":"zay","ar":"ز"}],"answer":"zay","explanation":"ز se nomme zāy (زَاي) et se transcrit « z » : « z » comme dans « zéro ». Repère visuel : un point au-dessus.","reviewKey":"letter:zay"},{"id":"m1l3-sound-dal","type":"choice","format":"mcq","prompt":"Quel son correspond à cette lettre ?","options":[{"id":"ghayn","label":"« gh »","why":"غ est ghayn : « r » grasseyé comme le « r » parisien de « Paris ». Repère visuel : un point au-dessus."},{"id":"dal","label":"« d »"},{"id":"kha","label":"« kh »","why":"خ est khā’ : « r » raclé au fond du palais, comme la « jota » espagnole ou le « ch » allemand de « Bach ». Repère visuel : un point au-dessus."},{"id":"dhal","label":"« dh »","why":"ذ est dhāl : « th » de l’anglais « this » : langue entre les dents, avec la voix. Repère visuel : un point au-dessus."}],"answer":"dal","explanation":"د se nomme dāl (دَال) et se transcrit « d » : « d » comme dans « dos ». Repère visuel : aucun point.","ar":"د","reviewKey":"letter:dal"},{"id":"m1l3-sound-dhal","type":"choice","format":"mcq","prompt":"Quel son correspond à cette lettre ?","options":[{"id":"nun","label":"« n »","why":"ن est nūn : « n » comme dans « nez ». Repère visuel : un point au-dessus."},{"id":"dal","label":"« d »","why":"د est dāl : « d » comme dans « dos ». Repère visuel : aucun point."},{"id":"dhal","label":"« dh »"},{"id":"zza","label":"« ẓ »","why":"ظ est ẓā’ : « th » de « this » prononcé de façon emphatique (grave). Repère visuel : un point au-dessus."}],"answer":"dhal","explanation":"ذ se nomme dhāl (ذَال) et se transcrit « dh » : « th » de l’anglais « this » : langue entre les dents, avec la voix. Repère visuel : un point au-dessus.","ar":"ذ","reviewKey":"letter:dhal"},{"id":"m1l3-match","type":"match","prompt":"Associez chaque lettre à son nom","pairs":[{"left":{"id":"l-dal","ar":"د"},"right":{"id":"r-dal","label":"dāl"}},{"left":{"id":"l-dhal","ar":"ذ"},"right":{"id":"r-dhal","label":"dhāl"}},{"left":{"id":"l-ra","ar":"ر"},"right":{"id":"r-ra","label":"rā’"}},{"left":{"id":"l-zay","ar":"ز"},"right":{"id":"r-zay","label":"zāy"}}],"explanation":"د = dāl · ذ = dhāl · ر = rā’ · ز = zāy"}],"summary":["د — dāl : « d » (aucun point)","ذ — dhāl : « dh » (un point au-dessus)","ر — rā’ : « r » (aucun point)","ز — zāy : « z » (un point au-dessus)"]}'::jsonb) on conflict (lesson_id) do update set content = excluded.content, version = public.lesson_contents.version + 1, updated_at = now();
insert into public.lessons (id, module_id, position, title_fr, objective_fr, difficulty, est_minutes, kind, published) values ('m1l4', 1, 4, 'Sīn, shīn, ṣād et ḍād', 'Reconnaître, nommer et prononcer : س ش ص ض', 2, 6, 'lesson', true) on conflict (id) do update set title_fr = excluded.title_fr, objective_fr = excluded.objective_fr, difficulty = excluded.difficulty, est_minutes = excluded.est_minutes, kind = excluded.kind, position = excluded.position;
insert into public.lesson_contents (lesson_id, content) values ('m1l4', '{"steps":[{"kind":"explain","text":"س et ش ont des « dents » ; ص et ض ont une boucle. ص et ض sont des lettres emphatiques : elles se prononcent avec l’arrière de la langue relevé, ce qui rend le son plus grave."},{"kind":"letter","letterId":"sin"},{"kind":"letter","letterId":"shin"},{"kind":"letter","letterId":"sad"},{"kind":"letter","letterId":"dad"},{"kind":"tip","text":"Emphatique = son « plein » et grave. Comparez س (s clair) et ص (s grave) : la différence change le sens des mots."}],"exercises":[{"id":"m1l4-listen-sin","type":"choice","format":"listen","prompt":"Écoutez puis choisissez la lettre entendue","options":[{"id":"sin","ar":"س"},{"id":"zay","ar":"ز","why":"ز est zāy : « z » comme dans « zéro ». Repère visuel : un point au-dessus."},{"id":"ha","ar":"ه","why":"ه est hā’ : « h » léger et expiré, comme l’anglais « hello ». Repère visuel : aucun point."},{"id":"shin","ar":"ش","why":"ش est shīn : « ch » comme dans « chat ». Repère visuel : trois points au-dessus."}],"answer":"sin","explanation":"س se nomme sīn (سِين) et se transcrit « s » : « s » comme dans « sel ». Repère visuel : aucun point.","audio":"letter:sin","textFallback":"Quelle lettre se prononce « s » comme dans « sel » ?","reviewKey":"letter:sin"},{"id":"m1l4-name-sin","type":"choice","format":"visual","prompt":"Quelle lettre s''appelle « sīn » ?","options":[{"id":"nun","ar":"ن","why":"ن est nūn : « n » comme dans « nez ». Repère visuel : un point au-dessus."},{"id":"sad","ar":"ص","why":"ص est ṣād : « s » emphatique : bouche arrondie, arrière de la langue relevé, son plus grave. Repère visuel : aucun point."},{"id":"sin","ar":"س"},{"id":"shin","ar":"ش","why":"ش est shīn : « ch » comme dans « chat ». Repère visuel : trois points au-dessus."}],"answer":"sin","explanation":"س se nomme sīn (سِين) et se transcrit « s » : « s » comme dans « sel ». Repère visuel : aucun point.","reviewKey":"letter:sin"},{"id":"m1l4-listen-shin","type":"choice","format":"listen","prompt":"Écoutez puis choisissez la lettre entendue","options":[{"id":"sin","ar":"س","why":"س est sīn : « s » comme dans « sel ». Repère visuel : aucun point."},{"id":"tta","ar":"ط","why":"ط est ṭā’ : « t » emphatique : son grave, arrière de la langue relevé. Repère visuel : aucun point."},{"id":"kha","ar":"خ","why":"خ est khā’ : « r » raclé au fond du palais, comme la « jota » espagnole ou le « ch » allemand de « Bach ». Repère visuel : un point au-dessus."},{"id":"shin","ar":"ش"}],"answer":"shin","explanation":"ش se nomme shīn (شِين) et se transcrit « sh » : « ch » comme dans « chat ». Repère visuel : trois points au-dessus.","audio":"letter:shin","textFallback":"Quelle lettre se prononce « ch » comme dans « chat » ?","reviewKey":"letter:shin"},{"id":"m1l4-name-shin","type":"choice","format":"visual","prompt":"Quelle lettre s''appelle « shīn » ?","options":[{"id":"ya","ar":"ي","why":"ي est yā’ : « y » comme dans « yaourt », ou voyelle longue « î ». Repère visuel : deux points en dessous."},{"id":"shin","ar":"ش"},{"id":"sin","ar":"س","why":"س est sīn : « s » comme dans « sel ». Repère visuel : aucun point."},{"id":"sad","ar":"ص","why":"ص est ṣād : « s » emphatique : bouche arrondie, arrière de la langue relevé, son plus grave. Repère visuel : aucun point."}],"answer":"shin","explanation":"ش se nomme shīn (شِين) et se transcrit « sh » : « ch » comme dans « chat ». Repère visuel : trois points au-dessus.","reviewKey":"letter:shin"},{"id":"m1l4-listen-sad","type":"choice","format":"listen","prompt":"Écoutez puis choisissez la lettre entendue","options":[{"id":"ha","ar":"ه","why":"ه est hā’ : « h » léger et expiré, comme l’anglais « hello ». Repère visuel : aucun point."},{"id":"sad","ar":"ص"},{"id":"kaf","ar":"ك","why":"ك est kāf : « k » comme dans « kilo ». Repère visuel : aucun point."},{"id":"dad","ar":"ض","why":"ض est ḍād : « d » emphatique, son grave et plein ; lettre réputée propre à l’arabe. Repère visuel : un point au-dessus."}],"answer":"sad","explanation":"ص se nomme ṣād (صَاد) et se transcrit « ṣ » : « s » emphatique : bouche arrondie, arrière de la langue relevé, son plus grave. Repère visuel : aucun point.","audio":"letter:sad","textFallback":"Quelle lettre se prononce « s » emphatique : bouche arrondie, arrière de la langue relevé, son plus grave ?","reviewKey":"letter:sad"},{"id":"m1l4-name-sad","type":"choice","format":"visual","prompt":"Quelle lettre s''appelle « ṣād » ?","options":[{"id":"jim","ar":"ج","why":"ج est jīm : « dj » comme dans « djinn ». Repère visuel : un point en dessous."},{"id":"dad","ar":"ض","why":"ض est ḍād : « d » emphatique, son grave et plein ; lettre réputée propre à l’arabe. Repère visuel : un point au-dessus."},{"id":"alif","ar":"ا","why":"ا est alif : pas de son propre : support de la voyelle longue « â » ou de la hamza (attaque de voyelle). Repère visuel : aucun point."},{"id":"sad","ar":"ص"}],"answer":"sad","explanation":"ص se nomme ṣād (صَاد) et se transcrit « ṣ » : « s » emphatique : bouche arrondie, arrière de la langue relevé, son plus grave. Repère visuel : aucun point.","reviewKey":"letter:sad"},{"id":"m1l4-listen-dad","type":"choice","format":"listen","prompt":"Écoutez puis choisissez la lettre entendue","options":[{"id":"sad","ar":"ص","why":"ص est ṣād : « s » emphatique : bouche arrondie, arrière de la langue relevé, son plus grave. Repère visuel : aucun point."},{"id":"sin","ar":"س","why":"س est sīn : « s » comme dans « sel ». Repère visuel : aucun point."},{"id":"dad","ar":"ض"},{"id":"zza","ar":"ظ","why":"ظ est ẓā’ : « th » de « this » prononcé de façon emphatique (grave). Repère visuel : un point au-dessus."}],"answer":"dad","explanation":"ض se nomme ḍād (ضَاد) et se transcrit « ḍ » : « d » emphatique, son grave et plein ; lettre réputée propre à l’arabe. Repère visuel : un point au-dessus.","audio":"letter:dad","textFallback":"Quelle lettre se prononce « d » emphatique, son grave et plein ; lettre réputée propre à l’arabe ?","reviewKey":"letter:dad"},{"id":"m1l4-name-dad","type":"choice","format":"visual","prompt":"Quelle lettre s''appelle « ḍād » ?","options":[{"id":"tta","ar":"ط","why":"ط est ṭā’ : « t » emphatique : son grave, arrière de la langue relevé. Repère visuel : aucun point."},{"id":"dad","ar":"ض"},{"id":"waw","ar":"و","why":"و est wāw : « w » comme dans « watt », ou voyelle longue « oû ». Repère visuel : aucun point."},{"id":"sad","ar":"ص","why":"ص est ṣād : « s » emphatique : bouche arrondie, arrière de la langue relevé, son plus grave. Repère visuel : aucun point."}],"answer":"dad","explanation":"ض se nomme ḍād (ضَاد) et se transcrit « ḍ » : « d » emphatique, son grave et plein ; lettre réputée propre à l’arabe. Repère visuel : un point au-dessus.","reviewKey":"letter:dad"},{"id":"m1l4-sound-sin","type":"choice","format":"mcq","prompt":"Quel son correspond à cette lettre ?","options":[{"id":"zay","label":"« z »","why":"ز est zāy : « z » comme dans « zéro ». Repère visuel : un point au-dessus."},{"id":"shin","label":"« sh »","why":"ش est shīn : « ch » comme dans « chat ». Repère visuel : trois points au-dessus."},{"id":"sin","label":"« s »"},{"id":"kha","label":"« kh »","why":"خ est khā’ : « r » raclé au fond du palais, comme la « jota » espagnole ou le « ch » allemand de « Bach ». Repère visuel : un point au-dessus."}],"answer":"sin","explanation":"س se nomme sīn (سِين) et se transcrit « s » : « s » comme dans « sel ». Repère visuel : aucun point.","ar":"س","reviewKey":"letter:sin"},{"id":"m1l4-sound-shin","type":"choice","format":"mcq","prompt":"Quel son correspond à cette lettre ?","options":[{"id":"sin","label":"« s »","why":"س est sīn : « s » comme dans « sel ». Repère visuel : aucun point."},{"id":"tha","label":"« th »","why":"ث est thā’ : « th » de l’anglais « think » : langue entre les dents, sans voix. Repère visuel : trois points au-dessus."},{"id":"shin","label":"« sh »"},{"id":"sad","label":"« ṣ »","why":"ص est ṣād : « s » emphatique : bouche arrondie, arrière de la langue relevé, son plus grave. Repère visuel : aucun point."}],"answer":"shin","explanation":"ش se nomme shīn (شِين) et se transcrit « sh » : « ch » comme dans « chat ». Repère visuel : trois points au-dessus.","ar":"ش","reviewKey":"letter:shin"},{"id":"m1l4-match","type":"match","prompt":"Associez chaque lettre à son nom","pairs":[{"left":{"id":"l-sin","ar":"س"},"right":{"id":"r-sin","label":"sīn"}},{"left":{"id":"l-shin","ar":"ش"},"right":{"id":"r-shin","label":"shīn"}},{"left":{"id":"l-sad","ar":"ص"},"right":{"id":"r-sad","label":"ṣād"}},{"left":{"id":"l-dad","ar":"ض"},"right":{"id":"r-dad","label":"ḍād"}}],"explanation":"س = sīn · ش = shīn · ص = ṣād · ض = ḍād"}],"summary":["س — sīn : « s » (aucun point)","ش — shīn : « sh » (trois points au-dessus)","ص — ṣād : « ṣ » (aucun point)","ض — ḍād : « ḍ » (un point au-dessus)"]}'::jsonb) on conflict (lesson_id) do update set content = excluded.content, version = public.lesson_contents.version + 1, updated_at = now();
