insert into public.lesson_contents (lesson_id, content) values ('m1l5', '{"steps":[{"kind":"explain","text":"ط et ظ sont aussi emphatiques. ع et غ partagent le même tracé : ع est un son de gorge sans équivalent en français, غ ressemble au « r » parisien."},{"kind":"letter","letterId":"tta"},{"kind":"letter","letterId":"zza"},{"kind":"letter","letterId":"ayn"},{"kind":"letter","letterId":"ghayn"},{"kind":"tip","text":"ع ne se transcrit pas comme une voyelle : c’est une vraie consonne. Écoutez-la souvent et répétez lentement."}],"exercises":[{"id":"m1l5-listen-tta","type":"choice","format":"listen","prompt":"Écoutez puis choisissez la lettre entendue","options":[{"id":"ra","ar":"ر","why":"ر est rā’ : « r » roulé du bout de la langue, comme en espagnol. Repère visuel : aucun point."},{"id":"tta","ar":"ط"},{"id":"nun","ar":"ن","why":"ن est nūn : « n » comme dans « nez ». Repère visuel : un point au-dessus."},{"id":"zza","ar":"ظ","why":"ظ est ẓā’ : « th » de « this » prononcé de façon emphatique (grave). Repère visuel : un point au-dessus."}],"answer":"tta","explanation":"ط se nomme ṭā’ (طَاء) et se transcrit « ṭ » : « t » emphatique : son grave, arrière de la langue relevé. Repère visuel : aucun point.","audio":"letter:tta","textFallback":"Quelle lettre se prononce « t » emphatique : son grave, arrière de la langue relevé ?","reviewKey":"letter:tta"},{"id":"m1l5-name-tta","type":"choice","format":"visual","prompt":"Quelle lettre s''appelle « ṭā’ » ?","options":[{"id":"zza","ar":"ظ","why":"ظ est ẓā’ : « th » de « this » prononcé de façon emphatique (grave). Repère visuel : un point au-dessus."},{"id":"tta","ar":"ط"},{"id":"ra","ar":"ر","why":"ر est rā’ : « r » roulé du bout de la langue, comme en espagnol. Repère visuel : aucun point."},{"id":"nun","ar":"ن","why":"ن est nūn : « n » comme dans « nez ». Repère visuel : un point au-dessus."}],"answer":"tta","explanation":"ط se nomme ṭā’ (طَاء) et se transcrit « ṭ » : « t » emphatique : son grave, arrière de la langue relevé. Repère visuel : aucun point.","reviewKey":"letter:tta"},{"id":"m1l5-listen-zza","type":"choice","format":"listen","prompt":"Écoutez puis choisissez la lettre entendue","options":[{"id":"ta","ar":"ت","why":"ت est tā’ : « t » comme dans « table ». Repère visuel : deux points au-dessus."},{"id":"mim","ar":"م","why":"م est mīm : « m » comme dans « mer ». Repère visuel : aucun point."},{"id":"zza","ar":"ظ"},{"id":"tta","ar":"ط","why":"ط est ṭā’ : « t » emphatique : son grave, arrière de la langue relevé. Repère visuel : aucun point."}],"answer":"zza","explanation":"ظ se nomme ẓā’ (ظَاء) et se transcrit « ẓ » : « th » de « this » prononcé de façon emphatique (grave). Repère visuel : un point au-dessus.","audio":"letter:zza","textFallback":"Quelle lettre se prononce « th » de « this » prononcé de façon emphatique (grave) ?","reviewKey":"letter:zza"},{"id":"m1l5-name-zza","type":"choice","format":"visual","prompt":"Quelle lettre s''appelle « ẓā’ » ?","options":[{"id":"zza","ar":"ظ"},{"id":"tta","ar":"ط","why":"ط est ṭā’ : « t » emphatique : son grave, arrière de la langue relevé. Repère visuel : aucun point."},{"id":"sad","ar":"ص","why":"ص est ṣād : « s » emphatique : bouche arrondie, arrière de la langue relevé, son plus grave. Repère visuel : aucun point."},{"id":"shin","ar":"ش","why":"ش est shīn : « ch » comme dans « chat ». Repère visuel : trois points au-dessus."}],"answer":"zza","explanation":"ظ se nomme ẓā’ (ظَاء) et se transcrit « ẓ » : « th » de « this » prononcé de façon emphatique (grave). Repère visuel : un point au-dessus.","reviewKey":"letter:zza"},{"id":"m1l5-listen-ayn","type":"choice","format":"listen","prompt":"Écoutez puis choisissez la lettre entendue","options":[{"id":"tha","ar":"ث","why":"ث est thā’ : « th » de l’anglais « think » : langue entre les dents, sans voix. Repère visuel : trois points au-dessus."},{"id":"ghayn","ar":"غ","why":"غ est ghayn : « r » grasseyé comme le « r » parisien de « Paris ». Repère visuel : un point au-dessus."},{"id":"ayn","ar":"ع"},{"id":"hha","ar":"ح","why":"ح est ḥā’ : « h » soufflé et serré au milieu de la gorge, comme pour embuer une vitre très fort. Repère visuel : aucun point."}],"answer":"ayn","explanation":"ع se nomme ʿayn (عَيْن) et se transcrit « ʿ » : contraction sonore du milieu de la gorge ; aucun équivalent en français. Repère visuel : aucun point.","audio":"letter:ayn","textFallback":"Quelle lettre se prononce contraction sonore du milieu de la gorge ; aucun équivalent en français ?","reviewKey":"letter:ayn"},{"id":"m1l5-name-ayn","type":"choice","format":"visual","prompt":"Quelle lettre s''appelle « ʿayn » ?","options":[{"id":"ayn","ar":"ع"},{"id":"ghayn","ar":"غ","why":"غ est ghayn : « r » grasseyé comme le « r » parisien de « Paris ». Repère visuel : un point au-dessus."},{"id":"dad","ar":"ض","why":"ض est ḍād : « d » emphatique, son grave et plein ; lettre réputée propre à l’arabe. Repère visuel : un point au-dessus."},{"id":"kaf","ar":"ك","why":"ك est kāf : « k » comme dans « kilo ». Repère visuel : aucun point."}],"answer":"ayn","explanation":"ع se nomme ʿayn (عَيْن) et se transcrit « ʿ » : contraction sonore du milieu de la gorge ; aucun équivalent en français. Repère visuel : aucun point.","reviewKey":"letter:ayn"},{"id":"m1l5-listen-ghayn","type":"choice","format":"listen","prompt":"Écoutez puis choisissez la lettre entendue","options":[{"id":"ayn","ar":"ع","why":"ع est ʿayn : contraction sonore du milieu de la gorge ; aucun équivalent en français. Repère visuel : aucun point."},{"id":"waw","ar":"و","why":"و est wāw : « w » comme dans « watt », ou voyelle longue « oû ». Repère visuel : aucun point."},{"id":"ghayn","ar":"غ"},{"id":"kaf","ar":"ك","why":"ك est kāf : « k » comme dans « kilo ». Repère visuel : aucun point."}],"answer":"ghayn","explanation":"غ se nomme ghayn (غَيْن) et se transcrit « gh » : « r » grasseyé comme le « r » parisien de « Paris ». Repère visuel : un point au-dessus.","audio":"letter:ghayn","textFallback":"Quelle lettre se prononce « r » grasseyé comme le « r » parisien de « Paris » ?","reviewKey":"letter:ghayn"},{"id":"m1l5-name-ghayn","type":"choice","format":"visual","prompt":"Quelle lettre s''appelle « ghayn » ?","options":[{"id":"ra","ar":"ر","why":"ر est rā’ : « r » roulé du bout de la langue, comme en espagnol. Repère visuel : aucun point."},{"id":"ghayn","ar":"غ"},{"id":"qaf","ar":"ق","why":"ق est qāf : « k » prononcé très au fond, contre la luette. Repère visuel : deux points au-dessus."},{"id":"ayn","ar":"ع","why":"ع est ʿayn : contraction sonore du milieu de la gorge ; aucun équivalent en français. Repère visuel : aucun point."}],"answer":"ghayn","explanation":"غ se nomme ghayn (غَيْن) et se transcrit « gh » : « r » grasseyé comme le « r » parisien de « Paris ». Repère visuel : un point au-dessus.","reviewKey":"letter:ghayn"},{"id":"m1l5-sound-tta","type":"choice","format":"mcq","prompt":"Quel son correspond à cette lettre ?","options":[{"id":"ayn","label":"« ʿ »","why":"ع est ʿayn : contraction sonore du milieu de la gorge ; aucun équivalent en français. Repère visuel : aucun point."},{"id":"zza","label":"« ẓ »","why":"ظ est ẓā’ : « th » de « this » prononcé de façon emphatique (grave). Repère visuel : un point au-dessus."},{"id":"tta","label":"« ṭ »"},{"id":"sad","label":"« ṣ »","why":"ص est ṣād : « s » emphatique : bouche arrondie, arrière de la langue relevé, son plus grave. Repère visuel : aucun point."}],"answer":"tta","explanation":"ط se nomme ṭā’ (طَاء) et se transcrit « ṭ » : « t » emphatique : son grave, arrière de la langue relevé. Repère visuel : aucun point.","ar":"ط","reviewKey":"letter:tta"},{"id":"m1l5-sound-zza","type":"choice","format":"mcq","prompt":"Quel son correspond à cette lettre ?","options":[{"id":"dal","label":"« d »","why":"د est dāl : « d » comme dans « dos ». Repère visuel : aucun point."},{"id":"zza","label":"« ẓ »"},{"id":"tta","label":"« ṭ »","why":"ط est ṭā’ : « t » emphatique : son grave, arrière de la langue relevé. Repère visuel : aucun point."},{"id":"jim","label":"« j »","why":"ج est jīm : « dj » comme dans « djinn ». Repère visuel : un point en dessous."}],"answer":"zza","explanation":"ظ se nomme ẓā’ (ظَاء) et se transcrit « ẓ » : « th » de « this » prononcé de façon emphatique (grave). Repère visuel : un point au-dessus.","ar":"ظ","reviewKey":"letter:zza"},{"id":"m1l5-match","type":"match","prompt":"Associez chaque lettre à son nom","pairs":[{"left":{"id":"l-tta","ar":"ط"},"right":{"id":"r-tta","label":"ṭā’"}},{"left":{"id":"l-zza","ar":"ظ"},"right":{"id":"r-zza","label":"ẓā’"}},{"left":{"id":"l-ayn","ar":"ع"},"right":{"id":"r-ayn","label":"ʿayn"}},{"left":{"id":"l-ghayn","ar":"غ"},"right":{"id":"r-ghayn","label":"ghayn"}}],"explanation":"ط = ṭā’ · ظ = ẓā’ · ع = ʿayn · غ = ghayn"}],"summary":["ط — ṭā’ : « ṭ » (aucun point)","ظ — ẓā’ : « ẓ » (un point au-dessus)","ع — ʿayn : « ʿ » (aucun point)","غ — ghayn : « gh » (un point au-dessus)"]}'::jsonb) on conflict (lesson_id) do update set content = excluded.content, version = public.lesson_contents.version + 1, updated_at = now();
insert into public.lessons (id, module_id, position, title_fr, objective_fr, difficulty, est_minutes, kind, published) values ('m1l6', 1, 6, 'Fā’, qāf, kāf et lām', 'Reconnaître, nommer et prononcer : ف ق ك ل', 2, 6, 'lesson', true) on conflict (id) do update set title_fr = excluded.title_fr, objective_fr = excluded.objective_fr, difficulty = excluded.difficulty, est_minutes = excluded.est_minutes, kind = excluded.kind, position = excluded.position;
insert into public.lesson_contents (lesson_id, content) values ('m1l6', '{"steps":[{"kind":"explain","text":"ف et ق ont une tête ronde : ف un point, ق deux points. ق se prononce beaucoup plus au fond de la bouche que ك."},{"kind":"letter","letterId":"fa"},{"kind":"letter","letterId":"qaf"},{"kind":"letter","letterId":"kaf"},{"kind":"letter","letterId":"lam"},{"kind":"tip","text":"Distinguez bien ق (k profond, contre la luette) et ك (k français). C’est une des oppositions les plus fréquentes du Coran."}],"exercises":[{"id":"m1l6-listen-fa","type":"choice","format":"listen","prompt":"Écoutez puis choisissez la lettre entendue","options":[{"id":"qaf","ar":"ق","why":"ق est qāf : « k » prononcé très au fond, contre la luette. Repère visuel : deux points au-dessus."},{"id":"sad","ar":"ص","why":"ص est ṣād : « s » emphatique : bouche arrondie, arrière de la langue relevé, son plus grave. Repère visuel : aucun point."},{"id":"fa","ar":"ف"},{"id":"shin","ar":"ش","why":"ش est shīn : « ch » comme dans « chat ». Repère visuel : trois points au-dessus."}],"answer":"fa","explanation":"ف se nomme fā’ (فَاء) et se transcrit « f » : « f » comme dans « fil ». Repère visuel : un point au-dessus.","audio":"letter:fa","textFallback":"Quelle lettre se prononce « f » comme dans « fil » ?","reviewKey":"letter:fa"},{"id":"m1l6-name-fa","type":"choice","format":"visual","prompt":"Quelle lettre s''appelle « fā’ » ?","options":[{"id":"lam","ar":"ل","why":"ل est lām : « l » comme dans « lune ». Repère visuel : aucun point."},{"id":"qaf","ar":"ق","why":"ق est qāf : « k » prononcé très au fond, contre la luette. Repère visuel : deux points au-dessus."},{"id":"fa","ar":"ف"},{"id":"ba","ar":"ب","why":"ب est bā’ : « b » comme dans « bateau ». Repère visuel : un point en dessous."}],"answer":"fa","explanation":"ف se nomme fā’ (فَاء) et se transcrit « f » : « f » comme dans « fil ». Repère visuel : un point au-dessus.","reviewKey":"letter:fa"},{"id":"m1l6-listen-qaf","type":"choice","format":"listen","prompt":"Écoutez puis choisissez la lettre entendue","options":[{"id":"mim","ar":"م","why":"م est mīm : « m » comme dans « mer ». Repère visuel : aucun point."},{"id":"fa","ar":"ف","why":"ف est fā’ : « f » comme dans « fil ». Repère visuel : un point au-dessus."},{"id":"qaf","ar":"ق"},{"id":"ya","ar":"ي","why":"ي est yā’ : « y » comme dans « yaourt », ou voyelle longue « î ». Repère visuel : deux points en dessous."}],"answer":"qaf","explanation":"ق se nomme qāf (قَاف) et se transcrit « q » : « k » prononcé très au fond, contre la luette. Repère visuel : deux points au-dessus.","audio":"letter:qaf","textFallback":"Quelle lettre se prononce « k » prononcé très au fond, contre la luette ?","reviewKey":"letter:qaf"},{"id":"m1l6-name-qaf","type":"choice","format":"visual","prompt":"Quelle lettre s''appelle « qāf » ?","options":[{"id":"fa","ar":"ف","why":"ف est fā’ : « f » comme dans « fil ». Repère visuel : un point au-dessus."},{"id":"qaf","ar":"ق"},{"id":"lam","ar":"ل","why":"ل est lām : « l » comme dans « lune ». Repère visuel : aucun point."},{"id":"mim","ar":"م","why":"م est mīm : « m » comme dans « mer ». Repère visuel : aucun point."}],"answer":"qaf","explanation":"ق se nomme qāf (قَاف) et se transcrit « q » : « k » prononcé très au fond, contre la luette. Repère visuel : deux points au-dessus.","reviewKey":"letter:qaf"},{"id":"m1l6-listen-kaf","type":"choice","format":"listen","prompt":"Écoutez puis choisissez la lettre entendue","options":[{"id":"kaf","ar":"ك"},{"id":"ghayn","ar":"غ","why":"غ est ghayn : « r » grasseyé comme le « r » parisien de « Paris ». Repère visuel : un point au-dessus."},{"id":"fa","ar":"ف","why":"ف est fā’ : « f » comme dans « fil ». Repère visuel : un point au-dessus."},{"id":"qaf","ar":"ق","why":"ق est qāf : « k » prononcé très au fond, contre la luette. Repère visuel : deux points au-dessus."}],"answer":"kaf","explanation":"ك se nomme kāf (كَاف) et se transcrit « k » : « k » comme dans « kilo ». Repère visuel : aucun point.","audio":"letter:kaf","textFallback":"Quelle lettre se prononce « k » comme dans « kilo » ?","reviewKey":"letter:kaf"},{"id":"m1l6-name-kaf","type":"choice","format":"visual","prompt":"Quelle lettre s''appelle « kāf » ?","options":[{"id":"dad","ar":"ض","why":"ض est ḍād : « d » emphatique, son grave et plein ; lettre réputée propre à l’arabe. Repère visuel : un point au-dessus."},{"id":"kaf","ar":"ك"},{"id":"nun","ar":"ن","why":"ن est nūn : « n » comme dans « nez ». Repère visuel : un point au-dessus."},{"id":"alif","ar":"ا","why":"ا est alif : pas de son propre : support de la voyelle longue « â » ou de la hamza (attaque de voyelle). Repère visuel : aucun point."}],"answer":"kaf","explanation":"ك se nomme kāf (كَاف) et se transcrit « k » : « k » comme dans « kilo ». Repère visuel : aucun point.","reviewKey":"letter:kaf"},{"id":"m1l6-listen-lam","type":"choice","format":"listen","prompt":"Écoutez puis choisissez la lettre entendue","options":[{"id":"lam","ar":"ل"},{"id":"ha","ar":"ه","why":"ه est hā’ : « h » léger et expiré, comme l’anglais « hello ». Repère visuel : aucun point."},{"id":"sin","ar":"س","why":"س est sīn : « s » comme dans « sel ». Repère visuel : aucun point."},{"id":"ba","ar":"ب","why":"ب est bā’ : « b » comme dans « bateau ». Repère visuel : un point en dessous."}],"answer":"lam","explanation":"ل se nomme lām (لَام) et se transcrit « l » : « l » comme dans « lune ». Repère visuel : aucun point.","audio":"letter:lam","textFallback":"Quelle lettre se prononce « l » comme dans « lune » ?","reviewKey":"letter:lam"},{"id":"m1l6-name-lam","type":"choice","format":"visual","prompt":"Quelle lettre s''appelle « lām » ?","options":[{"id":"lam","ar":"ل"},{"id":"alif","ar":"ا","why":"ا est alif : pas de son propre : support de la voyelle longue « â » ou de la hamza (attaque de voyelle). Repère visuel : aucun point."},{"id":"hha","ar":"ح","why":"ح est ḥā’ : « h » soufflé et serré au milieu de la gorge, comme pour embuer une vitre très fort. Repère visuel : aucun point."},{"id":"mim","ar":"م","why":"م est mīm : « m » comme dans « mer ». Repère visuel : aucun point."}],"answer":"lam","explanation":"ل se nomme lām (لَام) et se transcrit « l » : « l » comme dans « lune ». Repère visuel : aucun point.","reviewKey":"letter:lam"},{"id":"m1l6-sound-fa","type":"choice","format":"mcq","prompt":"Quel son correspond à cette lettre ?","options":[{"id":"zay","label":"« z »","why":"ز est zāy : « z » comme dans « zéro ». Repère visuel : un point au-dessus."},{"id":"fa","label":"« f »"},{"id":"qaf","label":"« q »","why":"ق est qāf : « k » prononcé très au fond, contre la luette. Repère visuel : deux points au-dessus."},{"id":"ya","label":"« y / ī »","why":"ي est yā’ : « y » comme dans « yaourt », ou voyelle longue « î ». Repère visuel : deux points en dessous."}],"answer":"fa","explanation":"ف se nomme fā’ (فَاء) et se transcrit « f » : « f » comme dans « fil ». Repère visuel : un point au-dessus.","ar":"ف","reviewKey":"letter:fa"},{"id":"m1l6-sound-qaf","type":"choice","format":"mcq","prompt":"Quel son correspond à cette lettre ?","options":[{"id":"zza","label":"« ẓ »","why":"ظ est ẓā’ : « th » de « this » prononcé de façon emphatique (grave). Repère visuel : un point au-dessus."},{"id":"fa","label":"« f »","why":"ف est fā’ : « f » comme dans « fil ». Repère visuel : un point au-dessus."},{"id":"shin","label":"« sh »","why":"ش est shīn : « ch » comme dans « chat ». Repère visuel : trois points au-dessus."},{"id":"qaf","label":"« q »"}],"answer":"qaf","explanation":"ق se nomme qāf (قَاف) et se transcrit « q » : « k » prononcé très au fond, contre la luette. Repère visuel : deux points au-dessus.","ar":"ق","reviewKey":"letter:qaf"},{"id":"m1l6-match","type":"match","prompt":"Associez chaque lettre à son nom","pairs":[{"left":{"id":"l-fa","ar":"ف"},"right":{"id":"r-fa","label":"fā’"}},{"left":{"id":"l-qaf","ar":"ق"},"right":{"id":"r-qaf","label":"qāf"}},{"left":{"id":"l-kaf","ar":"ك"},"right":{"id":"r-kaf","label":"kāf"}},{"left":{"id":"l-lam","ar":"ل"},"right":{"id":"r-lam","label":"lām"}}],"explanation":"ف = fā’ · ق = qāf · ك = kāf · ل = lām"}],"summary":["ف — fā’ : « f » (un point au-dessus)","ق — qāf : « q » (deux points au-dessus)","ك — kāf : « k » (aucun point)","ل — lām : « l » (aucun point)"]}'::jsonb) on conflict (lesson_id) do update set content = excluded.content, version = public.lesson_contents.version + 1, updated_at = now();
insert into public.lessons (id, module_id, position, title_fr, objective_fr, difficulty, est_minutes, kind, published) values ('m1l7', 1, 7, 'Mīm, nūn, hā’, wāw et yā’', 'Reconnaître, nommer et prononcer : م ن ه و ي', 2, 6, 'lesson', true) on conflict (id) do update set title_fr = excluded.title_fr, objective_fr = excluded.objective_fr, difficulty = excluded.difficulty, est_minutes = excluded.est_minutes, kind = excluded.kind, position = excluded.position;
insert into public.lesson_contents (lesson_id, content) values ('m1l7', '{"steps":[{"kind":"explain","text":"Dernier groupe. ه est un « h » léger, à ne pas confondre avec ح (souffle serré). و et ي servent aussi à écrire les voyelles longues « oû » et « î »."},{"kind":"letter","letterId":"mim"},{"kind":"letter","letterId":"nun"},{"kind":"letter","letterId":"ha"},{"kind":"letter","letterId":"waw"},{"kind":"letter","letterId":"ya"},{"kind":"tip","text":"ه (léger) ≠ ح (serré). Si vous hésitez, comparez les deux enregistrements côte à côte."}],"exercises":[{"id":"m1l7-listen-mim","type":"choice","format":"listen","prompt":"Écoutez puis choisissez la lettre entendue","options":[{"id":"qaf","ar":"ق","why":"ق est qāf : « k » prononcé très au fond, contre la luette. Repère visuel : deux points au-dessus."},{"id":"ayn","ar":"ع","why":"ع est ʿayn : contraction sonore du milieu de la gorge ; aucun équivalent en français. Repère visuel : aucun point."},{"id":"mim","ar":"م"},{"id":"waw","ar":"و","why":"و est wāw : « w » comme dans « watt », ou voyelle longue « oû ». Repère visuel : aucun point."}],"answer":"mim","explanation":"م se nomme mīm (مِيم) et se transcrit « m » : « m » comme dans « mer ». Repère visuel : aucun point.","audio":"letter:mim","textFallback":"Quelle lettre se prononce « m » comme dans « mer » ?","reviewKey":"letter:mim"},{"id":"m1l7-name-mim","type":"choice","format":"visual","prompt":"Quelle lettre s''appelle « mīm » ?","options":[{"id":"mim","ar":"م"},{"id":"jim","ar":"ج","why":"ج est jīm : « dj » comme dans « djinn ». Repère visuel : un point en dessous."},{"id":"alif","ar":"ا","why":"ا est alif : pas de son propre : support de la voyelle longue « â » ou de la hamza (attaque de voyelle). Repère visuel : aucun point."},{"id":"shin","ar":"ش","why":"ش est shīn : « ch » comme dans « chat ». Repère visuel : trois points au-dessus."}],"answer":"mim","explanation":"م se nomme mīm (مِيم) et se transcrit « m » : « m » comme dans « mer ». Repère visuel : aucun point.","reviewKey":"letter:mim"},{"id":"m1l7-listen-nun","type":"choice","format":"listen","prompt":"Écoutez puis choisissez la lettre entendue","options":[{"id":"ta","ar":"ت","why":"ت est tā’ : « t » comme dans « table ». Repère visuel : deux points au-dessus."},{"id":"nun","ar":"ن"},{"id":"ayn","ar":"ع","why":"ع est ʿayn : contraction sonore du milieu de la gorge ; aucun équivalent en français. Repère visuel : aucun point."},{"id":"ra","ar":"ر","why":"ر est rā’ : « r » roulé du bout de la langue, comme en espagnol. Repère visuel : aucun point."}],"answer":"nun","explanation":"ن se nomme nūn (نُون) et se transcrit « n » : « n » comme dans « nez ». Repère visuel : un point au-dessus.","audio":"letter:nun","textFallback":"Quelle lettre se prononce « n » comme dans « nez » ?","reviewKey":"letter:nun"},{"id":"m1l7-name-nun","type":"choice","format":"visual","prompt":"Quelle lettre s''appelle « nūn » ?","options":[{"id":"jim","ar":"ج","why":"ج est jīm : « dj » comme dans « djinn ». Repère visuel : un point en dessous."},{"id":"lam","ar":"ل","why":"ل est lām : « l » comme dans « lune ». Repère visuel : aucun point."},{"id":"nun","ar":"ن"},{"id":"kha","ar":"خ","why":"خ est khā’ : « r » raclé au fond du palais, comme la « jota » espagnole ou le « ch » allemand de « Bach ». Repère visuel : un point au-dessus."}],"answer":"nun","explanation":"ن se nomme nūn (نُون) et se transcrit « n » : « n » comme dans « nez ». Repère visuel : un point au-dessus.","reviewKey":"letter:nun"},{"id":"m1l7-listen-ha","type":"choice","format":"listen","prompt":"Écoutez puis choisissez la lettre entendue","options":[{"id":"ha","ar":"ه"},{"id":"dal","ar":"د","why":"د est dāl : « d » comme dans « dos ». Repère visuel : aucun point."},{"id":"sad","ar":"ص","why":"ص est ṣād : « s » emphatique : bouche arrondie, arrière de la langue relevé, son plus grave. Repère visuel : aucun point."},{"id":"qaf","ar":"ق","why":"ق est qāf : « k » prononcé très au fond, contre la luette. Repère visuel : deux points au-dessus."}],"answer":"ha","explanation":"ه se nomme hā’ (هَاء) et se transcrit « h » : « h » léger et expiré, comme l’anglais « hello ». Repère visuel : aucun point.","audio":"letter:ha","textFallback":"Quelle lettre se prononce « h » léger et expiré, comme l’anglais « hello » ?","reviewKey":"letter:ha"},{"id":"m1l7-name-ha","type":"choice","format":"visual","prompt":"Quelle lettre s''appelle « hā’ » ?","options":[{"id":"tha","ar":"ث","why":"ث est thā’ : « th » de l’anglais « think » : langue entre les dents, sans voix. Repère visuel : trois points au-dessus."},{"id":"tta","ar":"ط","why":"ط est ṭā’ : « t » emphatique : son grave, arrière de la langue relevé. Repère visuel : aucun point."},{"id":"ya","ar":"ي","why":"ي est yā’ : « y » comme dans « yaourt », ou voyelle longue « î ». Repère visuel : deux points en dessous."},{"id":"ha","ar":"ه"}],"answer":"ha","explanation":"ه se nomme hā’ (هَاء) et se transcrit « h » : « h » léger et expiré, comme l’anglais « hello ». Repère visuel : aucun point.","reviewKey":"letter:ha"},{"id":"m1l7-listen-waw","type":"choice","format":"listen","prompt":"Écoutez puis choisissez la lettre entendue","options":[{"id":"sad","ar":"ص","why":"ص est ṣād : « s » emphatique : bouche arrondie, arrière de la langue relevé, son plus grave. Repère visuel : aucun point."},{"id":"ya","ar":"ي","why":"ي est yā’ : « y » comme dans « yaourt », ou voyelle longue « î ». Repère visuel : deux points en dessous."},{"id":"lam","ar":"ل","why":"ل est lām : « l » comme dans « lune ». Repère visuel : aucun point."},{"id":"waw","ar":"و"}],"answer":"waw","explanation":"و se nomme wāw (وَاو) et se transcrit « w / ū » : « w » comme dans « watt », ou voyelle longue « oû ». Repère visuel : aucun point.","audio":"letter:waw","textFallback":"Quelle lettre se prononce « w » comme dans « watt », ou voyelle longue « oû » ?","reviewKey":"letter:waw"},{"id":"m1l7-name-waw","type":"choice","format":"visual","prompt":"Quelle lettre s''appelle « wāw » ?","options":[{"id":"waw","ar":"و"},{"id":"tta","ar":"ط","why":"ط est ṭā’ : « t » emphatique : son grave, arrière de la langue relevé. Repère visuel : aucun point."},{"id":"dhal","ar":"ذ","why":"ذ est dhāl : « th » de l’anglais « this » : langue entre les dents, avec la voix. Repère visuel : un point au-dessus."},{"id":"jim","ar":"ج","why":"ج est jīm : « dj » comme dans « djinn ». Repère visuel : un point en dessous."}],"answer":"waw","explanation":"و se nomme wāw (وَاو) et se transcrit « w / ū » : « w » comme dans « watt », ou voyelle longue « oû ». Repère visuel : aucun point.","reviewKey":"letter:waw"},{"id":"m1l7-listen-ya","type":"choice","format":"listen","prompt":"Écoutez puis choisissez la lettre entendue","options":[{"id":"qaf","ar":"ق","why":"ق est qāf : « k » prononcé très au fond, contre la luette. Repère visuel : deux points au-dessus."},{"id":"ya","ar":"ي"},{"id":"ha","ar":"ه","why":"ه est hā’ : « h » léger et expiré, comme l’anglais « hello ». Repère visuel : aucun point."},{"id":"ra","ar":"ر","why":"ر est rā’ : « r » roulé du bout de la langue, comme en espagnol. Repère visuel : aucun point."}],"answer":"ya","explanation":"ي se nomme yā’ (يَاء) et se transcrit « y / ī » : « y » comme dans « yaourt », ou voyelle longue « î ». Repère visuel : deux points en dessous.","audio":"letter:ya","textFallback":"Quelle lettre se prononce « y » comme dans « yaourt », ou voyelle longue « î » ?","reviewKey":"letter:ya"},{"id":"m1l7-name-ya","type":"choice","format":"visual","prompt":"Quelle lettre s''appelle « yā’ » ?","options":[{"id":"dad","ar":"ض","why":"ض est ḍād : « d » emphatique, son grave et plein ; lettre réputée propre à l’arabe. Repère visuel : un point au-dessus."},{"id":"mim","ar":"م","why":"م est mīm : « m » comme dans « mer ». Repère visuel : aucun point."},{"id":"tta","ar":"ط","why":"ط est ṭā’ : « t » emphatique : son grave, arrière de la langue relevé. Repère visuel : aucun point."},{"id":"ya","ar":"ي"}],"answer":"ya","explanation":"ي se nomme yā’ (يَاء) et se transcrit « y / ī » : « y » comme dans « yaourt », ou voyelle longue « î ». Repère visuel : deux points en dessous.","reviewKey":"letter:ya"},{"id":"m1l7-sound-mim","type":"choice","format":"mcq","prompt":"Quel son correspond à cette lettre ?","options":[{"id":"nun","label":"« n »","why":"ن est nūn : « n » comme dans « nez ». Repère visuel : un point au-dessus."},{"id":"dal","label":"« d »","why":"د est dāl : « d » comme dans « dos ». Repère visuel : aucun point."},{"id":"mim","label":"« m »"},{"id":"tha","label":"« th »","why":"ث est thā’ : « th » de l’anglais « think » : langue entre les dents, sans voix. Repère visuel : trois points au-dessus."}],"answer":"mim","explanation":"م se nomme mīm (مِيم) et se transcrit « m » : « m » comme dans « mer ». Repère visuel : aucun point.","ar":"م","reviewKey":"letter:mim"},{"id":"m1l7-sound-nun","type":"choice","format":"mcq","prompt":"Quel son correspond à cette lettre ?","options":[{"id":"ha","label":"« h »","why":"ه est hā’ : « h » léger et expiré, comme l’anglais « hello ». Repère visuel : aucun point."},{"id":"nun","label":"« n »"},{"id":"ayn","label":"« ʿ »","why":"ع est ʿayn : contraction sonore du milieu de la gorge ; aucun équivalent en français. Repère visuel : aucun point."},{"id":"ra","label":"« r »","why":"ر est rā’ : « r » roulé du bout de la langue, comme en espagnol. Repère visuel : aucun point."}],"answer":"nun","explanation":"ن se nomme nūn (نُون) et se transcrit « n » : « n » comme dans « nez ». Repère visuel : un point au-dessus.","ar":"ن","reviewKey":"letter:nun"},{"id":"m1l7-match","type":"match","prompt":"Associez chaque lettre à son nom","pairs":[{"left":{"id":"l-mim","ar":"م"},"right":{"id":"r-mim","label":"mīm"}},{"left":{"id":"l-nun","ar":"ن"},"right":{"id":"r-nun","label":"nūn"}},{"left":{"id":"l-ha","ar":"ه"},"right":{"id":"r-ha","label":"hā’"}},{"left":{"id":"l-waw","ar":"و"},"right":{"id":"r-waw","label":"wāw"}},{"left":{"id":"l-ya","ar":"ي"},"right":{"id":"r-ya","label":"yā’"}}],"explanation":"م = mīm · ن = nūn · ه = hā’ · و = wāw · ي = yā’"}],"summary":["م — mīm : « m » (aucun point)","ن — nūn : « n » (un point au-dessus)","ه — hā’ : « h » (aucun point)","و — wāw : « w / ū » (aucun point)","ي — yā’ : « y / ī » (deux points en dessous)"]}'::jsonb) on conflict (lesson_id) do update set content = excluded.content, version = public.lesson_contents.version + 1, updated_at = now();
insert into public.lessons (id, module_id, position, title_fr, objective_fr, difficulty, est_minutes, kind, published) values ('m1l8', 1, 8, 'Les lettres qui se ressemblent', 'Distinguer les lettres de même squelette grâce aux points', 2, 7, 'lesson', true) on conflict (id) do update set title_fr = excluded.title_fr, objective_fr = excluded.objective_fr, difficulty = excluded.difficulty, est_minutes = excluded.est_minutes, kind = excluded.kind, position = excluded.position;
insert into public.lesson_contents (lesson_id, content) values ('m1l8', '{"steps":[{"kind":"explain","text":"Quinze lettres ne se distinguent que par leurs points. Voici les familles à connaître. Repérez d’abord le squelette, puis comptez les points et regardez leur position."},{"kind":"table","caption":"Familles de lettres","head":["Squelette","Lettres","Différence"],"arCols":[1],"rows":[["ب","ب ت ث","1 point dessous / 2 dessus / 3 dessus"],["ح","ج ح خ","point dessous / aucun / point dessus"],["د","د ذ","aucun / point dessus"],["ر","ر ز","aucun / point dessus"],["س","س ش","aucun / 3 points dessus"],["ص","ص ض","aucun / point dessus"],["ط","ط ظ","aucun / point dessus"],["ع","ع غ","aucun / point dessus"],["ف","ف ق","1 point / 2 points"]]},{"kind":"tip","text":"Les points sont obligatoires en arabe : un point oublié change la lettre, donc le mot."}],"exercises":[{"id":"m1l8-1","type":"choice","format":"visual","prompt":"Quelle lettre a trois points au-dessus ?","options":[{"id":"b","ar":"ت","why":"ت a deux points au-dessus."},{"id":"a","ar":"ث"},{"id":"c","ar":"ب","why":"ب a un seul point, en dessous."},{"id":"d","ar":"ن","why":"ن a un point au-dessus et un corps plus arrondi."}],"answer":"a","explanation":"ث (thā’) porte trois points au-dessus ; ش (shīn) aussi, mais avec un squelette à dents.","reviewKey":"letter:tha"},{"id":"m1l8-2","type":"choice","format":"visual","prompt":"Laquelle de ces lettres n’a aucun point ?","options":[{"id":"b","ar":"ج","why":"ج a un point en dessous (dans le creux)."},{"id":"a","ar":"ح"},{"id":"d","ar":"غ","why":"غ a un point au-dessus ; elle appartient à la famille de ع."},{"id":"c","ar":"خ","why":"خ a un point au-dessus."}],"answer":"a","explanation":"ح (ḥā’) n’a aucun point ; c’est le point qui distingue ج et خ.","reviewKey":"letter:hha"},{"id":"m1l8-3","type":"choice","format":"visual","prompt":"Quelle lettre est ḍād ?","options":[{"id":"d","ar":"ذ","why":"ذ (dhāl) est petite et ne descend pas."},{"id":"a","ar":"ض"},{"id":"b","ar":"ص","why":"ص (ṣād) a le même squelette sans point."},{"id":"c","ar":"ظ","why":"ظ (ẓā’) a un point mais un squelette à hampe verticale."}],"answer":"a","explanation":"ض = ṣād + un point au-dessus.","reviewKey":"letter:dad"},{"id":"m1l8-4","type":"choice","format":"visual","prompt":"Quelle lettre est qāf ?","options":[{"id":"c","ar":"ك","why":"ك (kāf) a un tracé anguleux, sans point."},{"id":"a","ar":"ق"},{"id":"d","ar":"و","why":"و (wāw) a une tête ronde mais aucun point et ne se lie pas."},{"id":"b","ar":"ف","why":"ف (fā’) n’a qu’un point."}],"answer":"a","explanation":"ق (qāf) a deux points au-dessus de sa tête ronde.","reviewKey":"letter:qaf"},{"id":"m1l8-5","type":"sort","prompt":"Classez ces lettres selon leurs points","buckets":[{"id":"none","label":"Aucun point"},{"id":"above","label":"Points au-dessus"},{"id":"below","label":"Points en dessous"}],"items":[{"id":"i1","ar":"ح","bucket":"none"},{"id":"i2","ar":"ع","bucket":"none"},{"id":"i3","ar":"ت","bucket":"above"},{"id":"i4","ar":"ز","bucket":"above"},{"id":"i5","ar":"ب","bucket":"below"},{"id":"i6","ar":"ي","bucket":"below"}],"explanation":"ح et ع : aucun point. ت et ز : points au-dessus. ب et ي : points en dessous."}],"summary":["Squelette d’abord, points ensuite.","Neuf familles de lettres jumelles à connaître."]}'::jsonb) on conflict (lesson_id) do update set content = excluded.content, version = public.lesson_contents.version + 1, updated_at = now();
insert into public.lessons (id, module_id, position, title_fr, objective_fr, difficulty, est_minutes, kind, published) values ('m1-test', 1, 99, 'Test du module 1 : l’alphabet', 'Valider les acquis du module : 80 % de bonnes réponses sont nécessaires.', 2, 10, 'module_test', true) on conflict (id) do update set title_fr = excluded.title_fr, objective_fr = excluded.objective_fr, difficulty = excluded.difficulty, est_minutes = excluded.est_minutes, kind = excluded.kind, position = excluded.position;
insert into public.lesson_contents (lesson_id, content) values ('m1-test', '{"steps":[{"kind":"explain","text":"Ce test reprend les notions des leçons du module. Prenez votre temps : il n’y a pas de limite de durée et vous pourrez le repasser."}],"exercises":[{"id":"module_test-m1-m1l1-name-ba","type":"choice","format":"visual","prompt":"Quelle lettre s''appelle « bā’ » ?","options":[{"id":"tha","ar":"ث","why":"ث est thā’ : « th » de l’anglais « think » : langue entre les dents, sans voix. Repère visuel : trois points au-dessus."},{"id":"ta","ar":"ت","why":"ت est tā’ : « t » comme dans « table ». Repère visuel : deux points au-dessus."},{"id":"ba","ar":"ب"},{"id":"nun","ar":"ن","why":"ن est nūn : « n » comme dans « nez ». Repère visuel : un point au-dessus."}],"answer":"ba","explanation":"ب se nomme bā’ (بَاء) et se transcrit « b » : « b » comme dans « bateau ». Repère visuel : un point en dessous.","reviewKey":"letter:ba"},{"id":"module_test-m1-m1l1-listen-ba","type":"choice","format":"listen","prompt":"Écoutez puis choisissez la lettre entendue","options":[{"id":"ba","ar":"ب"},{"id":"ta","ar":"ت","why":"ت est tā’ : « t » comme dans « table ». Repère visuel : deux points au-dessus."},{"id":"qaf","ar":"ق","why":"ق est qāf : « k » prononcé très au fond, contre la luette. Repère visuel : deux points au-dessus."},{"id":"tha","ar":"ث","why":"ث est thā’ : « th » de l’anglais « think » : langue entre les dents, sans voix. Repère visuel : trois points au-dessus."}],"answer":"ba","explanation":"ب se nomme bā’ (بَاء) et se transcrit « b » : « b » comme dans « bateau ». Repère visuel : un point en dessous.","audio":"letter:ba","textFallback":"Quelle lettre se prononce « b » comme dans « bateau » ?","reviewKey":"letter:ba"},{"id":"module_test-m1-m1l2-name-hha","type":"choice","format":"visual","prompt":"Quelle lettre s''appelle « ḥā’ » ?","options":[{"id":"jim","ar":"ج","why":"ج est jīm : « dj » comme dans « djinn ». Repère visuel : un point en dessous."},{"id":"ha","ar":"ه","why":"ه est hā’ : « h » léger et expiré, comme l’anglais « hello ». Repère visuel : aucun point."},{"id":"kha","ar":"خ","why":"خ est khā’ : « r » raclé au fond du palais, comme la « jota » espagnole ou le « ch » allemand de « Bach ». Repère visuel : un point au-dessus."},{"id":"hha","ar":"ح"}],"answer":"hha","explanation":"ح se nomme ḥā’ (حَاء) et se transcrit « ḥ » : « h » soufflé et serré au milieu de la gorge, comme pour embuer une vitre très fort. Repère visuel : aucun point.","reviewKey":"letter:hha"},{"id":"module_test-m1-m1l2-sound-hha","type":"choice","format":"mcq","prompt":"Quel son correspond à cette lettre ?","options":[{"id":"tta","label":"« ṭ »","why":"ط est ṭā’ : « t » emphatique : son grave, arrière de la langue relevé. Repère visuel : aucun point."},{"id":"kha","label":"« kh »","why":"خ est khā’ : « r » raclé au fond du palais, comme la « jota » espagnole ou le « ch » allemand de « Bach ». Repère visuel : un point au-dessus."},{"id":"hha","label":"« ḥ »"},{"id":"jim","label":"« j »","why":"ج est jīm : « dj » comme dans « djinn ». Repère visuel : un point en dessous."}],"answer":"hha","explanation":"ح se nomme ḥā’ (حَاء) et se transcrit « ḥ » : « h » soufflé et serré au milieu de la gorge, comme pour embuer une vitre très fort. Repère visuel : aucun point.","ar":"ح","reviewKey":"letter:hha"},{"id":"module_test-m1-m1l3-sound-dal","type":"choice","format":"mcq","prompt":"Quel son correspond à cette lettre ?","options":[{"id":"ghayn","label":"« gh »","why":"غ est ghayn : « r » grasseyé comme le « r » parisien de « Paris ». Repère visuel : un point au-dessus."},{"id":"dal","label":"« d »"},{"id":"kha","label":"« kh »","why":"خ est khā’ : « r » raclé au fond du palais, comme la « jota » espagnole ou le « ch » allemand de « Bach ». Repère visuel : un point au-dessus."},{"id":"dhal","label":"« dh »","why":"ذ est dhāl : « th » de l’anglais « this » : langue entre les dents, avec la voix. Repère visuel : un point au-dessus."}],"answer":"dal","explanation":"د se nomme dāl (دَال) et se transcrit « d » : « d » comme dans « dos ». Repère visuel : aucun point.","ar":"د","reviewKey":"letter:dal"},{"id":"module_test-m1-m1l3-name-dhal","type":"choice","format":"visual","prompt":"Quelle lettre s''appelle « dhāl » ?","options":[{"id":"sad","ar":"ص","why":"ص est ṣād : « s » emphatique : bouche arrondie, arrière de la langue relevé, son plus grave. Repère visuel : aucun point."},{"id":"ha","ar":"ه","why":"ه est hā’ : « h » léger et expiré, comme l’anglais « hello ». Repère visuel : aucun point."},{"id":"dhal","ar":"ذ"},{"id":"dal","ar":"د","why":"د est dāl : « d » comme dans « dos ». Repère visuel : aucun point."}],"answer":"dhal","explanation":"ذ se nomme dhāl (ذَال) et se transcrit « dh » : « th » de l’anglais « this » : langue entre les dents, avec la voix. Repère visuel : un point au-dessus.","reviewKey":"letter:dhal"},{"id":"module_test-m1-m1l4-sound-sin","type":"choice","format":"mcq","prompt":"Quel son correspond à cette lettre ?","options":[{"id":"zay","label":"« z »","why":"ز est zāy : « z » comme dans « zéro ». Repère visuel : un point au-dessus."},{"id":"shin","label":"« sh »","why":"ش est shīn : « ch » comme dans « chat ». Repère visuel : trois points au-dessus."},{"id":"sin","label":"« s »"},{"id":"kha","label":"« kh »","why":"خ est khā’ : « r » raclé au fond du palais, comme la « jota » espagnole ou le « ch » allemand de « Bach ». Repère visuel : un point au-dessus."}],"answer":"sin","explanation":"س se nomme sīn (سِين) et se transcrit « s » : « s » comme dans « sel ». Repère visuel : aucun point.","ar":"س","reviewKey":"letter:sin"},{"id":"module_test-m1-m1l4-name-sad","type":"choice","format":"visual","prompt":"Quelle lettre s''appelle « ṣād » ?","options":[{"id":"jim","ar":"ج","why":"ج est jīm : « dj » comme dans « djinn ». Repère visuel : un point en dessous."},{"id":"dad","ar":"ض","why":"ض est ḍād : « d » emphatique, son grave et plein ; lettre réputée propre à l’arabe. Repère visuel : un point au-dessus."},{"id":"alif","ar":"ا","why":"ا est alif : pas de son propre : support de la voyelle longue « â » ou de la hamza (attaque de voyelle). Repère visuel : aucun point."},{"id":"sad","ar":"ص"}],"answer":"sad","explanation":"ص se nomme ṣād (صَاد) et se transcrit « ṣ » : « s » emphatique : bouche arrondie, arrière de la langue relevé, son plus grave. Repère visuel : aucun point.","reviewKey":"letter:sad"},{"id":"module_test-m1-m1l5-name-ayn","type":"choice","format":"visual","prompt":"Quelle lettre s''appelle « ʿayn » ?","options":[{"id":"ayn","ar":"ع"},{"id":"ghayn","ar":"غ","why":"غ est ghayn : « r » grasseyé comme le « r » parisien de « Paris ». Repère visuel : un point au-dessus."},{"id":"dad","ar":"ض","why":"ض est ḍād : « d » emphatique, son grave et plein ; lettre réputée propre à l’arabe. Repère visuel : un point au-dessus."},{"id":"kaf","ar":"ك","why":"ك est kāf : « k » comme dans « kilo ». Repère visuel : aucun point."}],"answer":"ayn","explanation":"ع se nomme ʿayn (عَيْن) et se transcrit « ʿ » : contraction sonore du milieu de la gorge ; aucun équivalent en français. Repère visuel : aucun point.","reviewKey":"letter:ayn"},{"id":"module_test-m1-m1l5-listen-ayn","type":"choice","format":"listen","prompt":"Écoutez puis choisissez la lettre entendue","options":[{"id":"tha","ar":"ث","why":"ث est thā’ : « th » de l’anglais « think » : langue entre les dents, sans voix. Repère visuel : trois points au-dessus."},{"id":"ghayn","ar":"غ","why":"غ est ghayn : « r » grasseyé comme le « r » parisien de « Paris ». Repère visuel : un point au-dessus."},{"id":"ayn","ar":"ع"},{"id":"hha","ar":"ح","why":"ح est ḥā’ : « h » soufflé et serré au milieu de la gorge, comme pour embuer une vitre très fort. Repère visuel : aucun point."}],"answer":"ayn","explanation":"ع se nomme ʿayn (عَيْن) et se transcrit « ʿ » : contraction sonore du milieu de la gorge ; aucun équivalent en français. Repère visuel : aucun point.","audio":"letter:ayn","textFallback":"Quelle lettre se prononce contraction sonore du milieu de la gorge ; aucun équivalent en français ?","reviewKey":"letter:ayn"},{"id":"module_test-m1-m1l6-name-kaf","type":"choice","format":"visual","prompt":"Quelle lettre s''appelle « kāf » ?","options":[{"id":"dad","ar":"ض","why":"ض est ḍād : « d » emphatique, son grave et plein ; lettre réputée propre à l’arabe. Repère visuel : un point au-dessus."},{"id":"kaf","ar":"ك"},{"id":"nun","ar":"ن","why":"ن est nūn : « n » comme dans « nez ». Repère visuel : un point au-dessus."},{"id":"alif","ar":"ا","why":"ا est alif : pas de son propre : support de la voyelle longue « â » ou de la hamza (attaque de voyelle). Repère visuel : aucun point."}],"answer":"kaf","explanation":"ك se nomme kāf (كَاف) et se transcrit « k » : « k » comme dans « kilo ». Repère visuel : aucun point.","reviewKey":"letter:kaf"},{"id":"module_test-m1-m1l6-sound-fa","type":"choice","format":"mcq","prompt":"Quel son correspond à cette lettre ?","options":[{"id":"zay","label":"« z »","why":"ز est zāy : « z » comme dans « zéro ». Repère visuel : un point au-dessus."},{"id":"fa","label":"« f »"},{"id":"qaf","label":"« q »","why":"ق est qāf : « k » prononcé très au fond, contre la luette. Repère visuel : deux points au-dessus."},{"id":"ya","label":"« y / ī »","why":"ي est yā’ : « y » comme dans « yaourt », ou voyelle longue « î ». Repère visuel : deux points en dessous."}],"answer":"fa","explanation":"ف se nomme fā’ (فَاء) et se transcrit « f » : « f » comme dans « fil ». Repère visuel : un point au-dessus.","ar":"ف","reviewKey":"letter:fa"},{"id":"module_test-m1-m1l7-listen-mim","type":"choice","format":"listen","prompt":"Écoutez puis choisissez la lettre entendue","options":[{"id":"qaf","ar":"ق","why":"ق est qāf : « k » prononcé très au fond, contre la luette. Repère visuel : deux points au-dessus."},{"id":"ayn","ar":"ع","why":"ع est ʿayn : contraction sonore du milieu de la gorge ; aucun équivalent en français. Repère visuel : aucun point."},{"id":"mim","ar":"م"},{"id":"waw","ar":"و","why":"و est wāw : « w » comme dans « watt », ou voyelle longue « oû ». Repère visuel : aucun point."}],"answer":"mim","explanation":"م se nomme mīm (مِيم) et se transcrit « m » : « m » comme dans « mer ». Repère visuel : aucun point.","audio":"letter:mim","textFallback":"Quelle lettre se prononce « m » comme dans « mer » ?","reviewKey":"letter:mim"},{"id":"module_test-m1-m1l7-listen-ha","type":"choice","format":"listen","prompt":"Écoutez puis choisissez la lettre entendue","options":[{"id":"ha","ar":"ه"},{"id":"dal","ar":"د","why":"د est dāl : « d » comme dans « dos ». Repère visuel : aucun point."},{"id":"sad","ar":"ص","why":"ص est ṣād : « s » emphatique : bouche arrondie, arrière de la langue relevé, son plus grave. Repère visuel : aucun point."},{"id":"qaf","ar":"ق","why":"ق est qāf : « k » prononcé très au fond, contre la luette. Repère visuel : deux points au-dessus."}],"answer":"ha","explanation":"ه se nomme hā’ (هَاء) et se transcrit « h » : « h » léger et expiré, comme l’anglais « hello ». Repère visuel : aucun point.","audio":"letter:ha","textFallback":"Quelle lettre se prononce « h » léger et expiré, comme l’anglais « hello » ?","reviewKey":"letter:ha"},{"id":"module_test-m1-m1l8-3","type":"choice","format":"visual","prompt":"Quelle lettre est ḍād ?","options":[{"id":"d","ar":"ذ","why":"ذ (dhāl) est petite et ne descend pas."},{"id":"a","ar":"ض"},{"id":"b","ar":"ص","why":"ص (ṣād) a le même squelette sans point."},{"id":"c","ar":"ظ","why":"ظ (ẓā’) a un point mais un squelette à hampe verticale."}],"answer":"a","explanation":"ض = ṣād + un point au-dessus.","reviewKey":"letter:dad"},{"id":"module_test-m1-m1l8-4","type":"choice","format":"visual","prompt":"Quelle lettre est qāf ?","options":[{"id":"c","ar":"ك","why":"ك (kāf) a un tracé anguleux, sans point."},{"id":"a","ar":"ق"},{"id":"d","ar":"و","why":"و (wāw) a une tête ronde mais aucun point et ne se lie pas."},{"id":"b","ar":"ف","why":"ف (fā’) n’a qu’un point."}],"answer":"a","explanation":"ق (qāf) a deux points au-dessus de sa tête ronde.","reviewKey":"letter:qaf"}],"summary":["Résultat enregistré dans votre progression.","Les notions manquées sont ajoutées à vos révisions."]}'::jsonb) on conflict (lesson_id) do update set content = excluded.content, version = public.lesson_contents.version + 1, updated_at = now();
