insert into public.lessons (id, module_id, position, title_fr, objective_fr, difficulty, est_minutes, kind, published) values ('m2l1', 2, 1, 'Une lettre, quatre formes', 'Comprendre pourquoi une lettre change de forme selon sa position', 1, 6, 'lesson', true) on conflict (id) do update set title_fr = excluded.title_fr, objective_fr = excluded.objective_fr, difficulty = excluded.difficulty, est_minutes = excluded.est_minutes, kind = excluded.kind, position = excluded.position;
insert into public.lesson_contents (lesson_id, content) values ('m2l1', '{"steps":[{"kind":"explain","text":"En arabe, les lettres d’un mot sont attachées entre elles, comme en écriture cursive. Selon sa place, une lettre prend une forme isolée, initiale (début de mot), médiane (milieu) ou finale (fin de mot)."},{"kind":"forms","letterId":"ba"},{"kind":"explain","text":"La forme initiale est souvent une version raccourcie de la lettre, qui « tend la main » vers la suivante. La forme finale garde la queue de la lettre isolée."},{"kind":"forms","letterId":"nun"},{"kind":"tip","text":"Au début et au milieu d’un mot, ب ت ث ن ي ont presque la même forme : seuls les points les distinguent."}],"exercises":[{"id":"m2l1-form-initial-ba","type":"choice","format":"visual","prompt":"Quelle est la forme initiale (début de mot) de bā’ ?","options":[{"id":"ok","ar":"بـ"},{"id":"oth","ar":"جـ","why":"C''est la forme initiale (début de mot) de jīm."},{"id":"sib","ar":"تـ","why":"C''est la forme initiale (début de mot) de tā’ (deux points au-dessus), pas de bā’ (un point en dessous)."},{"id":"iso","ar":"ـب","why":"Ce tracé n''est pas celui de la position initiale (début de mot)."}],"answer":"ok","explanation":"bā’ en position initiale (début de mot) s''écrit بـ. Cette lettre se lie aux deux côtés.","reviewKey":"form:ba"},{"id":"m2l1-form-final-ba","type":"choice","format":"visual","prompt":"Quelle est la forme finale (fin de mot) de bā’ ?","options":[{"id":"oth","ar":"ـج","why":"C''est la forme finale (fin de mot) de jīm."},{"id":"ok","ar":"ـب"},{"id":"sib","ar":"ـت","why":"C''est la forme finale (fin de mot) de tā’ (deux points au-dessus), pas de bā’ (un point en dessous)."}],"answer":"ok","explanation":"bā’ en position finale (fin de mot) s''écrit ـب. Cette lettre se lie aux deux côtés.","reviewKey":"form:ba"},{"id":"m2l1-form-medial-ta","type":"choice","format":"visual","prompt":"Quelle est la forme médiane (milieu de mot) de tā’ ?","options":[{"id":"oth","ar":"ـجـ","why":"C''est la forme médiane (milieu de mot) de jīm."},{"id":"iso","ar":"ـت","why":"Ce tracé n''est pas celui de la position médiane (milieu de mot)."},{"id":"sib","ar":"ـبـ","why":"C''est la forme médiane (milieu de mot) de bā’ (un point en dessous), pas de tā’ (deux points au-dessus)."},{"id":"ok","ar":"ـتـ"}],"answer":"ok","explanation":"tā’ en position médiane (milieu de mot) s''écrit ـتـ. Cette lettre se lie aux deux côtés.","reviewKey":"form:ta"},{"id":"m2l1-form-initial-nun","type":"choice","format":"visual","prompt":"Quelle est la forme initiale (début de mot) de nūn ?","options":[{"id":"ok","ar":"نـ"},{"id":"oth","ar":"تـ","why":"C''est la forme initiale (début de mot) de tā’."},{"id":"sib","ar":"بـ","why":"C''est la forme initiale (début de mot) de bā’ (un point en dessous), pas de nūn (un point au-dessus)."},{"id":"iso","ar":"ـن","why":"Ce tracé n''est pas celui de la position initiale (début de mot)."}],"answer":"ok","explanation":"nūn en position initiale (début de mot) s''écrit نـ. Cette lettre se lie aux deux côtés.","reviewKey":"form:nun"},{"id":"m2l1-form-medial-ya","type":"choice","format":"visual","prompt":"Quelle est la forme médiane (milieu de mot) de yā’ ?","options":[{"id":"sib","ar":"ـبـ","why":"C''est la forme médiane (milieu de mot) de bā’ (un point en dessous), pas de yā’ (deux points en dessous)."},{"id":"ok","ar":"ـيـ"},{"id":"iso","ar":"ـي","why":"Ce tracé n''est pas celui de la position médiane (milieu de mot)."},{"id":"oth","ar":"ـتـ","why":"C''est la forme médiane (milieu de mot) de tā’."}],"answer":"ok","explanation":"yā’ en position médiane (milieu de mot) s''écrit ـيـ. Cette lettre se lie aux deux côtés.","reviewKey":"form:ya"}],"summary":["Isolée, initiale, médiane, finale.","Les points restent à leur place dans toutes les formes."]}'::jsonb) on conflict (lesson_id) do update set content = excluded.content, version = public.lesson_contents.version + 1, updated_at = now();
insert into public.lessons (id, module_id, position, title_fr, objective_fr, difficulty, est_minutes, kind, published) values ('m2l2', 2, 2, 'Les formes des lettres courantes', 'Reconnaître les quatre formes de ج س ف ق ل م', 2, 8, 'lesson', true) on conflict (id) do update set title_fr = excluded.title_fr, objective_fr = excluded.objective_fr, difficulty = excluded.difficulty, est_minutes = excluded.est_minutes, kind = excluded.kind, position = excluded.position;
insert into public.lesson_contents (lesson_id, content) values ('m2l2', '{"steps":[{"kind":"explain","text":"Observez chaque lettre dans ses quatre positions. Repérez ce qui reste identique : c’est ce qui vous permettra de la reconnaître dans un mot."},{"kind":"forms","letterId":"jim"},{"kind":"forms","letterId":"sin"},{"kind":"forms","letterId":"fa"},{"kind":"forms","letterId":"qaf"},{"kind":"forms","letterId":"lam"},{"kind":"forms","letterId":"mim"}],"exercises":[{"id":"m2l2-form-initial-jim","type":"choice","format":"visual","prompt":"Quelle est la forme initiale (début de mot) de jīm ?","options":[{"id":"sib","ar":"حـ","why":"C''est la forme initiale (début de mot) de ḥā’ (aucun point), pas de jīm (un point en dessous)."},{"id":"oth","ar":"بـ","why":"C''est la forme initiale (début de mot) de bā’."},{"id":"iso","ar":"ـج","why":"Ce tracé n''est pas celui de la position initiale (début de mot)."},{"id":"ok","ar":"جـ"}],"answer":"ok","explanation":"jīm en position initiale (début de mot) s''écrit جـ. Cette lettre se lie aux deux côtés.","reviewKey":"form:jim"},{"id":"m2l2-form-medial-sin","type":"choice","format":"visual","prompt":"Quelle est la forme médiane (milieu de mot) de sīn ?","options":[{"id":"oth","ar":"ـبـ","why":"C''est la forme médiane (milieu de mot) de bā’."},{"id":"sib","ar":"ـشـ","why":"C''est la forme médiane (milieu de mot) de shīn (trois points au-dessus), pas de sīn (aucun point)."},{"id":"ok","ar":"ـسـ"},{"id":"iso","ar":"ـس","why":"Ce tracé n''est pas celui de la position médiane (milieu de mot)."}],"answer":"ok","explanation":"sīn en position médiane (milieu de mot) s''écrit ـسـ. Cette lettre se lie aux deux côtés.","reviewKey":"form:sin"},{"id":"m2l2-form-final-fa","type":"choice","format":"visual","prompt":"Quelle est la forme finale (fin de mot) de fā’ ?","options":[{"id":"ok","ar":"ـف"},{"id":"sib","ar":"ـق","why":"C''est la forme finale (fin de mot) de qāf (deux points au-dessus), pas de fā’ (un point au-dessus)."},{"id":"oth","ar":"ـب","why":"C''est la forme finale (fin de mot) de bā’."}],"answer":"ok","explanation":"fā’ en position finale (fin de mot) s''écrit ـف. Cette lettre se lie aux deux côtés.","reviewKey":"form:fa"},{"id":"m2l2-form-initial-qaf","type":"choice","format":"visual","prompt":"Quelle est la forme initiale (début de mot) de qāf ?","options":[{"id":"sib","ar":"فـ","why":"C''est la forme initiale (début de mot) de fā’ (un point au-dessus), pas de qāf (deux points au-dessus)."},{"id":"iso","ar":"ـق","why":"Ce tracé n''est pas celui de la position initiale (début de mot)."},{"id":"oth","ar":"بـ","why":"C''est la forme initiale (début de mot) de bā’."},{"id":"ok","ar":"قـ"}],"answer":"ok","explanation":"qāf en position initiale (début de mot) s''écrit قـ. Cette lettre se lie aux deux côtés.","reviewKey":"form:qaf"},{"id":"m2l2-form-medial-lam","type":"choice","format":"visual","prompt":"Quelle est la forme médiane (milieu de mot) de lām ?","options":[{"id":"oth","ar":"ـتـ","why":"C''est la forme médiane (milieu de mot) de tā’."},{"id":"iso","ar":"ـل","why":"Ce tracé n''est pas celui de la position médiane (milieu de mot)."},{"id":"ok","ar":"ـلـ"},{"id":"sib","ar":"ـبـ","why":"C''est la forme médiane (milieu de mot) de bā’ (un point en dessous), pas de lām (aucun point)."}],"answer":"ok","explanation":"lām en position médiane (milieu de mot) s''écrit ـلـ. Cette lettre se lie aux deux côtés.","reviewKey":"form:lam"},{"id":"m2l2-form-final-mim","type":"choice","format":"visual","prompt":"Quelle est la forme finale (fin de mot) de mīm ?","options":[{"id":"ok","ar":"ـم"},{"id":"oth","ar":"ـت","why":"C''est la forme finale (fin de mot) de tā’."},{"id":"sib","ar":"ـب","why":"C''est la forme finale (fin de mot) de bā’ (un point en dessous), pas de mīm (aucun point)."}],"answer":"ok","explanation":"mīm en position finale (fin de mot) s''écrit ـم. Cette lettre se lie aux deux côtés.","reviewKey":"form:mim"},{"id":"m2l2-form-final-lam","type":"choice","format":"visual","prompt":"Quelle est la forme finale (fin de mot) de lām ?","options":[{"id":"oth","ar":"ـت","why":"C''est la forme finale (fin de mot) de tā’."},{"id":"sib","ar":"ـب","why":"C''est la forme finale (fin de mot) de bā’ (un point en dessous), pas de lām (aucun point)."},{"id":"ok","ar":"ـل"}],"answer":"ok","explanation":"lām en position finale (fin de mot) s''écrit ـل. Cette lettre se lie aux deux côtés.","reviewKey":"form:lam"},{"id":"m2l2-form-initial-mim","type":"choice","format":"visual","prompt":"Quelle est la forme initiale (début de mot) de mīm ?","options":[{"id":"ok","ar":"مـ"},{"id":"sib","ar":"بـ","why":"C''est la forme initiale (début de mot) de bā’ (un point en dessous), pas de mīm (aucun point)."},{"id":"iso","ar":"ـم","why":"Ce tracé n''est pas celui de la position initiale (début de mot)."},{"id":"oth","ar":"تـ","why":"C''est la forme initiale (début de mot) de tā’."}],"answer":"ok","explanation":"mīm en position initiale (début de mot) s''écrit مـ. Cette lettre se lie aux deux côtés.","reviewKey":"form:mim"}],"summary":["ل en fin de mot garde sa grande boucle.","م se reconnaît à sa petite boucle, à toutes les positions."]}'::jsonb) on conflict (lesson_id) do update set content = excluded.content, version = public.lesson_contents.version + 1, updated_at = now();
insert into public.lessons (id, module_id, position, title_fr, objective_fr, difficulty, est_minutes, kind, published) values ('m2l3', 2, 3, 'Les six lettres qui ne se lient pas à gauche', 'Identifier ا د ذ ر ز و et leurs effets sur l’écriture d’un mot', 2, 7, 'lesson', true) on conflict (id) do update set title_fr = excluded.title_fr, objective_fr = excluded.objective_fr, difficulty = excluded.difficulty, est_minutes = excluded.est_minutes, kind = excluded.kind, position = excluded.position;
insert into public.lesson_contents (lesson_id, content) values ('m2l3', '{"steps":[{"kind":"explain","text":"Six lettres ne se lient jamais à la lettre suivante : ا د ذ ر ز و. Elles se lient à la lettre précédente, mais créent une coupure après elles. La lettre qui les suit prend donc une forme initiale ou isolée, même au milieu du mot."},{"kind":"forms","letterId":"alif"},{"kind":"forms","letterId":"dal"},{"kind":"forms","letterId":"dhal"},{"kind":"forms","letterId":"ra"},{"kind":"forms","letterId":"zay"},{"kind":"forms","letterId":"waw"},{"kind":"example","ar":"دَرَسَ","translit":"darasa","fr":"il a étudié","audio":"word:darasa","note":"د et ر ne se lient pas à gauche : le mot est écrit en trois morceaux."},{"kind":"tip","text":"Moyen mnémotechnique : « a, d, dh, r, z, w » — toutes les autres lettres se lient des deux côtés."}],"exercises":[{"id":"m2l3-sort","type":"sort","prompt":"Ces lettres se lient-elles à la lettre suivante ?","buckets":[{"id":"yes","label":"Se lie"},{"id":"no","label":"Ne se lie pas"}],"items":[{"id":"a","ar":"ا","bucket":"no"},{"id":"b","ar":"ب","bucket":"yes"},{"id":"c","ar":"د","bucket":"no"},{"id":"d","ar":"م","bucket":"yes"},{"id":"e","ar":"ر","bucket":"no"},{"id":"f","ar":"و","bucket":"no"},{"id":"g","ar":"ل","bucket":"yes"},{"id":"h","ar":"ز","bucket":"no"}],"explanation":"Ne se lient pas : ا د ذ ر ز و. Toutes les autres se lient à la lettre suivante.","reviewKey":"rule:non-joining"},{"id":"m2l3-2","type":"choice","format":"mcq","prompt":"Combien de lettres arabes ne se lient jamais à la lettre suivante ?","options":[{"id":"a","label":"6"},{"id":"d","label":"28","why":"La grande majorité des lettres se lient des deux côtés."},{"id":"c","label":"8","why":"Seules six lettres ont cette propriété : ا د ذ ر ز و."},{"id":"b","label":"4","why":"Il en manque deux : la liste complète est ا د ذ ر ز و."}],"answer":"a","explanation":"Les six lettres sont ا د ذ ر ز و.","reviewKey":"rule:non-joining"},{"id":"m2l3-form-final-dal","type":"choice","format":"visual","prompt":"Quelle est la forme finale (fin de mot) de dāl ?","options":[{"id":"sib","ar":"ـذ","why":"C''est la forme finale (fin de mot) de dhāl (un point au-dessus), pas de dāl (aucun point)."},{"id":"ok","ar":"ـد"},{"id":"oth","ar":"ـا","why":"C''est la forme finale (fin de mot) de alif."}],"answer":"ok","explanation":"dāl en position finale (fin de mot) s''écrit ـد. Cette lettre ne se lie jamais à la lettre suivante : sa forme initiale est identique à la forme isolée.","reviewKey":"form:dal"},{"id":"m2l3-form-medial-waw","type":"choice","format":"visual","prompt":"Quelle est la forme médiane (milieu de mot) de wāw ?","options":[{"id":"ok","ar":"ـو"},{"id":"oth","ar":"ـا","why":"C''est la forme médiane (milieu de mot) de alif."},{"id":"sib","ar":"ـبـ","why":"C''est la forme médiane (milieu de mot) de bā’ (un point en dessous), pas de wāw (aucun point)."},{"id":"iso","ar":"و","why":"Ce tracé n''est pas celui de la position médiane (milieu de mot)."}],"answer":"ok","explanation":"wāw en position médiane (milieu de mot) s''écrit ـو. Cette lettre ne se lie jamais à la lettre suivante : sa forme initiale est identique à la forme isolée.","reviewKey":"form:waw"},{"id":"m2l3-form-initial-ra","type":"choice","format":"visual","prompt":"Quelle est la forme initiale (début de mot) de rā’ ?","options":[{"id":"iso","ar":"ـر","why":"Ce tracé n''est pas celui de la position initiale (début de mot)."},{"id":"oth","ar":"ا","why":"C''est la forme initiale (début de mot) de alif."},{"id":"ok","ar":"ر"},{"id":"sib","ar":"ز","why":"C''est la forme initiale (début de mot) de zāy (un point au-dessus), pas de rā’ (aucun point)."}],"answer":"ok","explanation":"rā’ en position initiale (début de mot) s''écrit ر. Cette lettre ne se lie jamais à la lettre suivante : sa forme initiale est identique à la forme isolée.","reviewKey":"form:ra"},{"id":"m2l3-3","type":"choice","format":"mcq","prompt":"Dans دَرَسَ, pourquoi le mot est-il coupé en morceaux ?","options":[{"id":"c","label":"Parce que ce sont trois mots différents","why":"C’est un seul mot : les coupures viennent des lettres non liantes."},{"id":"b","label":"Parce que le mot contient des voyelles","why":"Les voyelles brèves sont des signes, elles ne coupent pas le mot."},{"id":"a","label":"Parce que د et ر ne se lient pas à la lettre suivante"}],"answer":"a","explanation":"د et ر font partie des six lettres non liantes : la lettre qui suit commence un nouveau « morceau ».","ar":"دَرَسَ"}],"summary":["ا د ذ ر ز و ne se lient jamais à gauche.","Un mot peut donc être écrit en plusieurs morceaux."]}'::jsonb) on conflict (lesson_id) do update set content = excluded.content, version = public.lesson_contents.version + 1, updated_at = now();
insert into public.lessons (id, module_id, position, title_fr, objective_fr, difficulty, est_minutes, kind, published) values ('m2l4', 2, 4, 'Formes particulières', 'Reconnaître les lettres qui changent beaucoup de forme, ainsi que لا, ة et ى', 3, 8, 'lesson', true) on conflict (id) do update set title_fr = excluded.title_fr, objective_fr = excluded.objective_fr, difficulty = excluded.difficulty, est_minutes = excluded.est_minutes, kind = excluded.kind, position = excluded.position;
insert into public.lesson_contents (lesson_id, content) values ('m2l4', '{"steps":[{"kind":"explain","text":"Certaines lettres changent nettement selon leur position : ع et غ, ه, ك. Observez-les attentivement."},{"kind":"forms","letterId":"ayn"},{"kind":"forms","letterId":"ha"},{"kind":"forms","letterId":"kaf"},{"kind":"example","ar":"لا","translit":"lā","fr":"non","audio":"word:la","note":"Lām suivi de alif forme une ligature obligatoire : لا."},{"kind":"example","ar":"رَحْمَة","translit":"raḥma","fr":"miséricorde","audio":"word:rahma","note":"ة (tā’ marbūṭa) se trouve uniquement en fin de mot. Elle se prononce « t » quand on enchaîne, « h » ou rien à la pause."},{"kind":"example","ar":"عَلَى","translit":"ʿalā","fr":"sur","audio":"word:ala","note":"ى (alif maqṣūra) ressemble à ي sans points ; en fin de mot elle se lit « â »."}],"exercises":[{"id":"m2l4-form-medial-ayn","type":"choice","format":"visual","prompt":"Quelle est la forme médiane (milieu de mot) de ʿayn ?","options":[{"id":"ok","ar":"ـعـ"},{"id":"oth","ar":"ـبـ","why":"C''est la forme médiane (milieu de mot) de bā’."},{"id":"sib","ar":"ـغـ","why":"C''est la forme médiane (milieu de mot) de ghayn (un point au-dessus), pas de ʿayn (aucun point)."},{"id":"iso","ar":"ـع","why":"Ce tracé n''est pas celui de la position médiane (milieu de mot)."}],"answer":"ok","explanation":"ʿayn en position médiane (milieu de mot) s''écrit ـعـ. Cette lettre se lie aux deux côtés.","reviewKey":"form:ayn"},{"id":"m2l4-form-initial-ha","type":"choice","format":"visual","prompt":"Quelle est la forme initiale (début de mot) de hā’ ?","options":[{"id":"iso","ar":"ـه","why":"Ce tracé n''est pas celui de la position initiale (début de mot)."},{"id":"oth","ar":"تـ","why":"C''est la forme initiale (début de mot) de tā’."},{"id":"ok","ar":"هـ"},{"id":"sib","ar":"بـ","why":"C''est la forme initiale (début de mot) de bā’ (un point en dessous), pas de hā’ (aucun point)."}],"answer":"ok","explanation":"hā’ en position initiale (début de mot) s''écrit هـ. Cette lettre se lie aux deux côtés.","reviewKey":"form:ha"},{"id":"m2l4-form-final-kaf","type":"choice","format":"visual","prompt":"Quelle est la forme finale (fin de mot) de kāf ?","options":[{"id":"oth","ar":"ـت","why":"C''est la forme finale (fin de mot) de tā’."},{"id":"sib","ar":"ـب","why":"C''est la forme finale (fin de mot) de bā’ (un point en dessous), pas de kāf (aucun point)."},{"id":"ok","ar":"ـك"}],"answer":"ok","explanation":"kāf en position finale (fin de mot) s''écrit ـك. Cette lettre se lie aux deux côtés.","reviewKey":"form:kaf"},{"id":"m2l4-1","type":"choice","format":"mcq","prompt":"Que représente لا ?","options":[{"id":"c","label":"alif + lām","why":"L’ordre est inversé : on lit de droite à gauche, ل d’abord, ا ensuite."},{"id":"a","label":"lām + alif (ligature)"},{"id":"b","label":"une lettre à part, la 29e","why":"لا n’est pas une lettre supplémentaire : c’est l’union obligatoire de ل et ا."}],"answer":"a","explanation":"لا est la ligature obligatoire de ل suivi de ا.","ar":"لا"},{"id":"m2l4-2","type":"choice","format":"mcq","prompt":"Où trouve-t-on la tā’ marbūṭa ة ?","options":[{"id":"b","label":"En début de mot","why":"ة n’apparaît jamais en début de mot."},{"id":"c","label":"N’importe où","why":"ة est réservée à la fin du mot ; ailleurs on écrit ت."},{"id":"a","label":"Uniquement en fin de mot"}],"answer":"a","explanation":"ة marque souvent le féminin et se place toujours en fin de mot.","ar":"رَحْمَة"}],"summary":["ع غ ه ك changent beaucoup de forme.","لا = ل + ا ; ة en fin de mot ; ى se lit « â »."]}'::jsonb) on conflict (lesson_id) do update set content = excluded.content, version = public.lesson_contents.version + 1, updated_at = now();
insert into public.lessons (id, module_id, position, title_fr, objective_fr, difficulty, est_minutes, kind, published) values ('m2-test', 2, 99, 'Test du module 2 : les formes', 'Valider les acquis du module : 80 % de bonnes réponses sont nécessaires.', 2, 5, 'module_test', true) on conflict (id) do update set title_fr = excluded.title_fr, objective_fr = excluded.objective_fr, difficulty = excluded.difficulty, est_minutes = excluded.est_minutes, kind = excluded.kind, position = excluded.position;
insert into public.lesson_contents (lesson_id, content) values ('m2-test', '{"steps":[{"kind":"explain","text":"Ce test reprend les notions des leçons du module. Prenez votre temps : il n’y a pas de limite de durée et vous pourrez le repasser."}],"exercises":[{"id":"module_test-m2-m2l1-form-initial-nun","type":"choice","format":"visual","prompt":"Quelle est la forme initiale (début de mot) de nūn ?","options":[{"id":"ok","ar":"نـ"},{"id":"oth","ar":"تـ","why":"C''est la forme initiale (début de mot) de tā’."},{"id":"sib","ar":"بـ","why":"C''est la forme initiale (début de mot) de bā’ (un point en dessous), pas de nūn (un point au-dessus)."},{"id":"iso","ar":"ـن","why":"Ce tracé n''est pas celui de la position initiale (début de mot)."}],"answer":"ok","explanation":"nūn en position initiale (début de mot) s''écrit نـ. Cette lettre se lie aux deux côtés.","reviewKey":"form:nun"},{"id":"module_test-m2-m2l1-form-medial-ya","type":"choice","format":"visual","prompt":"Quelle est la forme médiane (milieu de mot) de yā’ ?","options":[{"id":"sib","ar":"ـبـ","why":"C''est la forme médiane (milieu de mot) de bā’ (un point en dessous), pas de yā’ (deux points en dessous)."},{"id":"ok","ar":"ـيـ"},{"id":"iso","ar":"ـي","why":"Ce tracé n''est pas celui de la position médiane (milieu de mot)."},{"id":"oth","ar":"ـتـ","why":"C''est la forme médiane (milieu de mot) de tā’."}],"answer":"ok","explanation":"yā’ en position médiane (milieu de mot) s''écrit ـيـ. Cette lettre se lie aux deux côtés.","reviewKey":"form:ya"},{"id":"module_test-m2-m2l2-form-final-lam","type":"choice","format":"visual","prompt":"Quelle est la forme finale (fin de mot) de lām ?","options":[{"id":"oth","ar":"ـت","why":"C''est la forme finale (fin de mot) de tā’."},{"id":"sib","ar":"ـب","why":"C''est la forme finale (fin de mot) de bā’ (un point en dessous), pas de lām (aucun point)."},{"id":"ok","ar":"ـل"}],"answer":"ok","explanation":"lām en position finale (fin de mot) s''écrit ـل. Cette lettre se lie aux deux côtés.","reviewKey":"form:lam"},{"id":"module_test-m2-m2l2-form-initial-mim","type":"choice","format":"visual","prompt":"Quelle est la forme initiale (début de mot) de mīm ?","options":[{"id":"ok","ar":"مـ"},{"id":"sib","ar":"بـ","why":"C''est la forme initiale (début de mot) de bā’ (un point en dessous), pas de mīm (aucun point)."},{"id":"iso","ar":"ـم","why":"Ce tracé n''est pas celui de la position initiale (début de mot)."},{"id":"oth","ar":"تـ","why":"C''est la forme initiale (début de mot) de tā’."}],"answer":"ok","explanation":"mīm en position initiale (début de mot) s''écrit مـ. Cette lettre se lie aux deux côtés.","reviewKey":"form:mim"},{"id":"module_test-m2-m2l3-form-final-dal","type":"choice","format":"visual","prompt":"Quelle est la forme finale (fin de mot) de dāl ?","options":[{"id":"sib","ar":"ـذ","why":"C''est la forme finale (fin de mot) de dhāl (un point au-dessus), pas de dāl (aucun point)."},{"id":"ok","ar":"ـد"},{"id":"oth","ar":"ـا","why":"C''est la forme finale (fin de mot) de alif."}],"answer":"ok","explanation":"dāl en position finale (fin de mot) s''écrit ـد. Cette lettre ne se lie jamais à la lettre suivante : sa forme initiale est identique à la forme isolée.","reviewKey":"form:dal"},{"id":"module_test-m2-m2l3-form-medial-waw","type":"choice","format":"visual","prompt":"Quelle est la forme médiane (milieu de mot) de wāw ?","options":[{"id":"ok","ar":"ـو"},{"id":"oth","ar":"ـا","why":"C''est la forme médiane (milieu de mot) de alif."},{"id":"sib","ar":"ـبـ","why":"C''est la forme médiane (milieu de mot) de bā’ (un point en dessous), pas de wāw (aucun point)."},{"id":"iso","ar":"و","why":"Ce tracé n''est pas celui de la position médiane (milieu de mot)."}],"answer":"ok","explanation":"wāw en position médiane (milieu de mot) s''écrit ـو. Cette lettre ne se lie jamais à la lettre suivante : sa forme initiale est identique à la forme isolée.","reviewKey":"form:waw"},{"id":"module_test-m2-m2l4-form-medial-ayn","type":"choice","format":"visual","prompt":"Quelle est la forme médiane (milieu de mot) de ʿayn ?","options":[{"id":"ok","ar":"ـعـ"},{"id":"oth","ar":"ـبـ","why":"C''est la forme médiane (milieu de mot) de bā’."},{"id":"sib","ar":"ـغـ","why":"C''est la forme médiane (milieu de mot) de ghayn (un point au-dessus), pas de ʿayn (aucun point)."},{"id":"iso","ar":"ـع","why":"Ce tracé n''est pas celui de la position médiane (milieu de mot)."}],"answer":"ok","explanation":"ʿayn en position médiane (milieu de mot) s''écrit ـعـ. Cette lettre se lie aux deux côtés.","reviewKey":"form:ayn"},{"id":"module_test-m2-m2l4-form-final-kaf","type":"choice","format":"visual","prompt":"Quelle est la forme finale (fin de mot) de kāf ?","options":[{"id":"oth","ar":"ـت","why":"C''est la forme finale (fin de mot) de tā’."},{"id":"sib","ar":"ـب","why":"C''est la forme finale (fin de mot) de bā’ (un point en dessous), pas de kāf (aucun point)."},{"id":"ok","ar":"ـك"}],"answer":"ok","explanation":"kāf en position finale (fin de mot) s''écrit ـك. Cette lettre se lie aux deux côtés.","reviewKey":"form:kaf"}],"summary":["Résultat enregistré dans votre progression.","Les notions manquées sont ajoutées à vos révisions."]}'::jsonb) on conflict (lesson_id) do update set content = excluded.content, version = public.lesson_contents.version + 1, updated_at = now();
