insert into public.lessons (id, module_id, position, title_fr, objective_fr, difficulty, est_minutes, kind, published) values ('m3l1', 3, 1, 'La fatḥa : le son « a »', 'Lire une consonne portant une fatḥa', 1, 6, 'lesson', true) on conflict (id) do update set title_fr = excluded.title_fr, objective_fr = excluded.objective_fr, difficulty = excluded.difficulty, est_minutes = excluded.est_minutes, kind = excluded.kind, position = excluded.position;
insert into public.lesson_contents (lesson_id, content) values ('m3l1', '{"steps":[{"kind":"explain","text":"La fatḥa ( ـَ ) est un petit trait oblique AU-DESSUS de la consonne. Elle se prononce « a » bref."},{"kind":"example","ar":"بَ","translit":"ba","audio":"syll:ba-a"},{"kind":"example","ar":"تَ","translit":"ta","audio":"syll:ta-a"},{"kind":"example","ar":"كَ","translit":"ka","audio":"syll:kaf-a"},{"kind":"example","ar":"سَ","translit":"sa","audio":"syll:sin-a"},{"kind":"example","ar":"مَ","translit":"ma","audio":"syll:mim-a"},{"kind":"tip","text":"Les voyelles brèves ne sont pas des lettres : ce sont de petits signes placés au-dessus ou en dessous de la consonne. Dans le Coran, elles sont toujours écrites."}],"exercises":[{"id":"m3l1-syl-ba-a","type":"choice","format":"syllable","prompt":"Comment se lit cette syllabe ?","options":[{"id":"b","label":"bi","why":"« bi » s’écrirait avec une kasra (petit trait en dessous)."},{"id":"a","label":"ba"},{"id":"c","label":"bu","why":"« bu » s’écrirait avec une ḍamma (petit wāw au-dessus)."}],"answer":"a","explanation":"بَ : la lettre bā’ porte une fatḥa, on lit « ba ».","ar":"بَ","audio":"syll:ba-a","reviewKey":"haraka:a"},{"id":"m3l1-syl-ta-a","type":"choice","format":"syllable","prompt":"Comment se lit cette syllabe ?","options":[{"id":"c","label":"tu","why":"« tu » s’écrirait avec une ḍamma (petit wāw au-dessus)."},{"id":"a","label":"ta"},{"id":"b","label":"ti","why":"« ti » s’écrirait avec une kasra (petit trait en dessous)."}],"answer":"a","explanation":"تَ : la lettre tā’ porte une fatḥa, on lit « ta ».","ar":"تَ","audio":"syll:ta-a","reviewKey":"haraka:a"},{"id":"m3l1-syl-kaf-a","type":"choice","format":"syllable","prompt":"Comment se lit cette syllabe ?","options":[{"id":"c","label":"ku","why":"« ku » s’écrirait avec une ḍamma (petit wāw au-dessus)."},{"id":"b","label":"ki","why":"« ki » s’écrirait avec une kasra (petit trait en dessous)."},{"id":"a","label":"ka"}],"answer":"a","explanation":"كَ : la lettre kāf porte une fatḥa, on lit « ka ».","ar":"كَ","audio":"syll:kaf-a","reviewKey":"haraka:a"},{"id":"m3l1-syl-sin-a","type":"choice","format":"syllable","prompt":"Comment se lit cette syllabe ?","options":[{"id":"a","label":"sa"},{"id":"c","label":"su","why":"« su » s’écrirait avec une ḍamma (petit wāw au-dessus)."},{"id":"b","label":"si","why":"« si » s’écrirait avec une kasra (petit trait en dessous)."}],"answer":"a","explanation":"سَ : la lettre sīn porte une fatḥa, on lit « sa ».","ar":"سَ","audio":"syll:sin-a","reviewKey":"haraka:a"},{"id":"m3l1-syl-mim-a","type":"choice","format":"syllable","prompt":"Comment se lit cette syllabe ?","options":[{"id":"c","label":"mu","why":"« mu » s’écrirait avec une ḍamma (petit wāw au-dessus)."},{"id":"b","label":"mi","why":"« mi » s’écrirait avec une kasra (petit trait en dessous)."},{"id":"a","label":"ma"}],"answer":"a","explanation":"مَ : la lettre mīm porte une fatḥa, on lit « ma ».","ar":"مَ","audio":"syll:mim-a","reviewKey":"haraka:a"}],"summary":["fatḥa = « a » bref."]}'::jsonb) on conflict (lesson_id) do update set content = excluded.content, version = public.lesson_contents.version + 1, updated_at = now();
insert into public.lessons (id, module_id, position, title_fr, objective_fr, difficulty, est_minutes, kind, published) values ('m3l2', 3, 2, 'La kasra : le son « i »', 'Lire une consonne portant une kasra', 1, 6, 'lesson', true) on conflict (id) do update set title_fr = excluded.title_fr, objective_fr = excluded.objective_fr, difficulty = excluded.difficulty, est_minutes = excluded.est_minutes, kind = excluded.kind, position = excluded.position;
insert into public.lesson_contents (lesson_id, content) values ('m3l2', '{"steps":[{"kind":"explain","text":"La kasra ( ـِ ) est un petit trait oblique EN DESSOUS de la consonne. Elle se prononce « i » bref."},{"kind":"example","ar":"بِ","translit":"bi","audio":"syll:ba-i"},{"kind":"example","ar":"نِ","translit":"ni","audio":"syll:nun-i"},{"kind":"example","ar":"لِ","translit":"li","audio":"syll:lam-i"},{"kind":"example","ar":"فِ","translit":"fi","audio":"syll:fa-i"},{"kind":"example","ar":"دِ","translit":"di","audio":"syll:dal-i"},{"kind":"tip","text":"Les voyelles brèves ne sont pas des lettres : ce sont de petits signes placés au-dessus ou en dessous de la consonne. Dans le Coran, elles sont toujours écrites."}],"exercises":[{"id":"m3l2-syl-ba-i","type":"choice","format":"syllable","prompt":"Comment se lit cette syllabe ?","options":[{"id":"c","label":"bu","why":"« bu » s’écrirait avec une ḍamma (petit wāw au-dessus)."},{"id":"b","label":"ba","why":"« ba » s’écrirait avec une fatḥa (petit trait au-dessus)."},{"id":"a","label":"bi"}],"answer":"a","explanation":"بِ : la lettre bā’ porte une kasra, on lit « bi ».","ar":"بِ","audio":"syll:ba-i","reviewKey":"haraka:i"},{"id":"m3l2-syl-nun-i","type":"choice","format":"syllable","prompt":"Comment se lit cette syllabe ?","options":[{"id":"a","label":"ni"},{"id":"c","label":"nu","why":"« nu » s’écrirait avec une ḍamma (petit wāw au-dessus)."},{"id":"b","label":"na","why":"« na » s’écrirait avec une fatḥa (petit trait au-dessus)."}],"answer":"a","explanation":"نِ : la lettre nūn porte une kasra, on lit « ni ».","ar":"نِ","audio":"syll:nun-i","reviewKey":"haraka:i"},{"id":"m3l2-syl-lam-i","type":"choice","format":"syllable","prompt":"Comment se lit cette syllabe ?","options":[{"id":"b","label":"la","why":"« la » s’écrirait avec une fatḥa (petit trait au-dessus)."},{"id":"c","label":"lu","why":"« lu » s’écrirait avec une ḍamma (petit wāw au-dessus)."},{"id":"a","label":"li"}],"answer":"a","explanation":"لِ : la lettre lām porte une kasra, on lit « li ».","ar":"لِ","audio":"syll:lam-i","reviewKey":"haraka:i"},{"id":"m3l2-syl-fa-i","type":"choice","format":"syllable","prompt":"Comment se lit cette syllabe ?","options":[{"id":"b","label":"fa","why":"« fa » s’écrirait avec une fatḥa (petit trait au-dessus)."},{"id":"a","label":"fi"},{"id":"c","label":"fu","why":"« fu » s’écrirait avec une ḍamma (petit wāw au-dessus)."}],"answer":"a","explanation":"فِ : la lettre fā’ porte une kasra, on lit « fi ».","ar":"فِ","audio":"syll:fa-i","reviewKey":"haraka:i"},{"id":"m3l2-syl-dal-i","type":"choice","format":"syllable","prompt":"Comment se lit cette syllabe ?","options":[{"id":"a","label":"di"},{"id":"c","label":"du","why":"« du » s’écrirait avec une ḍamma (petit wāw au-dessus)."},{"id":"b","label":"da","why":"« da » s’écrirait avec une fatḥa (petit trait au-dessus)."}],"answer":"a","explanation":"دِ : la lettre dāl porte une kasra, on lit « di ».","ar":"دِ","audio":"syll:dal-i","reviewKey":"haraka:i"},{"id":"m3l2r-syl-ta-a","type":"choice","format":"syllable","prompt":"Comment se lit cette syllabe ?","options":[{"id":"a","label":"ta"},{"id":"c","label":"tu","why":"« tu » s’écrirait avec une ḍamma (petit wāw au-dessus)."},{"id":"b","label":"ti","why":"« ti » s’écrirait avec une kasra (petit trait en dessous)."}],"answer":"a","explanation":"تَ : la lettre tā’ porte une fatḥa, on lit « ta ».","ar":"تَ","audio":"syll:ta-a","reviewKey":"haraka:a"}],"summary":["kasra = « i » bref."]}'::jsonb) on conflict (lesson_id) do update set content = excluded.content, version = public.lesson_contents.version + 1, updated_at = now();
insert into public.lessons (id, module_id, position, title_fr, objective_fr, difficulty, est_minutes, kind, published) values ('m3l3', 3, 3, 'La ḍamma : le son « ou »', 'Lire une consonne portant une ḍamma', 1, 6, 'lesson', true) on conflict (id) do update set title_fr = excluded.title_fr, objective_fr = excluded.objective_fr, difficulty = excluded.difficulty, est_minutes = excluded.est_minutes, kind = excluded.kind, position = excluded.position;
insert into public.lesson_contents (lesson_id, content) values ('m3l3', '{"steps":[{"kind":"explain","text":"La ḍamma ( ـُ ) ressemble à un petit wāw placé AU-DESSUS de la consonne. Elle se prononce « ou » bref (transcrit « u »)."},{"kind":"example","ar":"بُ","translit":"bu","audio":"syll:ba-u"},{"kind":"example","ar":"قُ","translit":"qu","audio":"syll:qaf-u"},{"kind":"example","ar":"رُ","translit":"ru","audio":"syll:ra-u"},{"kind":"example","ar":"هُ","translit":"hu","audio":"syll:ha-u"},{"kind":"example","ar":"جُ","translit":"ju","audio":"syll:jim-u"},{"kind":"tip","text":"Les voyelles brèves ne sont pas des lettres : ce sont de petits signes placés au-dessus ou en dessous de la consonne. Dans le Coran, elles sont toujours écrites."}],"exercises":[{"id":"m3l3-syl-ba-u","type":"choice","format":"syllable","prompt":"Comment se lit cette syllabe ?","options":[{"id":"a","label":"bu"},{"id":"b","label":"ba","why":"« ba » s’écrirait avec une fatḥa (petit trait au-dessus)."},{"id":"c","label":"bi","why":"« bi » s’écrirait avec une kasra (petit trait en dessous)."}],"answer":"a","explanation":"بُ : la lettre bā’ porte une ḍamma, on lit « bu ».","ar":"بُ","audio":"syll:ba-u","reviewKey":"haraka:u"},{"id":"m3l3-syl-qaf-u","type":"choice","format":"syllable","prompt":"Comment se lit cette syllabe ?","options":[{"id":"a","label":"qu"},{"id":"b","label":"qa","why":"« qa » s’écrirait avec une fatḥa (petit trait au-dessus)."},{"id":"c","label":"qi","why":"« qi » s’écrirait avec une kasra (petit trait en dessous)."}],"answer":"a","explanation":"قُ : la lettre qāf porte une ḍamma, on lit « qu ».","ar":"قُ","audio":"syll:qaf-u","reviewKey":"haraka:u"},{"id":"m3l3-syl-ra-u","type":"choice","format":"syllable","prompt":"Comment se lit cette syllabe ?","options":[{"id":"b","label":"ra","why":"« ra » s’écrirait avec une fatḥa (petit trait au-dessus)."},{"id":"c","label":"ri","why":"« ri » s’écrirait avec une kasra (petit trait en dessous)."},{"id":"a","label":"ru"}],"answer":"a","explanation":"رُ : la lettre rā’ porte une ḍamma, on lit « ru ».","ar":"رُ","audio":"syll:ra-u","reviewKey":"haraka:u"},{"id":"m3l3-syl-ha-u","type":"choice","format":"syllable","prompt":"Comment se lit cette syllabe ?","options":[{"id":"a","label":"hu"},{"id":"b","label":"ha","why":"« ha » s’écrirait avec une fatḥa (petit trait au-dessus)."},{"id":"c","label":"hi","why":"« hi » s’écrirait avec une kasra (petit trait en dessous)."}],"answer":"a","explanation":"هُ : la lettre hā’ porte une ḍamma, on lit « hu ».","ar":"هُ","audio":"syll:ha-u","reviewKey":"haraka:u"},{"id":"m3l3-syl-jim-u","type":"choice","format":"syllable","prompt":"Comment se lit cette syllabe ?","options":[{"id":"c","label":"ji","why":"« ji » s’écrirait avec une kasra (petit trait en dessous)."},{"id":"b","label":"ja","why":"« ja » s’écrirait avec une fatḥa (petit trait au-dessus)."},{"id":"a","label":"ju"}],"answer":"a","explanation":"جُ : la lettre jīm porte une ḍamma, on lit « ju ».","ar":"جُ","audio":"syll:jim-u","reviewKey":"haraka:u"},{"id":"m3l3r-syl-kaf-i","type":"choice","format":"syllable","prompt":"Comment se lit cette syllabe ?","options":[{"id":"b","label":"ka","why":"« ka » s’écrirait avec une fatḥa (petit trait au-dessus)."},{"id":"a","label":"ki"},{"id":"c","label":"ku","why":"« ku » s’écrirait avec une ḍamma (petit wāw au-dessus)."}],"answer":"a","explanation":"كِ : la lettre kāf porte une kasra, on lit « ki ».","ar":"كِ","audio":"syll:kaf-i","reviewKey":"haraka:i"}],"summary":["ḍamma = « u » bref."]}'::jsonb) on conflict (lesson_id) do update set content = excluded.content, version = public.lesson_contents.version + 1, updated_at = now();
insert into public.lessons (id, module_id, position, title_fr, objective_fr, difficulty, est_minutes, kind, published) values ('m3l4', 3, 4, 'Le sukūn : pas de voyelle', 'Reconnaître une consonne sans voyelle et lire une syllabe fermée', 2, 6, 'lesson', true) on conflict (id) do update set title_fr = excluded.title_fr, objective_fr = excluded.objective_fr, difficulty = excluded.difficulty, est_minutes = excluded.est_minutes, kind = excluded.kind, position = excluded.position;
insert into public.lesson_contents (lesson_id, content) values ('m3l4', '{"steps":[{"kind":"explain","text":"Le sukūn ( ـْ ) est un petit cercle au-dessus de la consonne. Il indique qu’elle ne porte AUCUNE voyelle : elle ferme la syllabe précédente."},{"kind":"example","ar":"مِنْ","translit":"min","fr":"de, à partir de","audio":"word:min"},{"kind":"example","ar":"قُلْ","translit":"qul","fr":"dis !","audio":"word:qul"},{"kind":"example","ar":"لَمْ","translit":"lam","fr":"ne… pas (au passé)","audio":"word:lam"},{"kind":"tip","text":"Sukūn = arrêt sur la consonne. Ne rajoutez pas de « e » muet à la française : on dit « min », pas « mine »."}],"exercises":[{"id":"m3l4-1","type":"choice","format":"fill","prompt":"Comment se lit ce mot ?","options":[{"id":"a","label":"min"},{"id":"c","label":"mun","why":"م porte une kasra (trait dessous), donc « mi », pas « mu »."},{"id":"b","label":"mina","why":"Le sukūn sur ن interdit toute voyelle après lui."}],"answer":"a","explanation":"مِ (mi) + نْ (n sans voyelle) = « min ».","ar":"مِنْ","audio":"word:min","reviewKey":"word:min"},{"id":"m3l4-2","type":"choice","format":"fill","prompt":"Comment se lit ce mot ?","options":[{"id":"a","label":"qul"},{"id":"c","label":"qulu","why":"ل porte un sukūn : aucune voyelle finale."},{"id":"b","label":"qal","why":"ق porte une ḍamma (petit wāw), pas une fatḥa."}],"answer":"a","explanation":"قُ (qu) + لْ (l) = « qul ».","ar":"قُلْ","audio":"word:qul","reviewKey":"word:qul"},{"id":"m3l4-3","type":"choice","format":"fill","prompt":"Comment se lit ce mot ?","options":[{"id":"c","label":"lama","why":"م porte un sukūn."},{"id":"b","label":"lim","why":"ل porte une fatḥa (trait au-dessus), donc « la »."},{"id":"a","label":"lam"}],"answer":"a","explanation":"لَ (la) + مْ (m) = « lam ».","ar":"لَمْ","audio":"word:lam","reviewKey":"word:lam"},{"id":"m3l4-4","type":"choice","format":"mcq","prompt":"Que signifie le petit cercle ـْ au-dessus d’une lettre ?","options":[{"id":"b","label":"La lettre est doublée","why":"Le doublement est indiqué par la shadda ( ـّ ), un petit « w » arrondi."},{"id":"a","label":"La lettre ne porte aucune voyelle"},{"id":"c","label":"Il faut prononcer « o »","why":"L’arabe classique n’a pas de voyelle « o » : le cercle est le sukūn."}],"answer":"a","explanation":"Le sukūn indique l’absence de voyelle.","reviewKey":"haraka:sukun"}],"summary":["Sukūn ( ـْ ) = consonne sans voyelle.","Il ferme la syllabe : مِنْ = min."]}'::jsonb) on conflict (lesson_id) do update set content = excluded.content, version = public.lesson_contents.version + 1, updated_at = now();
insert into public.lessons (id, module_id, position, title_fr, objective_fr, difficulty, est_minutes, kind, published) values ('m3l5', 3, 5, 'La shadda : la consonne doublée', 'Prononcer une consonne doublée', 2, 7, 'lesson', true) on conflict (id) do update set title_fr = excluded.title_fr, objective_fr = excluded.objective_fr, difficulty = excluded.difficulty, est_minutes = excluded.est_minutes, kind = excluded.kind, position = excluded.position;
insert into public.lesson_contents (lesson_id, content) values ('m3l5', '{"steps":[{"kind":"explain","text":"La shadda ( ـّ ) ressemble à un petit « w » au-dessus de la lettre. Elle indique que la consonne est prononcée deux fois : une première fois sans voyelle, une seconde fois avec la voyelle qui accompagne la shadda."},{"kind":"example","ar":"ثُمَّ","translit":"thumma","fr":"ensuite","audio":"word:thumma"},{"kind":"example","ar":"إِنَّ","translit":"inna","fr":"certes","audio":"word:inna"},{"kind":"example","ar":"رَبّ","translit":"rabb","fr":"seigneur","audio":"word:rabb"},{"kind":"tip","text":"Tenez la consonne un peu plus longtemps : « thum-ma », « in-na ». Oublier la shadda peut changer le sens du mot."}],"exercises":[{"id":"m3l5-1","type":"choice","format":"fill","prompt":"Comment se lit ce mot ?","options":[{"id":"a","label":"thumma"},{"id":"b","label":"thuma","why":"La shadda sur م impose de la prononcer deux fois : « thum-ma »."},{"id":"c","label":"thamma","why":"ث porte une ḍamma : « thu »."}],"answer":"a","explanation":"ثُ (thu) + مَّ (m-ma) = « thumma ».","ar":"ثُمَّ","audio":"word:thumma","reviewKey":"word:thumma"},{"id":"m3l5-2","type":"choice","format":"fill","prompt":"Comment se lit ce mot ?","options":[{"id":"b","label":"ina","why":"La shadda double le ن : « in-na »."},{"id":"c","label":"anna","why":"L’alif porte une hamza avec kasra (en dessous) : « i »."},{"id":"a","label":"inna"}],"answer":"a","explanation":"إِ (i) + نَّ (n-na) = « inna ».","ar":"إِنَّ","audio":"word:inna","reviewKey":"word:inna"},{"id":"m3l5-3","type":"choice","format":"mcq","prompt":"Que fait la shadda ( ـّ ) ?","options":[{"id":"a","label":"Elle double la consonne"},{"id":"c","label":"Elle supprime la voyelle","why":"C’est le rôle du sukūn ( ـْ )."},{"id":"b","label":"Elle allonge la voyelle","why":"L’allongement des voyelles se fait avec ا و ي (voyelles longues)."}],"answer":"a","explanation":"La shadda indique une consonne géminée (prononcée deux fois).","reviewKey":"haraka:shadda"},{"id":"m3l5-4","type":"choice","format":"visual","prompt":"Lequel de ces mots contient une shadda ?","options":[{"id":"b","ar":"قُلْ","why":"قُلْ contient un sukūn (petit cercle), pas une shadda."},{"id":"c","ar":"مِنْ","why":"مِنْ contient une kasra et un sukūn."},{"id":"a","ar":"ثُمَّ"}],"answer":"a","explanation":"Dans ثُمَّ, le م porte une shadda surmontée d’une fatḥa.","reviewKey":"haraka:shadda"}],"summary":["Shadda ( ـّ ) = consonne doublée.","ثُمَّ = thumma, إِنَّ = inna."]}'::jsonb) on conflict (lesson_id) do update set content = excluded.content, version = public.lesson_contents.version + 1, updated_at = now();
insert into public.lessons (id, module_id, position, title_fr, objective_fr, difficulty, est_minutes, kind, published) values ('m3l6', 3, 6, 'Le tanwīn : la voyelle suivie de « n »', 'Lire les trois formes du tanwīn', 2, 7, 'lesson', true) on conflict (id) do update set title_fr = excluded.title_fr, objective_fr = excluded.objective_fr, difficulty = excluded.difficulty, est_minutes = excluded.est_minutes, kind = excluded.kind, position = excluded.position;
insert into public.lesson_contents (lesson_id, content) values ('m3l6', '{"steps":[{"kind":"explain","text":"Le tanwīn est une voyelle doublée en fin de mot. Il se prononce comme la voyelle suivie d’un « n » : ـٌ = « un », ـٍ = « in », ـً = « an ». Il marque en général un nom indéfini (« un livre »)."},{"kind":"example","ar":"كِتَابٌ","translit":"kitābun","fr":"un livre (sujet)","audio":"word:kitabun"},{"kind":"example","ar":"كِتَابًا","translit":"kitāban","fr":"un livre (complément)","audio":"word:kitaban"},{"kind":"example","ar":"كِتَابٍ","translit":"kitābin","fr":"d’un livre (après préposition)","audio":"word:kitabin"},{"kind":"tip","text":"Le tanwīn « an » s’écrit souvent avec un alif muet après lui : كِتَابًا. Cet alif ne se prononce pas."}],"exercises":[{"id":"m3l6-1","type":"choice","format":"fill","prompt":"Comment se lit ce mot ?","options":[{"id":"b","label":"kitābin","why":"« in » s’écrirait avec deux traits en dessous ( ـٍ )."},{"id":"a","label":"kitābun"},{"id":"c","label":"kitāban","why":"« an » s’écrirait avec deux traits au-dessus ( ـً )."}],"answer":"a","explanation":"Deux ḍamma ( ـٌ ) = « un ».","ar":"كِتَابٌ","audio":"word:kitabun","reviewKey":"word:kitabun"},{"id":"m3l6-2","type":"choice","format":"fill","prompt":"Comment se lit ce mot ?","options":[{"id":"b","label":"kitābā","why":"Le tanwīn ajoute un « n » ; l’alif final est muet."},{"id":"c","label":"kitābun","why":"« un » s’écrirait avec une double ḍamma."},{"id":"a","label":"kitāban"}],"answer":"a","explanation":"Deux fatḥa ( ـً ) = « an », l’alif final ne se prononce pas.","ar":"كِتَابًا","audio":"word:kitaban","reviewKey":"word:kitaban"},{"id":"m3l6-3","type":"choice","format":"fill","prompt":"Comment se lit ce mot ?","options":[{"id":"c","label":"kitābun","why":"« un » serait une double ḍamma au-dessus."},{"id":"a","label":"kitābin"},{"id":"b","label":"kitābi","why":"Le tanwīn ajoute un « n » : « in »."}],"answer":"a","explanation":"Deux kasra ( ـٍ ) = « in ».","ar":"كِتَابٍ","audio":"word:kitabin","reviewKey":"word:kitabin"},{"id":"m3l6-4","type":"choice","format":"mcq","prompt":"Comment se prononce ـً ?","options":[{"id":"b","label":"« a »","why":"Le tanwīn ajoute toujours un « n »."},{"id":"c","label":"« in »","why":"« in » correspond à ـٍ (deux traits en dessous)."},{"id":"a","label":"« an »"}],"answer":"a","explanation":"Double fatḥa = « an ».","reviewKey":"haraka:tanwin"}],"summary":["ـٌ = un, ـً = an, ـٍ = in.","Le tanwīn marque souvent l’indéfini."]}'::jsonb) on conflict (lesson_id) do update set content = excluded.content, version = public.lesson_contents.version + 1, updated_at = now();
insert into public.lessons (id, module_id, position, title_fr, objective_fr, difficulty, est_minutes, kind, published) values ('m3l7', 3, 7, 'Les voyelles longues', 'Lire ā, ī, ū et les distinguer des voyelles brèves', 2, 7, 'lesson', true) on conflict (id) do update set title_fr = excluded.title_fr, objective_fr = excluded.objective_fr, difficulty = excluded.difficulty, est_minutes = excluded.est_minutes, kind = excluded.kind, position = excluded.position;
insert into public.lesson_contents (lesson_id, content) values ('m3l7', '{"steps":[{"kind":"explain","text":"Une voyelle longue s’obtient en faisant suivre une voyelle brève de la lettre correspondante : fatḥa + ا = « ā », kasra + ي = « ī », ḍamma + و = « ū ». Elle dure environ deux fois plus longtemps."},{"kind":"example","ar":"بَا","translit":"bā"},{"kind":"example","ar":"بِي","translit":"bī"},{"kind":"example","ar":"بُو","translit":"bū"},{"kind":"example","ar":"قَالَ","translit":"qāla","fr":"il a dit","audio":"word:qala"},{"kind":"example","ar":"دِين","translit":"dīn","fr":"religion, rétribution","audio":"word:din"},{"kind":"example","ar":"نُور","translit":"nūr","fr":"lumière","audio":"word:nur"},{"kind":"tip","text":"La longueur change le sens : qala et qāla ne sont pas le même mot. Comptez « deux temps » sur une voyelle longue."}],"exercises":[{"id":"m3l7-1","type":"choice","format":"fill","prompt":"Comment se lit ce mot ?","options":[{"id":"a","label":"qāla"},{"id":"b","label":"qala","why":"L’alif après la fatḥa allonge le « a » : « qā »."},{"id":"c","label":"qīla","why":"ق porte une fatḥa, pas une kasra."}],"answer":"a","explanation":"قَا (qā) + لَ (la) = « qāla ».","ar":"قَالَ","audio":"word:qala","reviewKey":"word:qala"},{"id":"m3l7-2","type":"choice","format":"fill","prompt":"Comment se lit ce mot ?","options":[{"id":"c","label":"nawr","why":"Le و ne porte pas de sukūn ici : il sert de voyelle longue."},{"id":"a","label":"nūr"},{"id":"b","label":"nur","why":"Le و après la ḍamma allonge le son : « nū »."}],"answer":"a","explanation":"نُو (nū) + ر = « nūr ».","ar":"نُور","audio":"word:nur","reviewKey":"word:nur"},{"id":"m3l7-3","type":"choice","format":"fill","prompt":"Comment se lit ce mot ?","options":[{"id":"a","label":"dīn"},{"id":"b","label":"din","why":"Le ي après la kasra allonge le son : « dī »."},{"id":"c","label":"dayn","why":"د porte une kasra : « di », allongée par ي."}],"answer":"a","explanation":"دِي (dī) + ن = « dīn ».","ar":"دِين","audio":"word:din","reviewKey":"word:din"},{"id":"m3l7-4","type":"choice","format":"mcq","prompt":"Quelle lettre allonge la kasra ?","options":[{"id":"a","ar":"ي"},{"id":"b","ar":"ا","why":"ا allonge la fatḥa (« ā »)."},{"id":"c","ar":"و","why":"و allonge la ḍamma (« ū »)."}],"answer":"a","explanation":"kasra + ي = « ī ».","reviewKey":"rule:long-vowels"}],"summary":["ـَا = ā, ـِي = ī, ـُو = ū.","Une voyelle longue dure deux temps."]}'::jsonb) on conflict (lesson_id) do update set content = excluded.content, version = public.lesson_contents.version + 1, updated_at = now();
insert into public.lessons (id, module_id, position, title_fr, objective_fr, difficulty, est_minutes, kind, published) values ('m3l8', 3, 8, 'Initiation au tajwīd : madd, lettres solaires et lunaires', 'Appliquer trois règles élémentaires de lecture', 3, 9, 'lesson', true) on conflict (id) do update set title_fr = excluded.title_fr, objective_fr = excluded.objective_fr, difficulty = excluded.difficulty, est_minutes = excluded.est_minutes, kind = excluded.kind, position = excluded.position;
insert into public.lesson_contents (lesson_id, content) values ('m3l8', '{"steps":[{"kind":"explain","text":"Le tajwīd est l’ensemble des règles de récitation du Coran. C’est un domaine à part entière ; nous n’en voyons ici que trois règles de base, indispensables pour lire correctement."},{"kind":"explain","text":"1. Le madd naturel : une voyelle longue simple (ā, ī, ū) dure deux temps. Certains signes, comme le petit trait ondulé ( ـٓ ), indiquent un allongement plus long ; ils seront détaillés dans un cours de tajwīd."},{"kind":"explain","text":"2. L’article ال devant une lettre solaire : le lām ne se prononce pas et la lettre suivante est doublée (shadda). Devant une lettre lunaire, le lām se prononce avec un sukūn."},{"kind":"example","ar":"الشَّمْس","translit":"ash-shams","fr":"le soleil (lettre solaire ش)","audio":"word:ashshams"},{"kind":"example","ar":"الْقَمَر","translit":"al-qamar","fr":"la lune (lettre lunaire ق)","audio":"word:alqamar"},{"kind":"table","caption":"Les 14 lettres solaires","head":["Lettres"],"arCols":[0],"rows":[["ت ث د ذ ر ز س ش ص ض ط ظ ل ن"]]},{"kind":"explain","text":"3. La hamzat al-waṣl : l’alif de l’article ne se prononce que si l’on commence la lecture par ce mot. Au milieu d’une phrase, il s’efface et on enchaîne avec le mot précédent."},{"kind":"tip","text":"Astuce : les lettres solaires sont celles qui se prononcent avec la pointe de la langue près des dents."}],"exercises":[{"id":"m3l8-1","type":"choice","format":"fill","prompt":"Comment se lit ce mot ?","options":[{"id":"c","label":"ash-sham","why":"Le س final porte un sukūn mais se prononce bien."},{"id":"a","label":"ash-shams"},{"id":"b","label":"al-shams","why":"ش est une lettre solaire : le lām de l’article ne se prononce pas."}],"answer":"a","explanation":"ش est solaire : ل s’efface et ش est doublée.","ar":"الشَّمْس","audio":"word:ashshams","reviewKey":"word:ashshams"},{"id":"m3l8-2","type":"choice","format":"fill","prompt":"Comment se lit ce mot ?","options":[{"id":"a","label":"al-qamar"},{"id":"c","label":"al-qamr","why":"م porte une fatḥa : « ma »."},{"id":"b","label":"aq-qamar","why":"ق est une lettre lunaire : le lām se prononce."}],"answer":"a","explanation":"ق est lunaire : on prononce « al ».","ar":"الْقَمَر","audio":"word:alqamar","reviewKey":"word:alqamar"},{"id":"m3l8-3","type":"sort","prompt":"Lettre solaire ou lunaire ?","buckets":[{"id":"sun","label":"Solaire"},{"id":"moon","label":"Lunaire"}],"items":[{"id":"a","ar":"ن","bucket":"sun"},{"id":"b","ar":"ر","bucket":"sun"},{"id":"c","ar":"ت","bucket":"sun"},{"id":"d","ar":"ك","bucket":"moon"},{"id":"e","ar":"ب","bucket":"moon"},{"id":"f","ar":"ع","bucket":"moon"}],"explanation":"Solaires : ت ث د ذ ر ز س ش ص ض ط ظ ل ن. Toutes les autres sont lunaires.","reviewKey":"rule:sun-moon"},{"id":"m3l8-4","type":"choice","format":"mcq","prompt":"Combien de temps dure un madd naturel ?","options":[{"id":"c","label":"Six temps","why":"Les allongements plus longs relèvent de règles particulières, signalées par des signes."},{"id":"a","label":"Deux temps"},{"id":"b","label":"Un temps","why":"Un temps correspond à une voyelle brève."}],"answer":"a","explanation":"Le madd naturel (voyelle longue simple) dure deux temps.","reviewKey":"rule:madd"}],"summary":["Madd naturel : deux temps.","Lettre solaire : ل muet + doublement.","Hamzat al-waṣl : prononcée seulement en début de lecture."]}'::jsonb) on conflict (lesson_id) do update set content = excluded.content, version = public.lesson_contents.version + 1, updated_at = now();
insert into public.lessons (id, module_id, position, title_fr, objective_fr, difficulty, est_minutes, kind, published) values ('m3-test', 3, 99, 'Test du module 3 : voyelles et signes', 'Valider les acquis du module : 80 % de bonnes réponses sont nécessaires.', 2, 10, 'module_test', true) on conflict (id) do update set title_fr = excluded.title_fr, objective_fr = excluded.objective_fr, difficulty = excluded.difficulty, est_minutes = excluded.est_minutes, kind = excluded.kind, position = excluded.position;
insert into public.lesson_contents (lesson_id, content) values ('m3-test', '{"steps":[{"kind":"explain","text":"Ce test reprend les notions des leçons du module. Prenez votre temps : il n’y a pas de limite de durée et vous pourrez le repasser."}],"exercises":[{"id":"module_test-m3-m3l1-syl-ba-a","type":"choice","format":"syllable","prompt":"Comment se lit cette syllabe ?","options":[{"id":"b","label":"bi","why":"« bi » s’écrirait avec une kasra (petit trait en dessous)."},{"id":"a","label":"ba"},{"id":"c","label":"bu","why":"« bu » s’écrirait avec une ḍamma (petit wāw au-dessus)."}],"answer":"a","explanation":"بَ : la lettre bā’ porte une fatḥa, on lit « ba ».","ar":"بَ","audio":"syll:ba-a","reviewKey":"haraka:a"},{"id":"module_test-m3-m3l1-syl-sin-a","type":"choice","format":"syllable","prompt":"Comment se lit cette syllabe ?","options":[{"id":"a","label":"sa"},{"id":"c","label":"su","why":"« su » s’écrirait avec une ḍamma (petit wāw au-dessus)."},{"id":"b","label":"si","why":"« si » s’écrirait avec une kasra (petit trait en dessous)."}],"answer":"a","explanation":"سَ : la lettre sīn porte une fatḥa, on lit « sa ».","ar":"سَ","audio":"syll:sin-a","reviewKey":"haraka:a"},{"id":"module_test-m3-m3l2-syl-lam-i","type":"choice","format":"syllable","prompt":"Comment se lit cette syllabe ?","options":[{"id":"b","label":"la","why":"« la » s’écrirait avec une fatḥa (petit trait au-dessus)."},{"id":"c","label":"lu","why":"« lu » s’écrirait avec une ḍamma (petit wāw au-dessus)."},{"id":"a","label":"li"}],"answer":"a","explanation":"لِ : la lettre lām porte une kasra, on lit « li ».","ar":"لِ","audio":"syll:lam-i","reviewKey":"haraka:i"},{"id":"module_test-m3-m3l2-syl-nun-i","type":"choice","format":"syllable","prompt":"Comment se lit cette syllabe ?","options":[{"id":"a","label":"ni"},{"id":"c","label":"nu","why":"« nu » s’écrirait avec une ḍamma (petit wāw au-dessus)."},{"id":"b","label":"na","why":"« na » s’écrirait avec une fatḥa (petit trait au-dessus)."}],"answer":"a","explanation":"نِ : la lettre nūn porte une kasra, on lit « ni ».","ar":"نِ","audio":"syll:nun-i","reviewKey":"haraka:i"},{"id":"module_test-m3-m3l3r-syl-kaf-i","type":"choice","format":"syllable","prompt":"Comment se lit cette syllabe ?","options":[{"id":"b","label":"ka","why":"« ka » s’écrirait avec une fatḥa (petit trait au-dessus)."},{"id":"a","label":"ki"},{"id":"c","label":"ku","why":"« ku » s’écrirait avec une ḍamma (petit wāw au-dessus)."}],"answer":"a","explanation":"كِ : la lettre kāf porte une kasra, on lit « ki ».","ar":"كِ","audio":"syll:kaf-i","reviewKey":"haraka:i"},{"id":"module_test-m3-m3l3-syl-ba-u","type":"choice","format":"syllable","prompt":"Comment se lit cette syllabe ?","options":[{"id":"a","label":"bu"},{"id":"b","label":"ba","why":"« ba » s’écrirait avec une fatḥa (petit trait au-dessus)."},{"id":"c","label":"bi","why":"« bi » s’écrirait avec une kasra (petit trait en dessous)."}],"answer":"a","explanation":"بُ : la lettre bā’ porte une ḍamma, on lit « bu ».","ar":"بُ","audio":"syll:ba-u","reviewKey":"haraka:u"},{"id":"module_test-m3-m3l4-2","type":"choice","format":"fill","prompt":"Comment se lit ce mot ?","options":[{"id":"a","label":"qul"},{"id":"c","label":"qulu","why":"ل porte un sukūn : aucune voyelle finale."},{"id":"b","label":"qal","why":"ق porte une ḍamma (petit wāw), pas une fatḥa."}],"answer":"a","explanation":"قُ (qu) + لْ (l) = « qul ».","ar":"قُلْ","audio":"word:qul","reviewKey":"word:qul"},{"id":"module_test-m3-m3l4-1","type":"choice","format":"fill","prompt":"Comment se lit ce mot ?","options":[{"id":"a","label":"min"},{"id":"c","label":"mun","why":"م porte une kasra (trait dessous), donc « mi », pas « mu »."},{"id":"b","label":"mina","why":"Le sukūn sur ن interdit toute voyelle après lui."}],"answer":"a","explanation":"مِ (mi) + نْ (n sans voyelle) = « min ».","ar":"مِنْ","audio":"word:min","reviewKey":"word:min"},{"id":"module_test-m3-m3l5-2","type":"choice","format":"fill","prompt":"Comment se lit ce mot ?","options":[{"id":"b","label":"ina","why":"La shadda double le ن : « in-na »."},{"id":"c","label":"anna","why":"L’alif porte une hamza avec kasra (en dessous) : « i »."},{"id":"a","label":"inna"}],"answer":"a","explanation":"إِ (i) + نَّ (n-na) = « inna ».","ar":"إِنَّ","audio":"word:inna","reviewKey":"word:inna"},{"id":"module_test-m3-m3l5-4","type":"choice","format":"visual","prompt":"Lequel de ces mots contient une shadda ?","options":[{"id":"b","ar":"قُلْ","why":"قُلْ contient un sukūn (petit cercle), pas une shadda."},{"id":"c","ar":"مِنْ","why":"مِنْ contient une kasra et un sukūn."},{"id":"a","ar":"ثُمَّ"}],"answer":"a","explanation":"Dans ثُمَّ, le م porte une shadda surmontée d’une fatḥa.","reviewKey":"haraka:shadda"},{"id":"module_test-m3-m3l6-3","type":"choice","format":"fill","prompt":"Comment se lit ce mot ?","options":[{"id":"c","label":"kitābun","why":"« un » serait une double ḍamma au-dessus."},{"id":"a","label":"kitābin"},{"id":"b","label":"kitābi","why":"Le tanwīn ajoute un « n » : « in »."}],"answer":"a","explanation":"Deux kasra ( ـٍ ) = « in ».","ar":"كِتَابٍ","audio":"word:kitabin","reviewKey":"word:kitabin"},{"id":"module_test-m3-m3l6-2","type":"choice","format":"fill","prompt":"Comment se lit ce mot ?","options":[{"id":"b","label":"kitābā","why":"Le tanwīn ajoute un « n » ; l’alif final est muet."},{"id":"c","label":"kitābun","why":"« un » s’écrirait avec une double ḍamma."},{"id":"a","label":"kitāban"}],"answer":"a","explanation":"Deux fatḥa ( ـً ) = « an », l’alif final ne se prononce pas.","ar":"كِتَابًا","audio":"word:kitaban","reviewKey":"word:kitaban"},{"id":"module_test-m3-m3l7-3","type":"choice","format":"fill","prompt":"Comment se lit ce mot ?","options":[{"id":"a","label":"dīn"},{"id":"b","label":"din","why":"Le ي après la kasra allonge le son : « dī »."},{"id":"c","label":"dayn","why":"د porte une kasra : « di », allongée par ي."}],"answer":"a","explanation":"دِي (dī) + ن = « dīn ».","ar":"دِين","audio":"word:din","reviewKey":"word:din"},{"id":"module_test-m3-m3l7-4","type":"choice","format":"mcq","prompt":"Quelle lettre allonge la kasra ?","options":[{"id":"a","ar":"ي"},{"id":"b","ar":"ا","why":"ا allonge la fatḥa (« ā »)."},{"id":"c","ar":"و","why":"و allonge la ḍamma (« ū »)."}],"answer":"a","explanation":"kasra + ي = « ī ».","reviewKey":"rule:long-vowels"},{"id":"module_test-m3-m3l8-3","type":"sort","prompt":"Lettre solaire ou lunaire ?","buckets":[{"id":"sun","label":"Solaire"},{"id":"moon","label":"Lunaire"}],"items":[{"id":"a","ar":"ن","bucket":"sun"},{"id":"b","ar":"ر","bucket":"sun"},{"id":"c","ar":"ت","bucket":"sun"},{"id":"d","ar":"ك","bucket":"moon"},{"id":"e","ar":"ب","bucket":"moon"},{"id":"f","ar":"ع","bucket":"moon"}],"explanation":"Solaires : ت ث د ذ ر ز س ش ص ض ط ظ ل ن. Toutes les autres sont lunaires.","reviewKey":"rule:sun-moon"},{"id":"module_test-m3-m3l8-1","type":"choice","format":"fill","prompt":"Comment se lit ce mot ?","options":[{"id":"c","label":"ash-sham","why":"Le س final porte un sukūn mais se prononce bien."},{"id":"a","label":"ash-shams"},{"id":"b","label":"al-shams","why":"ش est une lettre solaire : le lām de l’article ne se prononce pas."}],"answer":"a","explanation":"ش est solaire : ل s’efface et ش est doublée.","ar":"الشَّمْس","audio":"word:ashshams","reviewKey":"word:ashshams"}],"summary":["Résultat enregistré dans votre progression.","Les notions manquées sont ajoutées à vos révisions."]}'::jsonb) on conflict (lesson_id) do update set content = excluded.content, version = public.lesson_contents.version + 1, updated_at = now();
insert into public.modules (id, course_id, position, title_fr, subtitle_fr, tier, published) values (4, 1, 4, 'Apprendre à lire', 'Syllabes, mots, article', 'free', true) on conflict (id) do update set title_fr = excluded.title_fr, subtitle_fr = excluded.subtitle_fr, tier = excluded.tier;
insert into public.lessons (id, module_id, position, title_fr, objective_fr, difficulty, est_minutes, kind, published) values ('m4l1', 4, 1, 'Lire des syllabes ouvertes', 'Assembler trois syllabes consonne + voyelle', 1, 7, 'lesson', true) on conflict (id) do update set title_fr = excluded.title_fr, objective_fr = excluded.objective_fr, difficulty = excluded.difficulty, est_minutes = excluded.est_minutes, kind = excluded.kind, position = excluded.position;
insert into public.lesson_contents (lesson_id, content) values ('m4l1', '{"steps":[{"kind":"explain","text":"Une syllabe ouverte = une consonne + une voyelle brève. Beaucoup de verbes arabes au passé sont formés de trois syllabes ouvertes : c’est un excellent entraînement."},{"kind":"example","ar":"كَتَبَ","translit":"ka-ta-ba","fr":"il a écrit","audio":"word:kataba"},{"kind":"example","ar":"ذَهَبَ","translit":"dha-ha-ba","fr":"il est allé","audio":"word:dhahaba"},{"kind":"example","ar":"جَلَسَ","translit":"ja-la-sa","fr":"il s’est assis","audio":"word:jalasa"},{"kind":"example","ar":"خَلَقَ","translit":"kha-la-qa","fr":"il a créé","audio":"word:khalaqa"},{"kind":"tip","text":"Lisez lettre par lettre de droite à gauche, puis accélérez jusqu’à lire le mot d’un seul souffle."}],"exercises":[{"id":"m4l1-1","type":"order","prompt":"Reconstituez le mot « kataba » syllabe par syllabe (de droite à gauche)","ar":"كَتَبَ","audio":"word:kataba","pieces":[{"id":"p0","ar":"كَ","label":"ka"},{"id":"p1","ar":"تَ","label":"ta"},{"id":"p2","ar":"بَ","label":"ba"}],"explanation":"كَتَبَ = كَ (ka) + تَ (ta) + بَ (ba). On lit de droite à gauche."},{"id":"m4l1-2","type":"order","prompt":"Reconstituez le mot « khalaqa » syllabe par syllabe (de droite à gauche)","ar":"خَلَقَ","audio":"word:khalaqa","pieces":[{"id":"p0","ar":"خَ","label":"kha"},{"id":"p1","ar":"لَ","label":"la"},{"id":"p2","ar":"قَ","label":"qa"}],"explanation":"خَلَقَ = خَ (kha) + لَ (la) + قَ (qa). On lit de droite à gauche."},{"id":"m4l1-3","type":"choice","format":"fill","prompt":"Comment se lit ce mot ?","options":[{"id":"b","label":"dahaba","why":"ذ (point au-dessus) se prononce « dh », comme l’anglais « this »."},{"id":"a","label":"dhahaba"},{"id":"c","label":"dhahiba","why":"ه porte une fatḥa : « ha »."}],"answer":"a","explanation":"ذَ (dha) + هَ (ha) + بَ (ba).","ar":"ذَهَبَ","audio":"word:dhahaba","reviewKey":"word:dhahaba"},{"id":"m4l1-4","type":"choice","format":"fill","prompt":"Comment se lit ce mot ?","options":[{"id":"b","label":"jalisa","why":"ل porte une fatḥa (trait au-dessus)."},{"id":"a","label":"jalasa"},{"id":"c","label":"halasa","why":"ج a un point dessous : « j »."}],"answer":"a","explanation":"جَ (ja) + لَ (la) + سَ (sa).","ar":"جَلَسَ","audio":"word:jalasa","reviewKey":"word:jalasa"}],"summary":["Syllabe ouverte = consonne + voyelle.","كَتَبَ = ka-ta-ba."]}'::jsonb) on conflict (lesson_id) do update set content = excluded.content, version = public.lesson_contents.version + 1, updated_at = now();
insert into public.lessons (id, module_id, position, title_fr, objective_fr, difficulty, est_minutes, kind, published) values ('m4l2', 4, 2, 'Lire des syllabes fermées', 'Lire des mots contenant un sukūn', 2, 7, 'lesson', true) on conflict (id) do update set title_fr = excluded.title_fr, objective_fr = excluded.objective_fr, difficulty = excluded.difficulty, est_minutes = excluded.est_minutes, kind = excluded.kind, position = excluded.position;
insert into public.lesson_contents (lesson_id, content) values ('m4l2', '{"steps":[{"kind":"explain","text":"Une syllabe fermée = consonne + voyelle + consonne sans voyelle (sukūn)."},{"kind":"example","ar":"عَبْد","translit":"ʿabd","fr":"serviteur","audio":"word:abd"},{"kind":"example","ar":"قَلْب","translit":"qalb","fr":"cœur","audio":"word:qalb"},{"kind":"example","ar":"شَمْس","translit":"shams","fr":"soleil","audio":"word:shams"},{"kind":"example","ar":"هَلْ","translit":"hal","fr":"est-ce que ?","audio":"word:hal"}],"exercises":[{"id":"m4l2-1","type":"choice","format":"fill","prompt":"Comment se lit ce mot ?","options":[{"id":"a","label":"qalb"},{"id":"b","label":"qalab","why":"ل porte un sukūn : pas de voyelle après lui."},{"id":"c","label":"kalb","why":"ق (deux points, tête ronde) n’est pas ك : son plus profond."}],"answer":"a","explanation":"قَلْ (qal) + ب = « qalb ».","ar":"قَلْب","audio":"word:qalb","reviewKey":"word:qalb"},{"id":"m4l2-2","type":"choice","format":"fill","prompt":"Comment se lit ce mot ?","options":[{"id":"c","label":"ʿubd","why":"ع porte une fatḥa."},{"id":"b","label":"ʿabad","why":"ب porte un sukūn."},{"id":"a","label":"ʿabd"}],"answer":"a","explanation":"عَبْ (ʿab) + د = « ʿabd ».","ar":"عَبْد","audio":"word:abd","reviewKey":"word:abd"},{"id":"m4l2-3","type":"order","prompt":"Reconstituez le mot « shams » syllabe par syllabe (de droite à gauche)","ar":"شَمْس","audio":"word:shams","pieces":[{"id":"p0","ar":"شَمْ","label":"sham"},{"id":"p1","ar":"س","label":"s"}],"explanation":"شَمْس = شَمْ (sham) + س (s). On lit de droite à gauche."},{"id":"m4l2-4","type":"choice","format":"fill","prompt":"Comment se lit ce mot ?","options":[{"id":"a","label":"hal"},{"id":"c","label":"hala","why":"ل porte un sukūn."},{"id":"b","label":"ḥal","why":"ه (léger) n’est pas ح (serré)."}],"answer":"a","explanation":"هَ (ha) + لْ (l) = « hal ».","ar":"هَلْ","audio":"word:hal","reviewKey":"word:hal"}],"summary":["Le sukūn ferme la syllabe.","قَلْب = qalb."]}'::jsonb) on conflict (lesson_id) do update set content = excluded.content, version = public.lesson_contents.version + 1, updated_at = now();
insert into public.lessons (id, module_id, position, title_fr, objective_fr, difficulty, est_minutes, kind, published) values ('m4l3', 4, 3, 'Lire des mots avec voyelles longues', 'Distinguer voyelles brèves et longues dans un mot', 2, 7, 'lesson', true) on conflict (id) do update set title_fr = excluded.title_fr, objective_fr = excluded.objective_fr, difficulty = excluded.difficulty, est_minutes = excluded.est_minutes, kind = excluded.kind, position = excluded.position;
insert into public.lesson_contents (lesson_id, content) values ('m4l3', '{"steps":[{"kind":"example","ar":"كِتَاب","translit":"kitāb","fr":"livre","audio":"word:kitab"},{"kind":"example","ar":"كَبِير","translit":"kabīr","fr":"grand","audio":"word:kabir"},{"kind":"example","ar":"سَمِيع","translit":"samīʿ","fr":"qui entend","audio":"word:sami"},{"kind":"example","ar":"رَسُول","translit":"rasūl","fr":"messager","audio":"word:rasul"}],"exercises":[{"id":"m4l3-1","type":"choice","format":"fill","prompt":"Comment se lit ce mot ?","options":[{"id":"a","label":"kitāb"},{"id":"b","label":"kitab","why":"L’alif après تَ allonge le son : « tā »."},{"id":"c","label":"katib","why":"ك porte une kasra : « ki »."}],"answer":"a","explanation":"كِ (ki) + تَا (tā) + ب.","ar":"كِتَاب","audio":"word:kitab","reviewKey":"word:kitab"},{"id":"m4l3-2","type":"choice","format":"fill","prompt":"Comment se lit ce mot ?","options":[{"id":"c","label":"rusūl","why":"ر porte une fatḥa."},{"id":"a","label":"rasūl"},{"id":"b","label":"rasul","why":"Le و après سُ allonge le son."}],"answer":"a","explanation":"رَ (ra) + سُو (sū) + ل.","ar":"رَسُول","audio":"word:rasul","reviewKey":"word:rasul"},{"id":"m4l3-3","type":"choice","format":"fill","prompt":"Comment se lit ce mot ?","options":[{"id":"a","label":"kabīr"},{"id":"c","label":"kubīr","why":"ك porte une fatḥa."},{"id":"b","label":"kabir","why":"Le ي après بِ allonge le son."}],"answer":"a","explanation":"كَ (ka) + بِي (bī) + ر.","ar":"كَبِير","audio":"word:kabir","reviewKey":"word:kabir"},{"id":"m4l3-4","type":"order","prompt":"Reconstituez le mot « samīʿ » syllabe par syllabe (de droite à gauche)","ar":"سَمِيع","audio":"word:sam","pieces":[{"id":"p0","ar":"سَ","label":"sa"},{"id":"p1","ar":"مِي","label":"mī"},{"id":"p2","ar":"ع","label":"ʿ"}],"explanation":"سَمِيع = سَ (sa) + مِي (mī) + ع (ʿ). On lit de droite à gauche."}],"summary":["Repérez ا و ي après une voyelle brève : la voyelle est longue."]}'::jsonb) on conflict (lesson_id) do update set content = excluded.content, version = public.lesson_contents.version + 1, updated_at = now();
insert into public.lessons (id, module_id, position, title_fr, objective_fr, difficulty, est_minutes, kind, published) values ('m4l4', 4, 4, 'Lire avec shadda et tanwīn', 'Combiner tous les signes dans un même mot', 3, 8, 'lesson', true) on conflict (id) do update set title_fr = excluded.title_fr, objective_fr = excluded.objective_fr, difficulty = excluded.difficulty, est_minutes = excluded.est_minutes, kind = excluded.kind, position = excluded.position;
insert into public.lesson_contents (lesson_id, content) values ('m4l4', '{"steps":[{"kind":"example","ar":"رَبٌّ","translit":"rabbun","fr":"un seigneur","audio":"word:rabbun"},{"kind":"example","ar":"عِلْمٌ","translit":"ʿilmun","fr":"un savoir","audio":"word:ilmun"},{"kind":"example","ar":"جَنَّةٌ","translit":"jannatun","fr":"un jardin","audio":"word:jannatun"}],"exercises":[{"id":"m4l4-1","type":"choice","format":"fill","prompt":"Comment se lit ce mot ?","options":[{"id":"a","label":"rabbun"},{"id":"c","label":"rabbin","why":"Le tanwīn est une double ḍamma : « un »."},{"id":"b","label":"rabun","why":"La shadda double le ب."}],"answer":"a","explanation":"رَ (ra) + بٌّ (b-bun).","ar":"رَبٌّ","audio":"word:rabbun","reviewKey":"word:rabbun"},{"id":"m4l4-2","type":"choice","format":"fill","prompt":"Comment se lit ce mot ?","options":[{"id":"b","label":"ʿalmun","why":"ع porte une kasra : « ʿi »."},{"id":"c","label":"ʿilm","why":"Le tanwīn ajoute « un »."},{"id":"a","label":"ʿilmun"}],"answer":"a","explanation":"عِلْ (ʿil) + مٌ (mun).","ar":"عِلْمٌ","audio":"word:ilmun","reviewKey":"word:ilmun"},{"id":"m4l4-3","type":"choice","format":"fill","prompt":"Comment se lit ce mot ?","options":[{"id":"c","label":"jannahun","why":"ة suivie d’une voyelle se prononce « t »."},{"id":"b","label":"janatun","why":"La shadda double le ن."},{"id":"a","label":"jannatun"}],"answer":"a","explanation":"جَنْ (jan) + نَ (na) + ةٌ (tun).","ar":"جَنَّةٌ","audio":"word:jannatun","reviewKey":"word:jannatun"}],"summary":["Shadda + tanwīn peuvent se combiner : رَبٌّ = rabbun."]}'::jsonb) on conflict (lesson_id) do update set content = excluded.content, version = public.lesson_contents.version + 1, updated_at = now();
