insert into public.lesson_contents (lesson_id, content) values ('m4l5', '{"steps":[{"kind":"example","ar":"الْكِتَاب","translit":"al-kitāb","fr":"le livre","audio":"word:alkitab"},{"kind":"example","ar":"النُّور","translit":"an-nūr","fr":"la lumière","audio":"word:annur"},{"kind":"example","ar":"الرَّحْمَة","translit":"ar-raḥma","fr":"la miséricorde","audio":"word:arrahma"},{"kind":"example","ar":"الْقَلْب","translit":"al-qalb","fr":"le cœur","audio":"word:alqalb"}],"exercises":[{"id":"m4l5-1","type":"choice","format":"fill","prompt":"Comment se lit ce mot ?","options":[{"id":"b","label":"al-nūr","why":"ن est solaire : ل ne se prononce pas."},{"id":"a","label":"an-nūr"},{"id":"c","label":"an-nur","why":"Le و allonge le son : « nū »."}],"answer":"a","explanation":"ن solaire : « an-nūr ».","ar":"النُّور","audio":"word:annur","reviewKey":"word:annur"},{"id":"m4l5-2","type":"choice","format":"fill","prompt":"Comment se lit ce mot ?","options":[{"id":"a","label":"al-kitāb"},{"id":"c","label":"al-kitab","why":"L’alif allonge « tā »."},{"id":"b","label":"ak-kitāb","why":"ك est lunaire : ل se prononce."}],"answer":"a","explanation":"ك lunaire : « al-kitāb ».","ar":"الْكِتَاب","audio":"word:alkitab","reviewKey":"word:alkitab"},{"id":"m4l5-3","type":"choice","format":"fill","prompt":"Comment se lit ce mot ?","options":[{"id":"a","label":"ar-raḥma"},{"id":"c","label":"ar-rahma","why":"ح (serré) n’est pas ه (léger)."},{"id":"b","label":"al-raḥma","why":"ر est solaire."}],"answer":"a","explanation":"ر solaire : « ar-raḥma ».","ar":"الرَّحْمَة","audio":"word:arrahma","reviewKey":"word:arrahma"}],"summary":["Solaire : الشّ… (ash-), lunaire : الْق… (al-)."]}'::jsonb) on conflict (lesson_id) do update set content = excluded.content, version = public.lesson_contents.version + 1, updated_at = now();
insert into public.lessons (id, module_id, position, title_fr, objective_fr, difficulty, est_minutes, kind, published) values ('m4-test', 4, 99, 'Test du module 4 : la lecture', 'Valider les acquis du module : 80 % de bonnes réponses sont nécessaires.', 2, 6, 'module_test', true) on conflict (id) do update set title_fr = excluded.title_fr, objective_fr = excluded.objective_fr, difficulty = excluded.difficulty, est_minutes = excluded.est_minutes, kind = excluded.kind, position = excluded.position;
insert into public.lesson_contents (lesson_id, content) values ('m4-test', '{"steps":[{"kind":"explain","text":"Ce test reprend les notions des leçons du module. Prenez votre temps : il n’y a pas de limite de durée et vous pourrez le repasser."}],"exercises":[{"id":"module_test-m4-m4l1-1","type":"order","prompt":"Reconstituez le mot « kataba » syllabe par syllabe (de droite à gauche)","ar":"كَتَبَ","audio":"word:kataba","pieces":[{"id":"p0","ar":"كَ","label":"ka"},{"id":"p1","ar":"تَ","label":"ta"},{"id":"p2","ar":"بَ","label":"ba"}],"explanation":"كَتَبَ = كَ (ka) + تَ (ta) + بَ (ba). On lit de droite à gauche."},{"id":"module_test-m4-m4l1-3","type":"choice","format":"fill","prompt":"Comment se lit ce mot ?","options":[{"id":"b","label":"dahaba","why":"ذ (point au-dessus) se prononce « dh », comme l’anglais « this »."},{"id":"a","label":"dhahaba"},{"id":"c","label":"dhahiba","why":"ه porte une fatḥa : « ha »."}],"answer":"a","explanation":"ذَ (dha) + هَ (ha) + بَ (ba).","ar":"ذَهَبَ","audio":"word:dhahaba","reviewKey":"word:dhahaba"},{"id":"module_test-m4-m4l2-2","type":"choice","format":"fill","prompt":"Comment se lit ce mot ?","options":[{"id":"c","label":"ʿubd","why":"ع porte une fatḥa."},{"id":"b","label":"ʿabad","why":"ب porte un sukūn."},{"id":"a","label":"ʿabd"}],"answer":"a","explanation":"عَبْ (ʿab) + د = « ʿabd ».","ar":"عَبْد","audio":"word:abd","reviewKey":"word:abd"},{"id":"module_test-m4-m4l2-3","type":"order","prompt":"Reconstituez le mot « shams » syllabe par syllabe (de droite à gauche)","ar":"شَمْس","audio":"word:shams","pieces":[{"id":"p0","ar":"شَمْ","label":"sham"},{"id":"p1","ar":"س","label":"s"}],"explanation":"شَمْس = شَمْ (sham) + س (s). On lit de droite à gauche."},{"id":"module_test-m4-m4l3-1","type":"choice","format":"fill","prompt":"Comment se lit ce mot ?","options":[{"id":"a","label":"kitāb"},{"id":"b","label":"kitab","why":"L’alif après تَ allonge le son : « tā »."},{"id":"c","label":"katib","why":"ك porte une kasra : « ki »."}],"answer":"a","explanation":"كِ (ki) + تَا (tā) + ب.","ar":"كِتَاب","audio":"word:kitab","reviewKey":"word:kitab"},{"id":"module_test-m4-m4l3-4","type":"order","prompt":"Reconstituez le mot « samīʿ » syllabe par syllabe (de droite à gauche)","ar":"سَمِيع","audio":"word:sam","pieces":[{"id":"p0","ar":"سَ","label":"sa"},{"id":"p1","ar":"مِي","label":"mī"},{"id":"p2","ar":"ع","label":"ʿ"}],"explanation":"سَمِيع = سَ (sa) + مِي (mī) + ع (ʿ). On lit de droite à gauche."},{"id":"module_test-m4-m4l4-1","type":"choice","format":"fill","prompt":"Comment se lit ce mot ?","options":[{"id":"a","label":"rabbun"},{"id":"c","label":"rabbin","why":"Le tanwīn est une double ḍamma : « un »."},{"id":"b","label":"rabun","why":"La shadda double le ب."}],"answer":"a","explanation":"رَ (ra) + بٌّ (b-bun).","ar":"رَبٌّ","audio":"word:rabbun","reviewKey":"word:rabbun"},{"id":"module_test-m4-m4l4-2","type":"choice","format":"fill","prompt":"Comment se lit ce mot ?","options":[{"id":"b","label":"ʿalmun","why":"ع porte une kasra : « ʿi »."},{"id":"c","label":"ʿilm","why":"Le tanwīn ajoute « un »."},{"id":"a","label":"ʿilmun"}],"answer":"a","explanation":"عِلْ (ʿil) + مٌ (mun).","ar":"عِلْمٌ","audio":"word:ilmun","reviewKey":"word:ilmun"},{"id":"module_test-m4-m4l5-3","type":"choice","format":"fill","prompt":"Comment se lit ce mot ?","options":[{"id":"a","label":"ar-raḥma"},{"id":"c","label":"ar-rahma","why":"ح (serré) n’est pas ه (léger)."},{"id":"b","label":"al-raḥma","why":"ر est solaire."}],"answer":"a","explanation":"ر solaire : « ar-raḥma ».","ar":"الرَّحْمَة","audio":"word:arrahma","reviewKey":"word:arrahma"},{"id":"module_test-m4-m4l5-2","type":"choice","format":"fill","prompt":"Comment se lit ce mot ?","options":[{"id":"a","label":"al-kitāb"},{"id":"c","label":"al-kitab","why":"L’alif allonge « tā »."},{"id":"b","label":"ak-kitāb","why":"ك est lunaire : ل se prononce."}],"answer":"a","explanation":"ك lunaire : « al-kitāb ».","ar":"الْكِتَاب","audio":"word:alkitab","reviewKey":"word:alkitab"}],"summary":["Résultat enregistré dans votre progression.","Les notions manquées sont ajoutées à vos révisions."]}'::jsonb) on conflict (lesson_id) do update set content = excluded.content, version = public.lesson_contents.version + 1, updated_at = now();
