insert into public.lessons (id, module_id, position, title_fr, objective_fr, difficulty, est_minutes, kind, published) values ('m5l1', 5, 1, 'Dieu et ses noms', 'Comprendre 6 mots fréquents du Coran et leur racine', 1, 8, 'lesson', true) on conflict (id) do update set title_fr = excluded.title_fr, objective_fr = excluded.objective_fr, difficulty = excluded.difficulty, est_minutes = excluded.est_minutes, kind = excluded.kind, position = excluded.position;
insert into public.lesson_contents (lesson_id, content) values ('m5l1', '{"steps":[{"kind":"explain","text":"Commençons par des mots présents dès la sourate al-Fātiḥa. Une traduction n’est qu’une approche du sens : plusieurs traductions françaises existent pour chacun de ces mots."},{"kind":"example","ar":"اللَّه","translit":"Allāh","fr":"Dieu","audio":"word:allah","note":"Nom propre de Dieu. Son origine étymologique est discutée par les grammairiens ; nous ne lui attribuons pas de racine ici."},{"kind":"quran","ref":{"surah":1,"ayah":1,"wordFrom":2,"wordTo":2},"fr":"Occurrence de « Allāh » dans le Coran."},{"kind":"example","ar":"رَبّ","translit":"rabb","fr":"Seigneur, Maître","audio":"word:rabb","note":"Racine : ر ب ب"},{"kind":"quran","ref":{"surah":1,"ayah":2,"wordFrom":3,"wordTo":3},"fr":"Occurrence de « rabb » dans le Coran."},{"kind":"example","ar":"رَحْمَٰن","translit":"raḥmān","fr":"le Tout-Miséricordieux (traduction courante)","audio":"word:rahman","note":"Racine : ر ح م"},{"kind":"quran","ref":{"surah":1,"ayah":3,"wordFrom":1,"wordTo":1},"fr":"Occurrence de « raḥmān » dans le Coran."},{"kind":"example","ar":"رَحِيم","translit":"raḥīm","fr":"le Très-Miséricordieux (traduction courante)","audio":"word:rahim","note":"Racine : ر ح م"},{"kind":"quran","ref":{"surah":1,"ayah":3,"wordFrom":2,"wordTo":2},"fr":"Occurrence de « raḥīm » dans le Coran."},{"kind":"example","ar":"حَمْد","translit":"ḥamd","fr":"louange","audio":"word:hamd","note":"Racine : ح م د"},{"kind":"quran","ref":{"surah":1,"ayah":2,"wordFrom":1,"wordTo":1},"fr":"Occurrence de « ḥamd » dans le Coran."},{"kind":"example","ar":"عَلِيم","translit":"ʿalīm","fr":"Omniscient, qui sait tout","audio":"word:alim","note":"Racine : ع ل م"},{"kind":"tip","text":"Ajoutez ces mots à vos révisions : ils reviendront automatiquement au bon moment."}],"exercises":[{"id":"m5l1-tr-allah","type":"choice","format":"translate","prompt":"Que signifie ce mot ?","options":[{"id":"a","label":"Dieu"},{"id":"b","label":"livre, écrit","why":"« livre, écrit » se dit كِتَاب (kitāb)."},{"id":"d","label":"vérité, droit","why":"« vérité, droit » se dit حَقّ (ḥaqq)."},{"id":"c","label":"âme, soi, personne","why":"« âme, soi, personne » se dit نَفْس (nafs)."}],"answer":"a","explanation":"اللَّه (Allāh) signifie « Dieu ».","ar":"اللَّه","audio":"word:allah","reviewKey":"word:allah"},{"id":"m5l1-tr-rabb","type":"choice","format":"translate","prompt":"Que signifie ce mot ?","options":[{"id":"c","label":"châtiment","why":"« châtiment » se dit عَذَاب (ʿadhāb)."},{"id":"b","label":"il a cru, il a eu foi","why":"« il a cru, il a eu foi » se dit آمَنَ (āmana)."},{"id":"a","label":"Seigneur, Maître"},{"id":"d","label":"messager","why":"« messager » se dit رَسُول (rasūl)."}],"answer":"a","explanation":"رَبّ (rabb) signifie « Seigneur, Maître » ; racine ر ب ب.","ar":"رَبّ","audio":"word:rabb","reviewKey":"word:rabb"},{"id":"m5l1-tr-rahman","type":"choice","format":"translate","prompt":"Que signifie ce mot ?","options":[{"id":"a","label":"le Tout-Miséricordieux (traduction courante)"},{"id":"b","label":"eau","why":"« eau » se dit مَاء (māʾ)."},{"id":"c","label":"il a fait, il a placé, il a rendu","why":"« il a fait, il a placé, il a rendu » se dit جَعَلَ (jaʿala)."},{"id":"d","label":"il a écrit ; il a prescrit","why":"« il a écrit ; il a prescrit » se dit كَتَبَ (kataba)."}],"answer":"a","explanation":"رَحْمَٰن (raḥmān) signifie « le Tout-Miséricordieux (traduction courante) » ; racine ر ح م.","ar":"رَحْمَٰن","audio":"word:rahman","reviewKey":"word:rahman"},{"id":"m5l1-tr-rahim","type":"choice","format":"translate","prompt":"Que signifie ce mot ?","options":[{"id":"a","label":"le Très-Miséricordieux (traduction courante)"},{"id":"b","label":"il a mécru, il a renié","why":"« il a mécru, il a renié » se dit كَفَرَ (kafara)."},{"id":"d","label":"terre","why":"« terre » se dit أَرْض (arḍ)."},{"id":"c","label":"il a été patient, il a enduré","why":"« il a été patient, il a enduré » se dit صَبَرَ (ṣabara)."}],"answer":"a","explanation":"رَحِيم (raḥīm) signifie « le Très-Miséricordieux (traduction courante) » ; racine ر ح م.","ar":"رَحِيم","audio":"word:rahim","reviewKey":"word:rahim"},{"id":"m5l1-tr-hamd","type":"choice","format":"translate","prompt":"Que signifie ce mot ?","options":[{"id":"d","label":"il a adoré","why":"« il a adoré » se dit عَبَدَ (ʿabada)."},{"id":"a","label":"louange"},{"id":"c","label":"peuple, gens","why":"« peuple, gens » se dit قَوْم (qawm)."},{"id":"b","label":"scribe, celui qui écrit","why":"« scribe, celui qui écrit » se dit كَاتِب (kātib)."}],"answer":"a","explanation":"حَمْد (ḥamd) signifie « louange » ; racine ح م د.","ar":"حَمْد","audio":"word:hamd","reviewKey":"word:hamd"},{"id":"m5l1-tr-alim","type":"choice","format":"translate","prompt":"Que signifie ce mot ?","options":[{"id":"b","label":"il a fait, il a œuvré","why":"« il a fait, il a œuvré » se dit عَمِلَ (ʿamila)."},{"id":"a","label":"Omniscient, qui sait tout"},{"id":"d","label":"chemin, voie","why":"« chemin, voie » se dit سَبِيل (sabīl)."},{"id":"c","label":"savoir, science","why":"« savoir, science » se dit عِلْم (ʿilm)."}],"answer":"a","explanation":"عَلِيم (ʿalīm) signifie « Omniscient, qui sait tout » ; racine ع ل م.","ar":"عَلِيم","audio":"word:alim","reviewKey":"word:alim"},{"id":"m5l1-root-rabb","type":"choice","format":"mcq","prompt":"Quelle est la racine de ce mot ?","options":[{"id":"b","ar":"ح ق ق","why":"ح ق ق est la racine d’autres mots (حَقّ)."},{"id":"a","ar":"ر ب ب"},{"id":"c","ar":"ص ب ر","why":"ص ب ر est la racine d’autres mots (صَبَرَ)."}],"answer":"a","explanation":"La racine de رَبّ est ر ب ب : ce sont les consonnes qui restent quand on retire les voyelles et les lettres ajoutées.","ar":"رَبّ","reviewKey":"root:ر ب ب"},{"id":"m5l1-root-rahman","type":"choice","format":"mcq","prompt":"Quelle est la racine de ce mot ?","options":[{"id":"b","ar":"ق و م","why":"ق و م est la racine d’autres mots (قَوْم)."},{"id":"c","ar":"ق ل ب","why":"ق ل ب est la racine d’autres mots (قَلْب)."},{"id":"a","ar":"ر ح م"}],"answer":"a","explanation":"La racine de رَحْمَٰن est ر ح م : ce sont les consonnes qui restent quand on retire les voyelles et les lettres ajoutées.","ar":"رَحْمَٰن","reviewKey":"root:ر ح م"},{"id":"m5l1-match","type":"match","prompt":"Associez chaque mot à son sens","pairs":[{"left":{"id":"l-allah","ar":"اللَّه"},"right":{"id":"r-allah","label":"Dieu"}},{"left":{"id":"l-rabb","ar":"رَبّ"},"right":{"id":"r-rabb","label":"Seigneur, Maître"}},{"left":{"id":"l-rahman","ar":"رَحْمَٰن"},"right":{"id":"r-rahman","label":"le Tout-Miséricordieux (traduction courante)"}},{"left":{"id":"l-rahim","ar":"رَحِيم"},"right":{"id":"r-rahim","label":"le Très-Miséricordieux (traduction courante)"}}],"explanation":"اللَّه = Dieu · رَبّ = Seigneur, Maître · رَحْمَٰن = le Tout-Miséricordieux (traduction courante) · رَحِيم = le Très-Miséricordieux (traduction courante)"}],"summary":["اللَّه (Allāh) : Dieu","رَبّ (rabb) : Seigneur, Maître","رَحْمَٰن (raḥmān) : le Tout-Miséricordieux (traduction courante)","رَحِيم (raḥīm) : le Très-Miséricordieux (traduction courante)","حَمْد (ḥamd) : louange","عَلِيم (ʿalīm) : Omniscient, qui sait tout"]}'::jsonb) on conflict (lesson_id) do update set content = excluded.content, version = public.lesson_contents.version + 1, updated_at = now();
insert into public.lessons (id, module_id, position, title_fr, objective_fr, difficulty, est_minutes, kind, published) values ('m5l2', 5, 2, 'La foi et la guidée', 'Comprendre 8 mots fréquents du Coran et leur racine', 1, 8, 'lesson', true) on conflict (id) do update set title_fr = excluded.title_fr, objective_fr = excluded.objective_fr, difficulty = excluded.difficulty, est_minutes = excluded.est_minutes, kind = excluded.kind, position = excluded.position;
insert into public.lesson_contents (lesson_id, content) values ('m5l2', '{"steps":[{"kind":"explain","text":"Ces mots reviennent très souvent dans le Coran. Remarquez les racines : elles vous aideront à reconnaître des mots de la même famille."},{"kind":"example","ar":"كِتَاب","translit":"kitāb","fr":"livre, écrit","audio":"word:kitab","note":"Racine : ك ت ب"},{"kind":"quran","ref":{"surah":2,"ayah":2},"fr":"Occurrence de « kitāb » dans le Coran."},{"kind":"example","ar":"هُدًى","translit":"hudan","fr":"guidée, bonne direction","audio":"word:hudan","note":"Racine : ه د ي"},{"kind":"quran","ref":{"surah":2,"ayah":2},"fr":"Occurrence de « hudan » dans le Coran."},{"kind":"example","ar":"آمَنَ","translit":"āmana","fr":"il a cru, il a eu foi","audio":"word:amana","note":"Racine : ء م ن"},{"kind":"example","ar":"كَفَرَ","translit":"kafara","fr":"il a mécru, il a renié","audio":"word:kafara","note":"Racine : ك ف ر"},{"kind":"example","ar":"حَقّ","translit":"ḥaqq","fr":"vérité, droit","audio":"word:haqq","note":"Racine : ح ق ق"},{"kind":"example","ar":"دِين","translit":"dīn","fr":"religion ; rétribution (selon le contexte)","audio":"word:din","note":"Racine : د ي ن"},{"kind":"quran","ref":{"surah":1,"ayah":4,"wordFrom":3,"wordTo":3},"fr":"Occurrence de « dīn » dans le Coran."},{"kind":"example","ar":"رَسُول","translit":"rasūl","fr":"messager","audio":"word:rasul","note":"Racine : ر س ل"},{"kind":"example","ar":"آيَة","translit":"āya","fr":"signe ; verset","audio":"word:aya","note":"Racine : ء ي ي"},{"kind":"tip","text":"Ajoutez ces mots à vos révisions : ils reviendront automatiquement au bon moment."}],"exercises":[{"id":"m5l2-tr-kitab","type":"choice","format":"translate","prompt":"Que signifie ce mot ?","options":[{"id":"a","label":"livre, écrit"},{"id":"c","label":"cœur","why":"« cœur » se dit قَلْب (qalb)."},{"id":"b","label":"Seigneur, Maître","why":"« Seigneur, Maître » se dit رَبّ (rabb)."},{"id":"d","label":"ciel","why":"« ciel » se dit سَمَاء (samāʾ)."}],"answer":"a","explanation":"كِتَاب (kitāb) signifie « livre, écrit » ; racine ك ت ب.","ar":"كِتَاب","audio":"word:kitab","reviewKey":"word:kitab"},{"id":"m5l2-tr-hudan","type":"choice","format":"translate","prompt":"Que signifie ce mot ?","options":[{"id":"c","label":"il a adoré","why":"« il a adoré » se dit عَبَدَ (ʿabada)."},{"id":"a","label":"guidée, bonne direction"},{"id":"d","label":"scribe, celui qui écrit","why":"« scribe, celui qui écrit » se dit كَاتِب (kātib)."},{"id":"b","label":"il a écrit ; il a prescrit","why":"« il a écrit ; il a prescrit » se dit كَتَبَ (kataba)."}],"answer":"a","explanation":"هُدًى (hudan) signifie « guidée, bonne direction » ; racine ه د ي.","ar":"هُدًى","audio":"word:hudan","reviewKey":"word:hudan"},{"id":"m5l2-tr-amana","type":"choice","format":"translate","prompt":"Que signifie ce mot ?","options":[{"id":"c","label":"eau","why":"« eau » se dit مَاء (māʾ)."},{"id":"d","label":"il était, il fut","why":"« il était, il fut » se dit كَانَ (kāna)."},{"id":"a","label":"il a cru, il a eu foi"},{"id":"b","label":"louange","why":"« louange » se dit حَمْد (ḥamd)."}],"answer":"a","explanation":"آمَنَ (āmana) signifie « il a cru, il a eu foi » ; racine ء م ن.","ar":"آمَنَ","audio":"word:amana","reviewKey":"word:amana"},{"id":"m5l2-tr-kafara","type":"choice","format":"translate","prompt":"Que signifie ce mot ?","options":[{"id":"a","label":"il a mécru, il a renié"},{"id":"d","label":"il a adoré","why":"« il a adoré » se dit عَبَدَ (ʿabada)."},{"id":"c","label":"ordre, affaire","why":"« ordre, affaire » se dit أَمْر (amr)."},{"id":"b","label":"jardin ; paradis","why":"« jardin ; paradis » se dit جَنَّة (janna)."}],"answer":"a","explanation":"كَفَرَ (kafara) signifie « il a mécru, il a renié » ; racine ك ف ر.","ar":"كَفَرَ","audio":"word:kafara","reviewKey":"word:kafara"},{"id":"m5l2-tr-haqq","type":"choice","format":"translate","prompt":"Que signifie ce mot ?","options":[{"id":"c","label":"Seigneur, Maître","why":"« Seigneur, Maître » se dit رَبّ (rabb)."},{"id":"d","label":"châtiment","why":"« châtiment » se dit عَذَاب (ʿadhāb)."},{"id":"b","label":"il a su","why":"« il a su » se dit عَلِمَ (ʿalima)."},{"id":"a","label":"vérité, droit"}],"answer":"a","explanation":"حَقّ (ḥaqq) signifie « vérité, droit » ; racine ح ق ق.","ar":"حَقّ","audio":"word:haqq","reviewKey":"word:haqq"},{"id":"m5l2-tr-din","type":"choice","format":"translate","prompt":"Que signifie ce mot ?","options":[{"id":"c","label":"jour","why":"« jour » se dit يَوْم (yawm)."},{"id":"d","label":"il a adoré","why":"« il a adoré » se dit عَبَدَ (ʿabada)."},{"id":"b","label":"cœur","why":"« cœur » se dit قَلْب (qalb)."},{"id":"a","label":"religion ; rétribution (selon le contexte)"}],"answer":"a","explanation":"دِين (dīn) signifie « religion ; rétribution (selon le contexte) » ; racine د ي ن.","ar":"دِين","audio":"word:din","reviewKey":"word:din"},{"id":"m5l2-tr-rasul","type":"choice","format":"translate","prompt":"Que signifie ce mot ?","options":[{"id":"c","label":"vérité, droit","why":"« vérité, droit » se dit حَقّ (ḥaqq)."},{"id":"b","label":"eau","why":"« eau » se dit مَاء (māʾ)."},{"id":"a","label":"messager"},{"id":"d","label":"louange","why":"« louange » se dit حَمْد (ḥamd)."}],"answer":"a","explanation":"رَسُول (rasūl) signifie « messager » ; racine ر س ل.","ar":"رَسُول","audio":"word:rasul","reviewKey":"word:rasul"},{"id":"m5l2-tr-aya","type":"choice","format":"translate","prompt":"Que signifie ce mot ?","options":[{"id":"b","label":"feu","why":"« feu » se dit نَار (nār)."},{"id":"c","label":"cœur","why":"« cœur » se dit قَلْب (qalb)."},{"id":"a","label":"signe ; verset"},{"id":"d","label":"il a fait, il a œuvré","why":"« il a fait, il a œuvré » se dit عَمِلَ (ʿamila)."}],"answer":"a","explanation":"آيَة (āya) signifie « signe ; verset » ; racine ء ي ي.","ar":"آيَة","audio":"word:aya","reviewKey":"word:aya"},{"id":"m5l2-root-kitab","type":"choice","format":"mcq","prompt":"Quelle est la racine de ce mot ?","options":[{"id":"b","ar":"ر ح م","why":"ر ح م est la racine d’autres mots (رَحْمَٰن, رَحِيم)."},{"id":"a","ar":"ك ت ب"},{"id":"c","ar":"ء ي ي","why":"ء ي ي est la racine d’autres mots (آيَة)."}],"answer":"a","explanation":"La racine de كِتَاب est ك ت ب : ce sont les consonnes qui restent quand on retire les voyelles et les lettres ajoutées.","ar":"كِتَاب","reviewKey":"root:ك ت ب"},{"id":"m5l2-root-hudan","type":"choice","format":"mcq","prompt":"Quelle est la racine de ce mot ?","options":[{"id":"b","ar":"ع ذ ب","why":"ع ذ ب est la racine d’autres mots (عَذَاب)."},{"id":"a","ar":"ه د ي"},{"id":"c","ar":"د ي ن","why":"د ي ن est la racine d’autres mots (دِين)."}],"answer":"a","explanation":"La racine de هُدًى est ه د ي : ce sont les consonnes qui restent quand on retire les voyelles et les lettres ajoutées.","ar":"هُدًى","reviewKey":"root:ه د ي"},{"id":"m5l2-match","type":"match","prompt":"Associez chaque mot à son sens","pairs":[{"left":{"id":"l-kitab","ar":"كِتَاب"},"right":{"id":"r-kitab","label":"livre, écrit"}},{"left":{"id":"l-hudan","ar":"هُدًى"},"right":{"id":"r-hudan","label":"guidée, bonne direction"}},{"left":{"id":"l-amana","ar":"آمَنَ"},"right":{"id":"r-amana","label":"il a cru, il a eu foi"}},{"left":{"id":"l-kafara","ar":"كَفَرَ"},"right":{"id":"r-kafara","label":"il a mécru, il a renié"}}],"explanation":"كِتَاب = livre, écrit · هُدًى = guidée, bonne direction · آمَنَ = il a cru, il a eu foi · كَفَرَ = il a mécru, il a renié"}],"summary":["كِتَاب (kitāb) : livre, écrit","هُدًى (hudan) : guidée, bonne direction","آمَنَ (āmana) : il a cru, il a eu foi","كَفَرَ (kafara) : il a mécru, il a renié","حَقّ (ḥaqq) : vérité, droit","دِين (dīn) : religion ; rétribution (selon le contexte)","رَسُول (rasūl) : messager","آيَة (āya) : signe ; verset"]}'::jsonb) on conflict (lesson_id) do update set content = excluded.content, version = public.lesson_contents.version + 1, updated_at = now();
