insert into public.lesson_contents (lesson_id, content) values ('m5l3', '{"steps":[{"kind":"explain","text":"Des mots qui décrivent l’intérieur de l’être humain et ses actes."},{"kind":"example","ar":"نَفْس","translit":"nafs","fr":"âme, soi, personne","audio":"word:nafs","note":"Racine : ن ف س"},{"kind":"example","ar":"قَلْب","translit":"qalb","fr":"cœur","audio":"word:qalb","note":"Racine : ق ل ب"},{"kind":"example","ar":"قَوْم","translit":"qawm","fr":"peuple, gens","audio":"word:qawm","note":"Racine : ق و م"},{"kind":"example","ar":"عَمِلَ","translit":"ʿamila","fr":"il a fait, il a œuvré","audio":"word:amila","note":"Racine : ع م ل"},{"kind":"example","ar":"صَبَرَ","translit":"ṣabara","fr":"il a été patient, il a enduré","audio":"word:sabara","note":"Racine : ص ب ر"},{"kind":"example","ar":"ذِكْر","translit":"dhikr","fr":"rappel, évocation","audio":"word:dhikr","note":"Racine : ذ ك ر"},{"kind":"tip","text":"Ajoutez ces mots à vos révisions : ils reviendront automatiquement au bon moment."}],"exercises":[{"id":"m5l3-tr-nafs","type":"choice","format":"translate","prompt":"Que signifie ce mot ?","options":[{"id":"a","label":"âme, soi, personne"},{"id":"b","label":"il a fait, il a œuvré","why":"« il a fait, il a œuvré » se dit عَمِلَ (ʿamila)."},{"id":"c","label":"le Tout-Miséricordieux (traduction courante)","why":"« le Tout-Miséricordieux (traduction courante) » se dit رَحْمَٰن (raḥmān)."},{"id":"d","label":"châtiment","why":"« châtiment » se dit عَذَاب (ʿadhāb)."}],"answer":"a","explanation":"نَفْس (nafs) signifie « âme, soi, personne » ; racine ن ف س.","ar":"نَفْس","audio":"word:nafs","reviewKey":"word:nafs"},{"id":"m5l3-tr-qalb","type":"choice","format":"translate","prompt":"Que signifie ce mot ?","options":[{"id":"c","label":"il a mécru, il a renié","why":"« il a mécru, il a renié » se dit كَفَرَ (kafara)."},{"id":"d","label":"il a cru, il a eu foi","why":"« il a cru, il a eu foi » se dit آمَنَ (āmana)."},{"id":"a","label":"cœur"},{"id":"b","label":"guidée, bonne direction","why":"« guidée, bonne direction » se dit هُدًى (hudan)."}],"answer":"a","explanation":"قَلْب (qalb) signifie « cœur » ; racine ق ل ب.","ar":"قَلْب","audio":"word:qalb","reviewKey":"word:qalb"},{"id":"m5l3-tr-qawm","type":"choice","format":"translate","prompt":"Que signifie ce mot ?","options":[{"id":"c","label":"chemin, voie","why":"« chemin, voie » se dit سَبِيل (sabīl)."},{"id":"b","label":"il a mécru, il a renié","why":"« il a mécru, il a renié » se dit كَفَرَ (kafara)."},{"id":"d","label":"âme, soi, personne","why":"« âme, soi, personne » se dit نَفْس (nafs)."},{"id":"a","label":"peuple, gens"}],"answer":"a","explanation":"قَوْم (qawm) signifie « peuple, gens » ; racine ق و م.","ar":"قَوْم","audio":"word:qawm","reviewKey":"word:qawm"},{"id":"m5l3-tr-amila","type":"choice","format":"translate","prompt":"Que signifie ce mot ?","options":[{"id":"a","label":"il a fait, il a œuvré"},{"id":"c","label":"signe ; verset","why":"« signe ; verset » se dit آيَة (āya)."},{"id":"d","label":"Omniscient, qui sait tout","why":"« Omniscient, qui sait tout » se dit عَلِيم (ʿalīm)."},{"id":"b","label":"il a été patient, il a enduré","why":"« il a été patient, il a enduré » se dit صَبَرَ (ṣabara)."}],"answer":"a","explanation":"عَمِلَ (ʿamila) signifie « il a fait, il a œuvré » ; racine ع م ل.","ar":"عَمِلَ","audio":"word:amila","reviewKey":"word:amila"},{"id":"m5l3-tr-sabara","type":"choice","format":"translate","prompt":"Que signifie ce mot ?","options":[{"id":"c","label":"louange","why":"« louange » se dit حَمْد (ḥamd)."},{"id":"b","label":"il était, il fut","why":"« il était, il fut » se dit كَانَ (kāna)."},{"id":"a","label":"il a été patient, il a enduré"},{"id":"d","label":"prière","why":"« prière » se dit صَلَاة (ṣalāh)."}],"answer":"a","explanation":"صَبَرَ (ṣabara) signifie « il a été patient, il a enduré » ; racine ص ب ر.","ar":"صَبَرَ","audio":"word:sabara","reviewKey":"word:sabara"},{"id":"m5l3-tr-dhikr","type":"choice","format":"translate","prompt":"Que signifie ce mot ?","options":[{"id":"d","label":"il a adoré","why":"« il a adoré » se dit عَبَدَ (ʿabada)."},{"id":"c","label":"eau","why":"« eau » se dit مَاء (māʾ)."},{"id":"a","label":"rappel, évocation"},{"id":"b","label":"il a fait, il a placé, il a rendu","why":"« il a fait, il a placé, il a rendu » se dit جَعَلَ (jaʿala)."}],"answer":"a","explanation":"ذِكْر (dhikr) signifie « rappel, évocation » ; racine ذ ك ر.","ar":"ذِكْر","audio":"word:dhikr","reviewKey":"word:dhikr"},{"id":"m5l3-root-nafs","type":"choice","format":"mcq","prompt":"Quelle est la racine de ce mot ?","options":[{"id":"a","ar":"ن ف س"},{"id":"c","ar":"ق ل ب","why":"ق ل ب est la racine d’autres mots (قَلْب)."},{"id":"b","ar":"ن و ر","why":"ن و ر est la racine d’autres mots (نَار)."}],"answer":"a","explanation":"La racine de نَفْس est ن ف س : ce sont les consonnes qui restent quand on retire les voyelles et les lettres ajoutées.","ar":"نَفْس","reviewKey":"root:ن ف س"},{"id":"m5l3-root-qalb","type":"choice","format":"mcq","prompt":"Quelle est la racine de ce mot ?","options":[{"id":"c","ar":"ء م ر","why":"ء م ر est la racine d’autres mots (أَمْر)."},{"id":"a","ar":"ق ل ب"},{"id":"b","ar":"ء م ن","why":"ء م ن est la racine d’autres mots (آمَنَ)."}],"answer":"a","explanation":"La racine de قَلْب est ق ل ب : ce sont les consonnes qui restent quand on retire les voyelles et les lettres ajoutées.","ar":"قَلْب","reviewKey":"root:ق ل ب"},{"id":"m5l3-match","type":"match","prompt":"Associez chaque mot à son sens","pairs":[{"left":{"id":"l-nafs","ar":"نَفْس"},"right":{"id":"r-nafs","label":"âme, soi, personne"}},{"left":{"id":"l-qalb","ar":"قَلْب"},"right":{"id":"r-qalb","label":"cœur"}},{"left":{"id":"l-qawm","ar":"قَوْم"},"right":{"id":"r-qawm","label":"peuple, gens"}},{"left":{"id":"l-amila","ar":"عَمِلَ"},"right":{"id":"r-amila","label":"il a fait, il a œuvré"}}],"explanation":"نَفْس = âme, soi, personne · قَلْب = cœur · قَوْم = peuple, gens · عَمِلَ = il a fait, il a œuvré"}],"summary":["نَفْس (nafs) : âme, soi, personne","قَلْب (qalb) : cœur","قَوْم (qawm) : peuple, gens","عَمِلَ (ʿamila) : il a fait, il a œuvré","صَبَرَ (ṣabara) : il a été patient, il a enduré","ذِكْر (dhikr) : rappel, évocation"]}'::jsonb) on conflict (lesson_id) do update set content = excluded.content, version = public.lesson_contents.version + 1, updated_at = now();
