insert into public.lesson_contents (lesson_id, content) values ('m5l4', '{"steps":[{"kind":"explain","text":"Le vocabulaire de la création et du monde visible."},{"kind":"example","ar":"خَلَقَ","translit":"khalaqa","fr":"il a créé","audio":"word:khalaqa","note":"Racine : خ ل ق"},{"kind":"example","ar":"أَرْض","translit":"arḍ","fr":"terre","audio":"word:ard","note":"Racine : ء ر ض"},{"kind":"example","ar":"سَمَاء","translit":"samāʾ","fr":"ciel","audio":"word:sama","note":"Racine : س م و"},{"kind":"example","ar":"مَاء","translit":"māʾ","fr":"eau","audio":"word:ma","note":"Racine : م و ه"},{"kind":"example","ar":"يَوْم","translit":"yawm","fr":"jour","audio":"word:yawm","note":"Racine : ي و م"},{"kind":"quran","ref":{"surah":1,"ayah":4,"wordFrom":2,"wordTo":2},"fr":"Occurrence de « yawm » dans le Coran."},{"kind":"example","ar":"شَيْء","translit":"shayʾ","fr":"chose","audio":"word:shay","note":"Racine : ش ي ء"},{"kind":"example","ar":"جَعَلَ","translit":"jaʿala","fr":"il a fait, il a placé, il a rendu","audio":"word:jaala","note":"Racine : ج ع ل"},{"kind":"tip","text":"Ajoutez ces mots à vos révisions : ils reviendront automatiquement au bon moment."}],"exercises":[{"id":"m5l4-tr-khalaqa","type":"choice","format":"translate","prompt":"Que signifie ce mot ?","options":[{"id":"d","label":"jardin ; paradis","why":"« jardin ; paradis » se dit جَنَّة (janna)."},{"id":"a","label":"il a créé"},{"id":"b","label":"âme, soi, personne","why":"« âme, soi, personne » se dit نَفْس (nafs)."},{"id":"c","label":"feu","why":"« feu » se dit نَار (nār)."}],"answer":"a","explanation":"خَلَقَ (khalaqa) signifie « il a créé » ; racine خ ل ق.","ar":"خَلَقَ","audio":"word:khalaqa","reviewKey":"word:khalaqa"},{"id":"m5l4-tr-ard","type":"choice","format":"translate","prompt":"Que signifie ce mot ?","options":[{"id":"a","label":"terre"},{"id":"b","label":"louange","why":"« louange » se dit حَمْد (ḥamd)."},{"id":"c","label":"vérité, droit","why":"« vérité, droit » se dit حَقّ (ḥaqq)."},{"id":"d","label":"le Très-Miséricordieux (traduction courante)","why":"« le Très-Miséricordieux (traduction courante) » se dit رَحِيم (raḥīm)."}],"answer":"a","explanation":"أَرْض (arḍ) signifie « terre » ; racine ء ر ض.","ar":"أَرْض","audio":"word:ard","reviewKey":"word:ard"},{"id":"m5l4-tr-sama","type":"choice","format":"translate","prompt":"Que signifie ce mot ?","options":[{"id":"b","label":"il a écrit ; il a prescrit","why":"« il a écrit ; il a prescrit » se dit كَتَبَ (kataba)."},{"id":"a","label":"ciel"},{"id":"c","label":"il a mécru, il a renié","why":"« il a mécru, il a renié » se dit كَفَرَ (kafara)."},{"id":"d","label":"messager","why":"« messager » se dit رَسُول (rasūl)."}],"answer":"a","explanation":"سَمَاء (samāʾ) signifie « ciel » ; racine س م و.","ar":"سَمَاء","audio":"word:sama","reviewKey":"word:sama"},{"id":"m5l4-tr-ma","type":"choice","format":"translate","prompt":"Que signifie ce mot ?","options":[{"id":"b","label":"il a fait, il a œuvré","why":"« il a fait, il a œuvré » se dit عَمِلَ (ʿamila)."},{"id":"d","label":"ciel","why":"« ciel » se dit سَمَاء (samāʾ)."},{"id":"c","label":"Omniscient, qui sait tout","why":"« Omniscient, qui sait tout » se dit عَلِيم (ʿalīm)."},{"id":"a","label":"eau"}],"answer":"a","explanation":"مَاء (māʾ) signifie « eau » ; racine م و ه.","ar":"مَاء","audio":"word:ma","reviewKey":"word:ma"},{"id":"m5l4-tr-yawm","type":"choice","format":"translate","prompt":"Que signifie ce mot ?","options":[{"id":"a","label":"jour"},{"id":"c","label":"messager","why":"« messager » se dit رَسُول (rasūl)."},{"id":"d","label":"feu","why":"« feu » se dit نَار (nār)."},{"id":"b","label":"châtiment","why":"« châtiment » se dit عَذَاب (ʿadhāb)."}],"answer":"a","explanation":"يَوْم (yawm) signifie « jour » ; racine ي و م.","ar":"يَوْم","audio":"word:yawm","reviewKey":"word:yawm"},{"id":"m5l4-tr-shay","type":"choice","format":"translate","prompt":"Que signifie ce mot ?","options":[{"id":"a","label":"chose"},{"id":"b","label":"il a fait, il a placé, il a rendu","why":"« il a fait, il a placé, il a rendu » se dit جَعَلَ (jaʿala)."},{"id":"c","label":"il a su","why":"« il a su » se dit عَلِمَ (ʿalima)."},{"id":"d","label":"il a mécru, il a renié","why":"« il a mécru, il a renié » se dit كَفَرَ (kafara)."}],"answer":"a","explanation":"شَيْء (shayʾ) signifie « chose » ; racine ش ي ء.","ar":"شَيْء","audio":"word:shay","reviewKey":"word:shay"},{"id":"m5l4-tr-jaala","type":"choice","format":"translate","prompt":"Que signifie ce mot ?","options":[{"id":"d","label":"chose","why":"« chose » se dit شَيْء (shayʾ)."},{"id":"b","label":"terre","why":"« terre » se dit أَرْض (arḍ)."},{"id":"c","label":"louange","why":"« louange » se dit حَمْد (ḥamd)."},{"id":"a","label":"il a fait, il a placé, il a rendu"}],"answer":"a","explanation":"جَعَلَ (jaʿala) signifie « il a fait, il a placé, il a rendu » ; racine ج ع ل.","ar":"جَعَلَ","audio":"word:jaala","reviewKey":"word:jaala"},{"id":"m5l4-root-khalaqa","type":"choice","format":"mcq","prompt":"Quelle est la racine de ce mot ?","options":[{"id":"b","ar":"ع ل م","why":"ع ل م est la racine d’autres mots (عَلِيم, عِلْم, عَلِمَ)."},{"id":"a","ar":"خ ل ق"},{"id":"c","ar":"ه د ي","why":"ه د ي est la racine d’autres mots (هُدًى)."}],"answer":"a","explanation":"La racine de خَلَقَ est خ ل ق : ce sont les consonnes qui restent quand on retire les voyelles et les lettres ajoutées.","ar":"خَلَقَ","reviewKey":"root:خ ل ق"},{"id":"m5l4-root-ard","type":"choice","format":"mcq","prompt":"Quelle est la racine de ce mot ?","options":[{"id":"a","ar":"ء ر ض"},{"id":"c","ar":"ذ ك ر","why":"ذ ك ر est la racine d’autres mots (ذِكْر)."},{"id":"b","ar":"ن و ر","why":"ن و ر est la racine d’autres mots (نَار)."}],"answer":"a","explanation":"La racine de أَرْض est ء ر ض : ce sont les consonnes qui restent quand on retire les voyelles et les lettres ajoutées.","ar":"أَرْض","reviewKey":"root:ء ر ض"},{"id":"m5l4-match","type":"match","prompt":"Associez chaque mot à son sens","pairs":[{"left":{"id":"l-khalaqa","ar":"خَلَقَ"},"right":{"id":"r-khalaqa","label":"il a créé"}},{"left":{"id":"l-ard","ar":"أَرْض"},"right":{"id":"r-ard","label":"terre"}},{"left":{"id":"l-sama","ar":"سَمَاء"},"right":{"id":"r-sama","label":"ciel"}},{"left":{"id":"l-ma","ar":"مَاء"},"right":{"id":"r-ma","label":"eau"}}],"explanation":"خَلَقَ = il a créé · أَرْض = terre · سَمَاء = ciel · مَاء = eau"}],"summary":["خَلَقَ (khalaqa) : il a créé","أَرْض (arḍ) : terre","سَمَاء (samāʾ) : ciel","مَاء (māʾ) : eau","يَوْم (yawm) : jour","شَيْء (shayʾ) : chose","جَعَلَ (jaʿala) : il a fait, il a placé, il a rendu"]}'::jsonb) on conflict (lesson_id) do update set content = excluded.content, version = public.lesson_contents.version + 1, updated_at = now();
insert into public.lessons (id, module_id, position, title_fr, objective_fr, difficulty, est_minutes, kind, published) values ('m5l5', 5, 5, 'Le culte et l’au-delà', 'Comprendre 6 mots fréquents du Coran et leur racine', 2, 8, 'lesson', true) on conflict (id) do update set title_fr = excluded.title_fr, objective_fr = excluded.objective_fr, difficulty = excluded.difficulty, est_minutes = excluded.est_minutes, kind = excluded.kind, position = excluded.position;
insert into public.lesson_contents (lesson_id, content) values ('m5l5', '{"steps":[{"kind":"explain","text":"Des mots liés à l’adoration et à la vie future."},{"kind":"example","ar":"صَلَاة","translit":"ṣalāh","fr":"prière","audio":"word:salah","note":"Racine : ص ل و — Dans le texte coranique, ce mot est souvent écrit avec un wāw : c’est une particularité de la graphie ʿuthmānī."},{"kind":"quran","ref":{"surah":2,"ayah":3},"fr":"Occurrence de « ṣalāh » dans le Coran."},{"kind":"example","ar":"عَبَدَ","translit":"ʿabada","fr":"il a adoré","audio":"word:abada","note":"Racine : ع ب د — En 1:5, on trouve la forme نَعْبُدُ (« nous adorons »)."},{"kind":"quran","ref":{"surah":1,"ayah":5,"wordFrom":2,"wordTo":2},"fr":"Occurrence de « ʿabada » dans le Coran."},{"kind":"example","ar":"جَنَّة","translit":"janna","fr":"jardin ; paradis","audio":"word:janna","note":"Racine : ج ن ن"},{"kind":"example","ar":"نَار","translit":"nār","fr":"feu","audio":"word:nar","note":"Racine : ن و ر"},{"kind":"example","ar":"عَذَاب","translit":"ʿadhāb","fr":"châtiment","audio":"word:adhab","note":"Racine : ع ذ ب"},{"kind":"example","ar":"سَبِيل","translit":"sabīl","fr":"chemin, voie","audio":"word:sabil","note":"Racine : س ب ل"},{"kind":"tip","text":"Ajoutez ces mots à vos révisions : ils reviendront automatiquement au bon moment."}],"exercises":[{"id":"m5l5-tr-salah","type":"choice","format":"translate","prompt":"Que signifie ce mot ?","options":[{"id":"c","label":"il a fait, il a œuvré","why":"« il a fait, il a œuvré » se dit عَمِلَ (ʿamila)."},{"id":"b","label":"religion ; rétribution (selon le contexte)","why":"« religion ; rétribution (selon le contexte) » se dit دِين (dīn)."},{"id":"d","label":"jour","why":"« jour » se dit يَوْم (yawm)."},{"id":"a","label":"prière"}],"answer":"a","explanation":"صَلَاة (ṣalāh) signifie « prière » ; racine ص ل و.","ar":"صَلَاة","audio":"word:salah","reviewKey":"word:salah"},{"id":"m5l5-tr-abada","type":"choice","format":"translate","prompt":"Que signifie ce mot ?","options":[{"id":"b","label":"messager","why":"« messager » se dit رَسُول (rasūl)."},{"id":"a","label":"il a adoré"},{"id":"c","label":"Seigneur, Maître","why":"« Seigneur, Maître » se dit رَبّ (rabb)."},{"id":"d","label":"Dieu","why":"« Dieu » se dit اللَّه (Allāh)."}],"answer":"a","explanation":"عَبَدَ (ʿabada) signifie « il a adoré » ; racine ع ب د.","ar":"عَبَدَ","audio":"word:abada","reviewKey":"word:abada"},{"id":"m5l5-tr-janna","type":"choice","format":"translate","prompt":"Que signifie ce mot ?","options":[{"id":"b","label":"il a fait, il a œuvré","why":"« il a fait, il a œuvré » se dit عَمِلَ (ʿamila)."},{"id":"d","label":"il a été patient, il a enduré","why":"« il a été patient, il a enduré » se dit صَبَرَ (ṣabara)."},{"id":"c","label":"il a cru, il a eu foi","why":"« il a cru, il a eu foi » se dit آمَنَ (āmana)."},{"id":"a","label":"jardin ; paradis"}],"answer":"a","explanation":"جَنَّة (janna) signifie « jardin ; paradis » ; racine ج ن ن.","ar":"جَنَّة","audio":"word:janna","reviewKey":"word:janna"},{"id":"m5l5-tr-nar","type":"choice","format":"translate","prompt":"Que signifie ce mot ?","options":[{"id":"d","label":"le Tout-Miséricordieux (traduction courante)","why":"« le Tout-Miséricordieux (traduction courante) » se dit رَحْمَٰن (raḥmān)."},{"id":"a","label":"feu"},{"id":"c","label":"il était, il fut","why":"« il était, il fut » se dit كَانَ (kāna)."},{"id":"b","label":"rappel, évocation","why":"« rappel, évocation » se dit ذِكْر (dhikr)."}],"answer":"a","explanation":"نَار (nār) signifie « feu » ; racine ن و ر.","ar":"نَار","audio":"word:nar","reviewKey":"word:nar"},{"id":"m5l5-tr-adhab","type":"choice","format":"translate","prompt":"Que signifie ce mot ?","options":[{"id":"c","label":"cœur","why":"« cœur » se dit قَلْب (qalb)."},{"id":"b","label":"rappel, évocation","why":"« rappel, évocation » se dit ذِكْر (dhikr)."},{"id":"a","label":"châtiment"},{"id":"d","label":"Dieu","why":"« Dieu » se dit اللَّه (Allāh)."}],"answer":"a","explanation":"عَذَاب (ʿadhāb) signifie « châtiment » ; racine ع ذ ب.","ar":"عَذَاب","audio":"word:adhab","reviewKey":"word:adhab"},{"id":"m5l5-tr-sabil","type":"choice","format":"translate","prompt":"Que signifie ce mot ?","options":[{"id":"d","label":"louange","why":"« louange » se dit حَمْد (ḥamd)."},{"id":"a","label":"chemin, voie"},{"id":"b","label":"religion ; rétribution (selon le contexte)","why":"« religion ; rétribution (selon le contexte) » se dit دِين (dīn)."},{"id":"c","label":"chose","why":"« chose » se dit شَيْء (shayʾ)."}],"answer":"a","explanation":"سَبِيل (sabīl) signifie « chemin, voie » ; racine س ب ل.","ar":"سَبِيل","audio":"word:sabil","reviewKey":"word:sabil"},{"id":"m5l5-root-salah","type":"choice","format":"mcq","prompt":"Quelle est la racine de ce mot ?","options":[{"id":"a","ar":"ص ل و"},{"id":"b","ar":"ق و م","why":"ق و م est la racine d’autres mots (قَوْم)."},{"id":"c","ar":"م و ه","why":"م و ه est la racine d’autres mots (مَاء)."}],"answer":"a","explanation":"La racine de صَلَاة est ص ل و : ce sont les consonnes qui restent quand on retire les voyelles et les lettres ajoutées.","ar":"صَلَاة","reviewKey":"root:ص ل و"},{"id":"m5l5-root-abada","type":"choice","format":"mcq","prompt":"Quelle est la racine de ce mot ?","options":[{"id":"b","ar":"ع ذ ب","why":"ع ذ ب est la racine d’autres mots (عَذَاب)."},{"id":"a","ar":"ع ب د"},{"id":"c","ar":"ق و ل","why":"ق و ل est la racine d’autres mots (قَالَ)."}],"answer":"a","explanation":"La racine de عَبَدَ est ع ب د : ce sont les consonnes qui restent quand on retire les voyelles et les lettres ajoutées.","ar":"عَبَدَ","reviewKey":"root:ع ب د"},{"id":"m5l5-match","type":"match","prompt":"Associez chaque mot à son sens","pairs":[{"left":{"id":"l-salah","ar":"صَلَاة"},"right":{"id":"r-salah","label":"prière"}},{"left":{"id":"l-abada","ar":"عَبَدَ"},"right":{"id":"r-abada","label":"il a adoré"}},{"left":{"id":"l-janna","ar":"جَنَّة"},"right":{"id":"r-janna","label":"jardin ; paradis"}},{"left":{"id":"l-nar","ar":"نَار"},"right":{"id":"r-nar","label":"feu"}}],"explanation":"صَلَاة = prière · عَبَدَ = il a adoré · جَنَّة = jardin ; paradis · نَار = feu"}],"summary":["صَلَاة (ṣalāh) : prière","عَبَدَ (ʿabada) : il a adoré","جَنَّة (janna) : jardin ; paradis","نَار (nār) : feu","عَذَاب (ʿadhāb) : châtiment","سَبِيل (sabīl) : chemin, voie"]}'::jsonb) on conflict (lesson_id) do update set content = excluded.content, version = public.lesson_contents.version + 1, updated_at = now();
insert into public.lessons (id, module_id, position, title_fr, objective_fr, difficulty, est_minutes, kind, published) values ('m5l6', 5, 6, 'Les mots les plus fréquents et les racines', 'Comprendre 7 mots fréquents du Coran et leur racine', 2, 8, 'lesson', true) on conflict (id) do update set title_fr = excluded.title_fr, objective_fr = excluded.objective_fr, difficulty = excluded.difficulty, est_minutes = excluded.est_minutes, kind = excluded.kind, position = excluded.position;
insert into public.lesson_contents (lesson_id, content) values ('m5l6', '{"steps":[{"kind":"explain","text":"Une racine est un ensemble de (souvent) trois consonnes porteuses d’un sens général. En changeant les voyelles et en ajoutant des lettres autour, on obtient des mots de la même famille. Connaître une racine, c’est souvent deviner le sens de plusieurs mots."},{"kind":"example","ar":"قَالَ","translit":"qāla","fr":"il a dit","audio":"word:qala","note":"Racine : ق و ل — Un des verbes les plus fréquents du Coran."},{"kind":"example","ar":"كَانَ","translit":"kāna","fr":"il était, il fut","audio":"word:kana","note":"Racine : ك و ن"},{"kind":"example","ar":"أَمْر","translit":"amr","fr":"ordre, affaire","audio":"word:amr","note":"Racine : ء م ر"},{"kind":"example","ar":"كَتَبَ","translit":"kataba","fr":"il a écrit ; il a prescrit","audio":"word:kataba","note":"Racine : ك ت ب"},{"kind":"example","ar":"كَاتِب","translit":"kātib","fr":"scribe, celui qui écrit","audio":"word:katib","note":"Racine : ك ت ب"},{"kind":"example","ar":"عِلْم","translit":"ʿilm","fr":"savoir, science","audio":"word:ilm","note":"Racine : ع ل م"},{"kind":"example","ar":"عَلِمَ","translit":"ʿalima","fr":"il a su","audio":"word:alima","note":"Racine : ع ل م"},{"kind":"tip","text":"Ajoutez ces mots à vos révisions : ils reviendront automatiquement au bon moment."}],"exercises":[{"id":"m5l6-tr-qala","type":"choice","format":"translate","prompt":"Que signifie ce mot ?","options":[{"id":"c","label":"messager","why":"« messager » se dit رَسُول (rasūl)."},{"id":"a","label":"il a dit"},{"id":"d","label":"ordre, affaire","why":"« ordre, affaire » se dit أَمْر (amr)."},{"id":"b","label":"le Tout-Miséricordieux (traduction courante)","why":"« le Tout-Miséricordieux (traduction courante) » se dit رَحْمَٰن (raḥmān)."}],"answer":"a","explanation":"قَالَ (qāla) signifie « il a dit » ; racine ق و ل.","ar":"قَالَ","audio":"word:qala","reviewKey":"word:qala"},{"id":"m5l6-tr-kana","type":"choice","format":"translate","prompt":"Que signifie ce mot ?","options":[{"id":"d","label":"jardin ; paradis","why":"« jardin ; paradis » se dit جَنَّة (janna)."},{"id":"b","label":"feu","why":"« feu » se dit نَار (nār)."},{"id":"c","label":"il a fait, il a œuvré","why":"« il a fait, il a œuvré » se dit عَمِلَ (ʿamila)."},{"id":"a","label":"il était, il fut"}],"answer":"a","explanation":"كَانَ (kāna) signifie « il était, il fut » ; racine ك و ن.","ar":"كَانَ","audio":"word:kana","reviewKey":"word:kana"},{"id":"m5l6-tr-amr","type":"choice","format":"translate","prompt":"Que signifie ce mot ?","options":[{"id":"a","label":"ordre, affaire"},{"id":"d","label":"chose","why":"« chose » se dit شَيْء (shayʾ)."},{"id":"c","label":"rappel, évocation","why":"« rappel, évocation » se dit ذِكْر (dhikr)."},{"id":"b","label":"jardin ; paradis","why":"« jardin ; paradis » se dit جَنَّة (janna)."}],"answer":"a","explanation":"أَمْر (amr) signifie « ordre, affaire » ; racine ء م ر.","ar":"أَمْر","audio":"word:amr","reviewKey":"word:amr"},{"id":"m5l6-tr-kataba","type":"choice","format":"translate","prompt":"Que signifie ce mot ?","options":[{"id":"b","label":"il a fait, il a placé, il a rendu","why":"« il a fait, il a placé, il a rendu » se dit جَعَلَ (jaʿala)."},{"id":"d","label":"Omniscient, qui sait tout","why":"« Omniscient, qui sait tout » se dit عَلِيم (ʿalīm)."},{"id":"c","label":"guidée, bonne direction","why":"« guidée, bonne direction » se dit هُدًى (hudan)."},{"id":"a","label":"il a écrit ; il a prescrit"}],"answer":"a","explanation":"كَتَبَ (kataba) signifie « il a écrit ; il a prescrit » ; racine ك ت ب.","ar":"كَتَبَ","audio":"word:kataba","reviewKey":"word:kataba"},{"id":"m5l6-tr-katib","type":"choice","format":"translate","prompt":"Que signifie ce mot ?","options":[{"id":"b","label":"cœur","why":"« cœur » se dit قَلْب (qalb)."},{"id":"c","label":"prière","why":"« prière » se dit صَلَاة (ṣalāh)."},{"id":"d","label":"ordre, affaire","why":"« ordre, affaire » se dit أَمْر (amr)."},{"id":"a","label":"scribe, celui qui écrit"}],"answer":"a","explanation":"كَاتِب (kātib) signifie « scribe, celui qui écrit » ; racine ك ت ب.","ar":"كَاتِب","audio":"word:katib","reviewKey":"word:katib"},{"id":"m5l6-tr-ilm","type":"choice","format":"translate","prompt":"Que signifie ce mot ?","options":[{"id":"b","label":"jardin ; paradis","why":"« jardin ; paradis » se dit جَنَّة (janna)."},{"id":"d","label":"châtiment","why":"« châtiment » se dit عَذَاب (ʿadhāb)."},{"id":"c","label":"il a été patient, il a enduré","why":"« il a été patient, il a enduré » se dit صَبَرَ (ṣabara)."},{"id":"a","label":"savoir, science"}],"answer":"a","explanation":"عِلْم (ʿilm) signifie « savoir, science » ; racine ع ل م.","ar":"عِلْم","audio":"word:ilm","reviewKey":"word:ilm"},{"id":"m5l6-tr-alima","type":"choice","format":"translate","prompt":"Que signifie ce mot ?","options":[{"id":"d","label":"messager","why":"« messager » se dit رَسُول (rasūl)."},{"id":"a","label":"il a su"},{"id":"c","label":"savoir, science","why":"« savoir, science » se dit عِلْم (ʿilm)."},{"id":"b","label":"il a créé","why":"« il a créé » se dit خَلَقَ (khalaqa)."}],"answer":"a","explanation":"عَلِمَ (ʿalima) signifie « il a su » ; racine ع ل م.","ar":"عَلِمَ","audio":"word:alima","reviewKey":"word:alima"},{"id":"m5l6-root-qala","type":"choice","format":"mcq","prompt":"Quelle est la racine de ce mot ?","options":[{"id":"c","ar":"ح ق ق","why":"ح ق ق est la racine d’autres mots (حَقّ)."},{"id":"b","ar":"ص ب ر","why":"ص ب ر est la racine d’autres mots (صَبَرَ)."},{"id":"a","ar":"ق و ل"}],"answer":"a","explanation":"La racine de قَالَ est ق و ل : ce sont les consonnes qui restent quand on retire les voyelles et les lettres ajoutées.","ar":"قَالَ","reviewKey":"root:ق و ل"},{"id":"m5l6-root-kana","type":"choice","format":"mcq","prompt":"Quelle est la racine de ce mot ?","options":[{"id":"a","ar":"ك و ن"},{"id":"b","ar":"ن ف س","why":"ن ف س est la racine d’autres mots (نَفْس)."},{"id":"c","ar":"ح ق ق","why":"ح ق ق est la racine d’autres mots (حَقّ)."}],"answer":"a","explanation":"La racine de كَانَ est ك و ن : ce sont les consonnes qui restent quand on retire les voyelles et les lettres ajoutées.","ar":"كَانَ","reviewKey":"root:ك و ن"},{"id":"m5l6-match","type":"match","prompt":"Associez chaque mot à son sens","pairs":[{"left":{"id":"l-qala","ar":"قَالَ"},"right":{"id":"r-qala","label":"il a dit"}},{"left":{"id":"l-kana","ar":"كَانَ"},"right":{"id":"r-kana","label":"il était, il fut"}},{"left":{"id":"l-amr","ar":"أَمْر"},"right":{"id":"r-amr","label":"ordre, affaire"}},{"left":{"id":"l-kataba","ar":"كَتَبَ"},"right":{"id":"r-kataba","label":"il a écrit ; il a prescrit"}}],"explanation":"قَالَ = il a dit · كَانَ = il était, il fut · أَمْر = ordre, affaire · كَتَبَ = il a écrit ; il a prescrit"}],"summary":["قَالَ (qāla) : il a dit","كَانَ (kāna) : il était, il fut","أَمْر (amr) : ordre, affaire","كَتَبَ (kataba) : il a écrit ; il a prescrit","كَاتِب (kātib) : scribe, celui qui écrit","عِلْم (ʿilm) : savoir, science","عَلِمَ (ʿalima) : il a su"]}'::jsonb) on conflict (lesson_id) do update set content = excluded.content, version = public.lesson_contents.version + 1, updated_at = now();
insert into public.lessons (id, module_id, position, title_fr, objective_fr, difficulty, est_minutes, kind, published) values ('m5-test', 5, 99, 'Test du module 5 : le vocabulaire', 'Valider les acquis du module : 80 % de bonnes réponses sont nécessaires.', 2, 8, 'module_test', true) on conflict (id) do update set title_fr = excluded.title_fr, objective_fr = excluded.objective_fr, difficulty = excluded.difficulty, est_minutes = excluded.est_minutes, kind = excluded.kind, position = excluded.position;
insert into public.lesson_contents (lesson_id, content) values ('m5-test', '{"steps":[{"kind":"explain","text":"Ce test reprend les notions des leçons du module. Prenez votre temps : il n’y a pas de limite de durée et vous pourrez le repasser."}],"exercises":[{"id":"module_test-m5-m5l1-tr-rabb","type":"choice","format":"translate","prompt":"Que signifie ce mot ?","options":[{"id":"c","label":"châtiment","why":"« châtiment » se dit عَذَاب (ʿadhāb)."},{"id":"b","label":"il a cru, il a eu foi","why":"« il a cru, il a eu foi » se dit آمَنَ (āmana)."},{"id":"a","label":"Seigneur, Maître"},{"id":"d","label":"messager","why":"« messager » se dit رَسُول (rasūl)."}],"answer":"a","explanation":"رَبّ (rabb) signifie « Seigneur, Maître » ; racine ر ب ب.","ar":"رَبّ","audio":"word:rabb","reviewKey":"word:rabb"},{"id":"module_test-m5-m5l1-root-rahman","type":"choice","format":"mcq","prompt":"Quelle est la racine de ce mot ?","options":[{"id":"b","ar":"ق و م","why":"ق و م est la racine d’autres mots (قَوْم)."},{"id":"c","ar":"ق ل ب","why":"ق ل ب est la racine d’autres mots (قَلْب)."},{"id":"a","ar":"ر ح م"}],"answer":"a","explanation":"La racine de رَحْمَٰن est ر ح م : ce sont les consonnes qui restent quand on retire les voyelles et les lettres ajoutées.","ar":"رَحْمَٰن","reviewKey":"root:ر ح م"},{"id":"module_test-m5-m5l2-tr-amana","type":"choice","format":"translate","prompt":"Que signifie ce mot ?","options":[{"id":"c","label":"eau","why":"« eau » se dit مَاء (māʾ)."},{"id":"d","label":"il était, il fut","why":"« il était, il fut » se dit كَانَ (kāna)."},{"id":"a","label":"il a cru, il a eu foi"},{"id":"b","label":"louange","why":"« louange » se dit حَمْد (ḥamd)."}],"answer":"a","explanation":"آمَنَ (āmana) signifie « il a cru, il a eu foi » ; racine ء م ن.","ar":"آمَنَ","audio":"word:amana","reviewKey":"word:amana"},{"id":"module_test-m5-m5l2-tr-din","type":"choice","format":"translate","prompt":"Que signifie ce mot ?","options":[{"id":"c","label":"jour","why":"« jour » se dit يَوْم (yawm)."},{"id":"d","label":"il a adoré","why":"« il a adoré » se dit عَبَدَ (ʿabada)."},{"id":"b","label":"cœur","why":"« cœur » se dit قَلْب (qalb)."},{"id":"a","label":"religion ; rétribution (selon le contexte)"}],"answer":"a","explanation":"دِين (dīn) signifie « religion ; rétribution (selon le contexte) » ; racine د ي ن.","ar":"دِين","audio":"word:din","reviewKey":"word:din"},{"id":"module_test-m5-m5l3-root-qalb","type":"choice","format":"mcq","prompt":"Quelle est la racine de ce mot ?","options":[{"id":"c","ar":"ء م ر","why":"ء م ر est la racine d’autres mots (أَمْر)."},{"id":"a","ar":"ق ل ب"},{"id":"b","ar":"ء م ن","why":"ء م ن est la racine d’autres mots (آمَنَ)."}],"answer":"a","explanation":"La racine de قَلْب est ق ل ب : ce sont les consonnes qui restent quand on retire les voyelles et les lettres ajoutées.","ar":"قَلْب","reviewKey":"root:ق ل ب"},{"id":"module_test-m5-m5l3-tr-qalb","type":"choice","format":"translate","prompt":"Que signifie ce mot ?","options":[{"id":"c","label":"il a mécru, il a renié","why":"« il a mécru, il a renié » se dit كَفَرَ (kafara)."},{"id":"d","label":"il a cru, il a eu foi","why":"« il a cru, il a eu foi » se dit آمَنَ (āmana)."},{"id":"a","label":"cœur"},{"id":"b","label":"guidée, bonne direction","why":"« guidée, bonne direction » se dit هُدًى (hudan)."}],"answer":"a","explanation":"قَلْب (qalb) signifie « cœur » ; racine ق ل ب.","ar":"قَلْب","audio":"word:qalb","reviewKey":"word:qalb"},{"id":"module_test-m5-m5l4-tr-shay","type":"choice","format":"translate","prompt":"Que signifie ce mot ?","options":[{"id":"a","label":"chose"},{"id":"b","label":"il a fait, il a placé, il a rendu","why":"« il a fait, il a placé, il a rendu » se dit جَعَلَ (jaʿala)."},{"id":"c","label":"il a su","why":"« il a su » se dit عَلِمَ (ʿalima)."},{"id":"d","label":"il a mécru, il a renié","why":"« il a mécru, il a renié » se dit كَفَرَ (kafara)."}],"answer":"a","explanation":"شَيْء (shayʾ) signifie « chose » ; racine ش ي ء.","ar":"شَيْء","audio":"word:shay","reviewKey":"word:shay"},{"id":"module_test-m5-m5l4-tr-ard","type":"choice","format":"translate","prompt":"Que signifie ce mot ?","options":[{"id":"a","label":"terre"},{"id":"b","label":"louange","why":"« louange » se dit حَمْد (ḥamd)."},{"id":"c","label":"vérité, droit","why":"« vérité, droit » se dit حَقّ (ḥaqq)."},{"id":"d","label":"le Très-Miséricordieux (traduction courante)","why":"« le Très-Miséricordieux (traduction courante) » se dit رَحِيم (raḥīm)."}],"answer":"a","explanation":"أَرْض (arḍ) signifie « terre » ; racine ء ر ض.","ar":"أَرْض","audio":"word:ard","reviewKey":"word:ard"},{"id":"module_test-m5-m5l5-tr-salah","type":"choice","format":"translate","prompt":"Que signifie ce mot ?","options":[{"id":"c","label":"il a fait, il a œuvré","why":"« il a fait, il a œuvré » se dit عَمِلَ (ʿamila)."},{"id":"b","label":"religion ; rétribution (selon le contexte)","why":"« religion ; rétribution (selon le contexte) » se dit دِين (dīn)."},{"id":"d","label":"jour","why":"« jour » se dit يَوْم (yawm)."},{"id":"a","label":"prière"}],"answer":"a","explanation":"صَلَاة (ṣalāh) signifie « prière » ; racine ص ل و.","ar":"صَلَاة","audio":"word:salah","reviewKey":"word:salah"},{"id":"module_test-m5-m5l5-tr-adhab","type":"choice","format":"translate","prompt":"Que signifie ce mot ?","options":[{"id":"c","label":"cœur","why":"« cœur » se dit قَلْب (qalb)."},{"id":"b","label":"rappel, évocation","why":"« rappel, évocation » se dit ذِكْر (dhikr)."},{"id":"a","label":"châtiment"},{"id":"d","label":"Dieu","why":"« Dieu » se dit اللَّه (Allāh)."}],"answer":"a","explanation":"عَذَاب (ʿadhāb) signifie « châtiment » ; racine ع ذ ب.","ar":"عَذَاب","audio":"word:adhab","reviewKey":"word:adhab"},{"id":"module_test-m5-m5l6-match","type":"match","prompt":"Associez chaque mot à son sens","pairs":[{"left":{"id":"l-qala","ar":"قَالَ"},"right":{"id":"r-qala","label":"il a dit"}},{"left":{"id":"l-kana","ar":"كَانَ"},"right":{"id":"r-kana","label":"il était, il fut"}},{"left":{"id":"l-amr","ar":"أَمْر"},"right":{"id":"r-amr","label":"ordre, affaire"}},{"left":{"id":"l-kataba","ar":"كَتَبَ"},"right":{"id":"r-kataba","label":"il a écrit ; il a prescrit"}}],"explanation":"قَالَ = il a dit · كَانَ = il était, il fut · أَمْر = ordre, affaire · كَتَبَ = il a écrit ; il a prescrit"},{"id":"module_test-m5-m5l6-root-kana","type":"choice","format":"mcq","prompt":"Quelle est la racine de ce mot ?","options":[{"id":"a","ar":"ك و ن"},{"id":"b","ar":"ن ف س","why":"ن ف س est la racine d’autres mots (نَفْس)."},{"id":"c","ar":"ح ق ق","why":"ح ق ق est la racine d’autres mots (حَقّ)."}],"answer":"a","explanation":"La racine de كَانَ est ك و ن : ce sont les consonnes qui restent quand on retire les voyelles et les lettres ajoutées.","ar":"كَانَ","reviewKey":"root:ك و ن"}],"summary":["Résultat enregistré dans votre progression.","Les notions manquées sont ajoutées à vos révisions."]}'::jsonb) on conflict (lesson_id) do update set content = excluded.content, version = public.lesson_contents.version + 1, updated_at = now();
insert into public.lessons (id, module_id, position, title_fr, objective_fr, difficulty, est_minutes, kind, published) values ('exam-free', 5, 99, 'Examen général du parcours gratuit', 'Valider les acquis du module : 80 % de bonnes réponses sont nécessaires.', 2, 19, 'final_exam', true) on conflict (id) do update set title_fr = excluded.title_fr, objective_fr = excluded.objective_fr, difficulty = excluded.difficulty, est_minutes = excluded.est_minutes, kind = excluded.kind, position = excluded.position;
insert into public.lesson_contents (lesson_id, content) values ('exam-free', '{"steps":[{"kind":"explain","text":"Ce test reprend les notions des leçons du module. Prenez votre temps : il n’y a pas de limite de durée et vous pourrez le repasser."}],"exercises":[{"id":"final_exam-m5-m1l1-name-ba","type":"choice","format":"visual","prompt":"Quelle lettre s''appelle « bā’ » ?","options":[{"id":"tha","ar":"ث","why":"ث est thā’ : « th » de l’anglais « think » : langue entre les dents, sans voix. Repère visuel : trois points au-dessus."},{"id":"ta","ar":"ت","why":"ت est tā’ : « t » comme dans « table ». Repère visuel : deux points au-dessus."},{"id":"ba","ar":"ب"},{"id":"nun","ar":"ن","why":"ن est nūn : « n » comme dans « nez ». Repère visuel : un point au-dessus."}],"answer":"ba","explanation":"ب se nomme bā’ (بَاء) et se transcrit « b » : « b » comme dans « bateau ». Repère visuel : un point en dessous.","reviewKey":"letter:ba"},{"id":"final_exam-m5-m1l2-listen-kha","type":"choice","format":"listen","prompt":"Écoutez puis choisissez la lettre entendue","options":[{"id":"kha","ar":"خ"},{"id":"waw","ar":"و","why":"و est wāw : « w » comme dans « watt », ou voyelle longue « oû ». Repère visuel : aucun point."},{"id":"jim","ar":"ج","why":"ج est jīm : « dj » comme dans « djinn ». Repère visuel : un point en dessous."},{"id":"hha","ar":"ح","why":"ح est ḥā’ : « h » soufflé et serré au milieu de la gorge, comme pour embuer une vitre très fort. Repère visuel : aucun point."}],"answer":"kha","explanation":"خ se nomme khā’ (خَاء) et se transcrit « kh » : « r » raclé au fond du palais, comme la « jota » espagnole ou le « ch » allemand de « Bach ». Repère visuel : un point au-dessus.","audio":"letter:kha","textFallback":"Quelle lettre se prononce « r » raclé au fond du palais, comme la « jota » espagnole ou le « ch » allemand de « Bach » ?","reviewKey":"letter:kha"},{"id":"final_exam-m5-m1l3-name-dhal","type":"choice","format":"visual","prompt":"Quelle lettre s''appelle « dhāl » ?","options":[{"id":"sad","ar":"ص","why":"ص est ṣād : « s » emphatique : bouche arrondie, arrière de la langue relevé, son plus grave. Repère visuel : aucun point."},{"id":"ha","ar":"ه","why":"ه est hā’ : « h » léger et expiré, comme l’anglais « hello ». Repère visuel : aucun point."},{"id":"dhal","ar":"ذ"},{"id":"dal","ar":"د","why":"د est dāl : « d » comme dans « dos ». Repère visuel : aucun point."}],"answer":"dhal","explanation":"ذ se nomme dhāl (ذَال) et se transcrit « dh » : « th » de l’anglais « this » : langue entre les dents, avec la voix. Repère visuel : un point au-dessus.","reviewKey":"letter:dhal"},{"id":"final_exam-m5-m1l4-listen-sin","type":"choice","format":"listen","prompt":"Écoutez puis choisissez la lettre entendue","options":[{"id":"sin","ar":"س"},{"id":"zay","ar":"ز","why":"ز est zāy : « z » comme dans « zéro ». Repère visuel : un point au-dessus."},{"id":"ha","ar":"ه","why":"ه est hā’ : « h » léger et expiré, comme l’anglais « hello ». Repère visuel : aucun point."},{"id":"shin","ar":"ش","why":"ش est shīn : « ch » comme dans « chat ». Repère visuel : trois points au-dessus."}],"answer":"sin","explanation":"س se nomme sīn (سِين) et se transcrit « s » : « s » comme dans « sel ». Repère visuel : aucun point.","audio":"letter:sin","textFallback":"Quelle lettre se prononce « s » comme dans « sel » ?","reviewKey":"letter:sin"},{"id":"final_exam-m5-m1l5-sound-zza","type":"choice","format":"mcq","prompt":"Quel son correspond à cette lettre ?","options":[{"id":"dal","label":"« d »","why":"د est dāl : « d » comme dans « dos ». Repère visuel : aucun point."},{"id":"zza","label":"« ẓ »"},{"id":"tta","label":"« ṭ »","why":"ط est ṭā’ : « t » emphatique : son grave, arrière de la langue relevé. Repère visuel : aucun point."},{"id":"jim","label":"« j »","why":"ج est jīm : « dj » comme dans « djinn ». Repère visuel : un point en dessous."}],"answer":"zza","explanation":"ظ se nomme ẓā’ (ظَاء) et se transcrit « ẓ » : « th » de « this » prononcé de façon emphatique (grave). Repère visuel : un point au-dessus.","ar":"ظ","reviewKey":"letter:zza"},{"id":"final_exam-m5-m1l6-listen-qaf","type":"choice","format":"listen","prompt":"Écoutez puis choisissez la lettre entendue","options":[{"id":"mim","ar":"م","why":"م est mīm : « m » comme dans « mer ». Repère visuel : aucun point."},{"id":"fa","ar":"ف","why":"ف est fā’ : « f » comme dans « fil ». Repère visuel : un point au-dessus."},{"id":"qaf","ar":"ق"},{"id":"ya","ar":"ي","why":"ي est yā’ : « y » comme dans « yaourt », ou voyelle longue « î ». Repère visuel : deux points en dessous."}],"answer":"qaf","explanation":"ق se nomme qāf (قَاف) et se transcrit « q » : « k » prononcé très au fond, contre la luette. Repère visuel : deux points au-dessus.","audio":"letter:qaf","textFallback":"Quelle lettre se prononce « k » prononcé très au fond, contre la luette ?","reviewKey":"letter:qaf"},{"id":"final_exam-m5-m1l7-name-waw","type":"choice","format":"visual","prompt":"Quelle lettre s''appelle « wāw » ?","options":[{"id":"waw","ar":"و"},{"id":"tta","ar":"ط","why":"ط est ṭā’ : « t » emphatique : son grave, arrière de la langue relevé. Repère visuel : aucun point."},{"id":"dhal","ar":"ذ","why":"ذ est dhāl : « th » de l’anglais « this » : langue entre les dents, avec la voix. Repère visuel : un point au-dessus."},{"id":"jim","ar":"ج","why":"ج est jīm : « dj » comme dans « djinn ». Repère visuel : un point en dessous."}],"answer":"waw","explanation":"و se nomme wāw (وَاو) et se transcrit « w / ū » : « w » comme dans « watt », ou voyelle longue « oû ». Repère visuel : aucun point.","reviewKey":"letter:waw"},{"id":"final_exam-m5-m1l8-1","type":"choice","format":"visual","prompt":"Quelle lettre a trois points au-dessus ?","options":[{"id":"b","ar":"ت","why":"ت a deux points au-dessus."},{"id":"a","ar":"ث"},{"id":"c","ar":"ب","why":"ب a un seul point, en dessous."},{"id":"d","ar":"ن","why":"ن a un point au-dessus et un corps plus arrondi."}],"answer":"a","explanation":"ث (thā’) porte trois points au-dessus ; ش (shīn) aussi, mais avec un squelette à dents.","reviewKey":"letter:tha"},{"id":"final_exam-m5-m2l1-form-initial-nun","type":"choice","format":"visual","prompt":"Quelle est la forme initiale (début de mot) de nūn ?","options":[{"id":"ok","ar":"نـ"},{"id":"oth","ar":"تـ","why":"C''est la forme initiale (début de mot) de tā’."},{"id":"sib","ar":"بـ","why":"C''est la forme initiale (début de mot) de bā’ (un point en dessous), pas de nūn (un point au-dessus)."},{"id":"iso","ar":"ـن","why":"Ce tracé n''est pas celui de la position initiale (début de mot)."}],"answer":"ok","explanation":"nūn en position initiale (début de mot) s''écrit نـ. Cette lettre se lie aux deux côtés.","reviewKey":"form:nun"},{"id":"final_exam-m5-m2l2-form-final-mim","type":"choice","format":"visual","prompt":"Quelle est la forme finale (fin de mot) de mīm ?","options":[{"id":"ok","ar":"ـم"},{"id":"oth","ar":"ـت","why":"C''est la forme finale (fin de mot) de tā’."},{"id":"sib","ar":"ـب","why":"C''est la forme finale (fin de mot) de bā’ (un point en dessous), pas de mīm (aucun point)."}],"answer":"ok","explanation":"mīm en position finale (fin de mot) s''écrit ـم. Cette lettre se lie aux deux côtés.","reviewKey":"form:mim"},{"id":"final_exam-m5-m2l3-2","type":"choice","format":"mcq","prompt":"Combien de lettres arabes ne se lient jamais à la lettre suivante ?","options":[{"id":"a","label":"6"},{"id":"d","label":"28","why":"La grande majorité des lettres se lient des deux côtés."},{"id":"c","label":"8","why":"Seules six lettres ont cette propriété : ا د ذ ر ز و."},{"id":"b","label":"4","why":"Il en manque deux : la liste complète est ا د ذ ر ز و."}],"answer":"a","explanation":"Les six lettres sont ا د ذ ر ز و.","reviewKey":"rule:non-joining"},{"id":"final_exam-m5-m2l4-form-final-kaf","type":"choice","format":"visual","prompt":"Quelle est la forme finale (fin de mot) de kāf ?","options":[{"id":"oth","ar":"ـت","why":"C''est la forme finale (fin de mot) de tā’."},{"id":"sib","ar":"ـب","why":"C''est la forme finale (fin de mot) de bā’ (un point en dessous), pas de kāf (aucun point)."},{"id":"ok","ar":"ـك"}],"answer":"ok","explanation":"kāf en position finale (fin de mot) s''écrit ـك. Cette lettre se lie aux deux côtés.","reviewKey":"form:kaf"},{"id":"final_exam-m5-m3l1-syl-ta-a","type":"choice","format":"syllable","prompt":"Comment se lit cette syllabe ?","options":[{"id":"c","label":"tu","why":"« tu » s’écrirait avec une ḍamma (petit wāw au-dessus)."},{"id":"a","label":"ta"},{"id":"b","label":"ti","why":"« ti » s’écrirait avec une kasra (petit trait en dessous)."}],"answer":"a","explanation":"تَ : la lettre tā’ porte une fatḥa, on lit « ta ».","ar":"تَ","audio":"syll:ta-a","reviewKey":"haraka:a"},{"id":"final_exam-m5-m3l2-syl-ba-i","type":"choice","format":"syllable","prompt":"Comment se lit cette syllabe ?","options":[{"id":"c","label":"bu","why":"« bu » s’écrirait avec une ḍamma (petit wāw au-dessus)."},{"id":"b","label":"ba","why":"« ba » s’écrirait avec une fatḥa (petit trait au-dessus)."},{"id":"a","label":"bi"}],"answer":"a","explanation":"بِ : la lettre bā’ porte une kasra, on lit « bi ».","ar":"بِ","audio":"syll:ba-i","reviewKey":"haraka:i"},{"id":"final_exam-m5-m3l3-syl-ra-u","type":"choice","format":"syllable","prompt":"Comment se lit cette syllabe ?","options":[{"id":"b","label":"ra","why":"« ra » s’écrirait avec une fatḥa (petit trait au-dessus)."},{"id":"c","label":"ri","why":"« ri » s’écrirait avec une kasra (petit trait en dessous)."},{"id":"a","label":"ru"}],"answer":"a","explanation":"رُ : la lettre rā’ porte une ḍamma, on lit « ru ».","ar":"رُ","audio":"syll:ra-u","reviewKey":"haraka:u"},{"id":"final_exam-m5-m3l4-1","type":"choice","format":"fill","prompt":"Comment se lit ce mot ?","options":[{"id":"a","label":"min"},{"id":"c","label":"mun","why":"م porte une kasra (trait dessous), donc « mi », pas « mu »."},{"id":"b","label":"mina","why":"Le sukūn sur ن interdit toute voyelle après lui."}],"answer":"a","explanation":"مِ (mi) + نْ (n sans voyelle) = « min ».","ar":"مِنْ","audio":"word:min","reviewKey":"word:min"},{"id":"final_exam-m5-m3l5-4","type":"choice","format":"visual","prompt":"Lequel de ces mots contient une shadda ?","options":[{"id":"b","ar":"قُلْ","why":"قُلْ contient un sukūn (petit cercle), pas une shadda."},{"id":"c","ar":"مِنْ","why":"مِنْ contient une kasra et un sukūn."},{"id":"a","ar":"ثُمَّ"}],"answer":"a","explanation":"Dans ثُمَّ, le م porte une shadda surmontée d’une fatḥa.","reviewKey":"haraka:shadda"},{"id":"final_exam-m5-m3l6-3","type":"choice","format":"fill","prompt":"Comment se lit ce mot ?","options":[{"id":"c","label":"kitābun","why":"« un » serait une double ḍamma au-dessus."},{"id":"a","label":"kitābin"},{"id":"b","label":"kitābi","why":"Le tanwīn ajoute un « n » : « in »."}],"answer":"a","explanation":"Deux kasra ( ـٍ ) = « in ».","ar":"كِتَابٍ","audio":"word:kitabin","reviewKey":"word:kitabin"},{"id":"final_exam-m5-m3l7-4","type":"choice","format":"mcq","prompt":"Quelle lettre allonge la kasra ?","options":[{"id":"a","ar":"ي"},{"id":"b","ar":"ا","why":"ا allonge la fatḥa (« ā »)."},{"id":"c","ar":"و","why":"و allonge la ḍamma (« ū »)."}],"answer":"a","explanation":"kasra + ي = « ī ».","reviewKey":"rule:long-vowels"},{"id":"final_exam-m5-m3l8-2","type":"choice","format":"fill","prompt":"Comment se lit ce mot ?","options":[{"id":"a","label":"al-qamar"},{"id":"c","label":"al-qamr","why":"م porte une fatḥa : « ma »."},{"id":"b","label":"aq-qamar","why":"ق est une lettre lunaire : le lām se prononce."}],"answer":"a","explanation":"ق est lunaire : on prononce « al ».","ar":"الْقَمَر","audio":"word:alqamar","reviewKey":"word:alqamar"},{"id":"final_exam-m5-m4l1-4","type":"choice","format":"fill","prompt":"Comment se lit ce mot ?","options":[{"id":"b","label":"jalisa","why":"ل porte une fatḥa (trait au-dessus)."},{"id":"a","label":"jalasa"},{"id":"c","label":"halasa","why":"ج a un point dessous : « j »."}],"answer":"a","explanation":"جَ (ja) + لَ (la) + سَ (sa).","ar":"جَلَسَ","audio":"word:jalasa","reviewKey":"word:jalasa"},{"id":"final_exam-m5-m4l2-1","type":"choice","format":"fill","prompt":"Comment se lit ce mot ?","options":[{"id":"a","label":"qalb"},{"id":"b","label":"qalab","why":"ل porte un sukūn : pas de voyelle après lui."},{"id":"c","label":"kalb","why":"ق (deux points, tête ronde) n’est pas ك : son plus profond."}],"answer":"a","explanation":"قَلْ (qal) + ب = « qalb ».","ar":"قَلْب","audio":"word:qalb","reviewKey":"word:qalb"},{"id":"final_exam-m5-m4l3-2","type":"choice","format":"fill","prompt":"Comment se lit ce mot ?","options":[{"id":"c","label":"rusūl","why":"ر porte une fatḥa."},{"id":"a","label":"rasūl"},{"id":"b","label":"rasul","why":"Le و après سُ allonge le son."}],"answer":"a","explanation":"رَ (ra) + سُو (sū) + ل.","ar":"رَسُول","audio":"word:rasul","reviewKey":"word:rasul"},{"id":"final_exam-m5-m4l4-1","type":"choice","format":"fill","prompt":"Comment se lit ce mot ?","options":[{"id":"a","label":"rabbun"},{"id":"c","label":"rabbin","why":"Le tanwīn est une double ḍamma : « un »."},{"id":"b","label":"rabun","why":"La shadda double le ب."}],"answer":"a","explanation":"رَ (ra) + بٌّ (b-bun).","ar":"رَبٌّ","audio":"word:rabbun","reviewKey":"word:rabbun"},{"id":"final_exam-m5-m4l5-1","type":"choice","format":"fill","prompt":"Comment se lit ce mot ?","options":[{"id":"b","label":"al-nūr","why":"ن est solaire : ل ne se prononce pas."},{"id":"a","label":"an-nūr"},{"id":"c","label":"an-nur","why":"Le و allonge le son : « nū »."}],"answer":"a","explanation":"ن solaire : « an-nūr ».","ar":"النُّور","audio":"word:annur","reviewKey":"word:annur"},{"id":"final_exam-m5-m5l1-tr-rabb","type":"choice","format":"translate","prompt":"Que signifie ce mot ?","options":[{"id":"c","label":"châtiment","why":"« châtiment » se dit عَذَاب (ʿadhāb)."},{"id":"b","label":"il a cru, il a eu foi","why":"« il a cru, il a eu foi » se dit آمَنَ (āmana)."},{"id":"a","label":"Seigneur, Maître"},{"id":"d","label":"messager","why":"« messager » se dit رَسُول (rasūl)."}],"answer":"a","explanation":"رَبّ (rabb) signifie « Seigneur, Maître » ; racine ر ب ب.","ar":"رَبّ","audio":"word:rabb","reviewKey":"word:rabb"},{"id":"final_exam-m5-m5l2-tr-amana","type":"choice","format":"translate","prompt":"Que signifie ce mot ?","options":[{"id":"c","label":"eau","why":"« eau » se dit مَاء (māʾ)."},{"id":"d","label":"il était, il fut","why":"« il était, il fut » se dit كَانَ (kāna)."},{"id":"a","label":"il a cru, il a eu foi"},{"id":"b","label":"louange","why":"« louange » se dit حَمْد (ḥamd)."}],"answer":"a","explanation":"آمَنَ (āmana) signifie « il a cru, il a eu foi » ; racine ء م ن.","ar":"آمَنَ","audio":"word:amana","reviewKey":"word:amana"},{"id":"final_exam-m5-m5l3-root-qalb","type":"choice","format":"mcq","prompt":"Quelle est la racine de ce mot ?","options":[{"id":"c","ar":"ء م ر","why":"ء م ر est la racine d’autres mots (أَمْر)."},{"id":"a","ar":"ق ل ب"},{"id":"b","ar":"ء م ن","why":"ء م ن est la racine d’autres mots (آمَنَ)."}],"answer":"a","explanation":"La racine de قَلْب est ق ل ب : ce sont les consonnes qui restent quand on retire les voyelles et les lettres ajoutées.","ar":"قَلْب","reviewKey":"root:ق ل ب"},{"id":"final_exam-m5-m5l4-tr-shay","type":"choice","format":"translate","prompt":"Que signifie ce mot ?","options":[{"id":"a","label":"chose"},{"id":"b","label":"il a fait, il a placé, il a rendu","why":"« il a fait, il a placé, il a rendu » se dit جَعَلَ (jaʿala)."},{"id":"c","label":"il a su","why":"« il a su » se dit عَلِمَ (ʿalima)."},{"id":"d","label":"il a mécru, il a renié","why":"« il a mécru, il a renié » se dit كَفَرَ (kafara)."}],"answer":"a","explanation":"شَيْء (shayʾ) signifie « chose » ; racine ش ي ء.","ar":"شَيْء","audio":"word:shay","reviewKey":"word:shay"},{"id":"final_exam-m5-m5l5-tr-salah","type":"choice","format":"translate","prompt":"Que signifie ce mot ?","options":[{"id":"c","label":"il a fait, il a œuvré","why":"« il a fait, il a œuvré » se dit عَمِلَ (ʿamila)."},{"id":"b","label":"religion ; rétribution (selon le contexte)","why":"« religion ; rétribution (selon le contexte) » se dit دِين (dīn)."},{"id":"d","label":"jour","why":"« jour » se dit يَوْم (yawm)."},{"id":"a","label":"prière"}],"answer":"a","explanation":"صَلَاة (ṣalāh) signifie « prière » ; racine ص ل و.","ar":"صَلَاة","audio":"word:salah","reviewKey":"word:salah"},{"id":"final_exam-m5-m5l6-match","type":"match","prompt":"Associez chaque mot à son sens","pairs":[{"left":{"id":"l-qala","ar":"قَالَ"},"right":{"id":"r-qala","label":"il a dit"}},{"left":{"id":"l-kana","ar":"كَانَ"},"right":{"id":"r-kana","label":"il était, il fut"}},{"left":{"id":"l-amr","ar":"أَمْر"},"right":{"id":"r-amr","label":"ordre, affaire"}},{"left":{"id":"l-kataba","ar":"كَتَبَ"},"right":{"id":"r-kataba","label":"il a écrit ; il a prescrit"}}],"explanation":"قَالَ = il a dit · كَانَ = il était, il fut · أَمْر = ordre, affaire · كَتَبَ = il a écrit ; il a prescrit"}],"summary":["Résultat enregistré dans votre progression.","Les notions manquées sont ajoutées à vos révisions."]}'::jsonb) on conflict (lesson_id) do update set content = excluded.content, version = public.lesson_contents.version + 1, updated_at = now();
insert into public.modules (id, course_id, position, title_fr, subtitle_fr, tier, published) values (6, 1, 6, 'Introduction à la conjugaison', 'Racine, passé, présent, futur, impératif', 'premium', true) on conflict (id) do update set title_fr = excluded.title_fr, subtitle_fr = excluded.subtitle_fr, tier = excluded.tier;
insert into public.lessons (id, module_id, position, title_fr, objective_fr, difficulty, est_minutes, kind, published) values ('m6l1', 6, 1, 'Le verbe arabe et sa racine', 'Comprendre racine, schème et forme de base فَعَلَ', 1, 9, 'lesson', true) on conflict (id) do update set title_fr = excluded.title_fr, objective_fr = excluded.objective_fr, difficulty = excluded.difficulty, est_minutes = excluded.est_minutes, kind = excluded.kind, position = excluded.position;
insert into public.lesson_contents (lesson_id, content) values ('m6l1', '{"steps":[{"kind":"explain","text":"En arabe, la plupart des verbes reposent sur une racine de trois consonnes (verbe trilittère). Les grammairiens arabes représentent ces trois consonnes par ف ع ل : on parle du schème فَعَلَ."},{"kind":"explain","text":"La forme de référence d’un verbe n’est pas l’infinitif (qui n’existe pas en arabe), mais la 3e personne du masculin singulier du passé : كَتَبَ « il a écrit ». C’est sous cette forme qu’on cherche un verbe dans un dictionnaire."},{"kind":"table","caption":"Racine et schème","head":["Racine","Verbe (il a…)","Sens"],"rows":[["ك ت ب","كَتَبَ","écrire"],["خ ل ق","خَلَقَ","créer"],["ع ل م","عَلِمَ","savoir"],["ذ ه ب","ذَهَبَ","aller"]],"arCols":[0,1]},{"kind":"tip","text":"La voyelle de la 2e consonne au passé varie : كَتَبَ (a), عَلِمَ (i). Elle s’apprend avec chaque verbe."}],"exercises":[{"id":"m6l1-1","type":"choice","format":"mcq","prompt":"Quelle est la forme de référence d’un verbe arabe ?","options":[{"id":"b","label":"L’infinitif","why":"L’arabe n’a pas d’infinitif : on cite le verbe au passé, à la 3e personne du masculin singulier."},{"id":"c","label":"L’impératif","why":"L’impératif se forme à partir du présent ; ce n’est pas la forme de dictionnaire."},{"id":"a","label":"Le passé, 3e personne du masculin singulier (« il a… »)"}],"answer":"a","explanation":"On cite le verbe sous la forme « il a fait » : كَتَبَ.","reviewKey":"conj:reference"},{"id":"m6l1-2","type":"choice","format":"mcq","prompt":"Quelle est la racine de خَلَقَ ?","options":[{"id":"c","ar":"ح ل ق","why":"La première lettre porte un point au-dessus : c’est خ, pas ح."},{"id":"b","ar":"خ ل ك","why":"La dernière lettre est ق (deux points, tête ronde), pas ك."},{"id":"a","ar":"خ ل ق"}],"answer":"a","explanation":"خَلَقَ : racine خ ل ق, « créer ».","ar":"خَلَقَ","reviewKey":"root:خ ل ق"},{"id":"m6l1-3","type":"choice","format":"mcq","prompt":"Par quelles lettres les grammairiens représentent-ils la racine ?","options":[{"id":"c","ar":"ق و ل","why":"ق و ل est la racine de « dire »."},{"id":"a","ar":"ف ع ل"},{"id":"b","ar":"ك ت ب","why":"ك ت ب est une racine réelle (écrire), pas le modèle conventionnel."}],"answer":"a","explanation":"Le modèle conventionnel est ف ع ل, d’où le schème فَعَلَ."}],"summary":["Verbe trilittère = 3 consonnes.","Forme de référence : كَتَبَ « il a écrit ».","Schème modèle : فَعَلَ."]}'::jsonb) on conflict (lesson_id) do update set content = excluded.content, version = public.lesson_contents.version + 1, updated_at = now();
insert into public.lessons (id, module_id, position, title_fr, objective_fr, difficulty, est_minutes, kind, published) values ('m6l2', 6, 2, 'Le passé (accompli) : singulier', 'Conjuguer كَتَبَ au singulier', 2, 9, 'lesson', true) on conflict (id) do update set title_fr = excluded.title_fr, objective_fr = excluded.objective_fr, difficulty = excluded.difficulty, est_minutes = excluded.est_minutes, kind = excluded.kind, position = excluded.position;
insert into public.lesson_contents (lesson_id, content) values ('m6l2', '{"steps":[{"kind":"explain","text":"Le passé (al-māḍī, « l’accompli ») exprime une action terminée. On le forme en ajoutant une terminaison à la base كَتَبْـ / كَتَبَـ. La terminaison indique la personne, le genre et le nombre."},{"kind":"table","caption":"Passé singulier de كَتَبَ","head":["Pronom","Sens","Verbe","Lecture"],"rows":[["هُوَ","il","كَتَبَ","kataba"],["هِيَ","elle","كَتَبَتْ","katabat"],["أَنْتَ","tu (masc.)","كَتَبْتَ","katabta"],["أَنْتِ","tu (fém.)","كَتَبْتِ","katabti"],["أَنَا","je","كَتَبْتُ","katabtu"]],"arCols":[0,2]},{"kind":"tip","text":"« tu » existe au masculin (كَتَبْتَ) et au féminin (كَتَبْتِ) : seule la voyelle finale change."}],"exercises":[{"id":"m6-past-0","type":"choice","format":"mcq","prompt":"Quelle est la forme du passé de كَتَبَ pour هُوَ (il) ?","options":[{"id":"b","ar":"كَتَبَتْ","label":"katabat","why":"كَتَبَتْ correspond à هِيَ (elle)."},{"id":"c","ar":"كَتَبْتَ","label":"katabta","why":"كَتَبْتَ correspond à أَنْتَ (tu (masc.))."},{"id":"a","ar":"كَتَبَ","label":"kataba"}],"answer":"a","explanation":"هُوَ (il) → كَتَبَ (kataba).","reviewKey":"conj:past:kataba"},{"id":"m6-past-1","type":"choice","format":"mcq","prompt":"Quelle est la forme du passé de كَتَبَ pour هِيَ (elle) ?","options":[{"id":"c","ar":"كَتَبْتَ","label":"katabta","why":"كَتَبْتَ correspond à أَنْتَ (tu (masc.))."},{"id":"a","ar":"كَتَبَتْ","label":"katabat"},{"id":"b","ar":"كَتَبَ","label":"kataba","why":"كَتَبَ correspond à هُوَ (il)."}],"answer":"a","explanation":"هِيَ (elle) → كَتَبَتْ (katabat).","reviewKey":"conj:past:katabat"},{"id":"m6-past-2","type":"choice","format":"mcq","prompt":"Quelle est la forme du passé de كَتَبَ pour أَنْتَ (tu (masc.)) ?","options":[{"id":"a","ar":"كَتَبْتَ","label":"katabta"},{"id":"b","ar":"كَتَبَ","label":"kataba","why":"كَتَبَ correspond à هُوَ (il)."},{"id":"c","ar":"كَتَبَتْ","label":"katabat","why":"كَتَبَتْ correspond à هِيَ (elle)."}],"answer":"a","explanation":"أَنْتَ (tu (masc.)) → كَتَبْتَ (katabta).","reviewKey":"conj:past:katabta"},{"id":"m6-past-3","type":"choice","format":"mcq","prompt":"Quelle est la forme du passé de كَتَبَ pour أَنْتِ (tu (fém.)) ?","options":[{"id":"c","ar":"كَتَبَتْ","label":"katabat","why":"كَتَبَتْ correspond à هِيَ (elle)."},{"id":"a","ar":"كَتَبْتِ","label":"katabti"},{"id":"b","ar":"كَتَبَ","label":"kataba","why":"كَتَبَ correspond à هُوَ (il)."}],"answer":"a","explanation":"أَنْتِ (tu (fém.)) → كَتَبْتِ (katabti).","reviewKey":"conj:past:katabti"},{"id":"m6-past-4","type":"choice","format":"mcq","prompt":"Quelle est la forme du passé de كَتَبَ pour أَنَا (je) ?","options":[{"id":"a","ar":"كَتَبْتُ","label":"katabtu"},{"id":"c","ar":"كَتَبَتْ","label":"katabat","why":"كَتَبَتْ correspond à هِيَ (elle)."},{"id":"b","ar":"كَتَبَ","label":"kataba","why":"كَتَبَ correspond à هُوَ (il)."}],"answer":"a","explanation":"أَنَا (je) → كَتَبْتُ (katabtu).","reviewKey":"conj:past:katabtu"}],"summary":["هُوَ كَتَبَ · هِيَ كَتَبَتْ · أَنْتَ كَتَبْتَ · أَنْتِ كَتَبْتِ · أَنَا كَتَبْتُ"]}'::jsonb) on conflict (lesson_id) do update set content = excluded.content, version = public.lesson_contents.version + 1, updated_at = now();
insert into public.lessons (id, module_id, position, title_fr, objective_fr, difficulty, est_minutes, kind, published) values ('m6l3', 6, 3, 'Le passé : pluriel et duel', 'Conjuguer كَتَبَ au pluriel et au duel', 2, 9, 'lesson', true) on conflict (id) do update set title_fr = excluded.title_fr, objective_fr = excluded.objective_fr, difficulty = excluded.difficulty, est_minutes = excluded.est_minutes, kind = excluded.kind, position = excluded.position;
insert into public.lesson_contents (lesson_id, content) values ('m6l3', '{"steps":[{"kind":"explain","text":"L’arabe classique distingue trois nombres : singulier, duel (deux personnes) et pluriel (trois et plus). Il distingue aussi le masculin et le féminin à la 2e et à la 3e personne."},{"kind":"table","caption":"Passé pluriel et duel de كَتَبَ","head":["Pronom","Sens","Verbe","Lecture"],"rows":[["هُمْ","ils","كَتَبُوا","katabū"],["هُنَّ","elles","كَتَبْنَ","katabna"],["أَنْتُمْ","vous (masc.)","كَتَبْتُمْ","katabtum"],["أَنْتُنَّ","vous (fém.)","كَتَبْتُنَّ","katabtunna"],["نَحْنُ","nous","كَتَبْنَا","katabnā"],["هُمَا","eux deux","كَتَبَا","katabā"],["هُمَا","elles deux","كَتَبَتَا","katabatā"],["أَنْتُمَا","vous deux","كَتَبْتُمَا","katabtumā"]],"arCols":[0,2]},{"kind":"tip","text":"Le alif final de كَتَبُوا ne se prononce pas : c’est une convention d’écriture."}],"exercises":[{"id":"m6-past-10","type":"choice","format":"mcq","prompt":"Quelle est la forme du passé de كَتَبَ pour هُمْ (ils) ?","options":[{"id":"a","ar":"كَتَبُوا","label":"katabū"},{"id":"c","ar":"كَتَبْتُمْ","label":"katabtum","why":"كَتَبْتُمْ correspond à أَنْتُمْ (vous (masc.))."},{"id":"b","ar":"كَتَبْنَ","label":"katabna","why":"كَتَبْنَ correspond à هُنَّ (elles)."}],"answer":"a","explanation":"هُمْ (ils) → كَتَبُوا (katabū).","reviewKey":"conj:past:katabū"},{"id":"m6-past-11","type":"choice","format":"mcq","prompt":"Quelle est la forme du passé de كَتَبَ pour هُنَّ (elles) ?","options":[{"id":"b","ar":"كَتَبُوا","label":"katabū","why":"كَتَبُوا correspond à هُمْ (ils)."},{"id":"a","ar":"كَتَبْنَ","label":"katabna"},{"id":"c","ar":"كَتَبْتُمْ","label":"katabtum","why":"كَتَبْتُمْ correspond à أَنْتُمْ (vous (masc.))."}],"answer":"a","explanation":"هُنَّ (elles) → كَتَبْنَ (katabna).","reviewKey":"conj:past:katabna"},{"id":"m6-past-12","type":"choice","format":"mcq","prompt":"Quelle est la forme du passé de كَتَبَ pour أَنْتُمْ (vous (masc.)) ?","options":[{"id":"c","ar":"كَتَبْنَ","label":"katabna","why":"كَتَبْنَ correspond à هُنَّ (elles)."},{"id":"b","ar":"كَتَبُوا","label":"katabū","why":"كَتَبُوا correspond à هُمْ (ils)."},{"id":"a","ar":"كَتَبْتُمْ","label":"katabtum"}],"answer":"a","explanation":"أَنْتُمْ (vous (masc.)) → كَتَبْتُمْ (katabtum).","reviewKey":"conj:past:katabtum"},{"id":"m6-past-13","type":"choice","format":"mcq","prompt":"Quelle est la forme du passé de كَتَبَ pour أَنْتُنَّ (vous (fém.)) ?","options":[{"id":"c","ar":"كَتَبْنَ","label":"katabna","why":"كَتَبْنَ correspond à هُنَّ (elles)."},{"id":"a","ar":"كَتَبْتُنَّ","label":"katabtunna"},{"id":"b","ar":"كَتَبُوا","label":"katabū","why":"كَتَبُوا correspond à هُمْ (ils)."}],"answer":"a","explanation":"أَنْتُنَّ (vous (fém.)) → كَتَبْتُنَّ (katabtunna).","reviewKey":"conj:past:katabtunna"},{"id":"m6-past-14","type":"choice","format":"mcq","prompt":"Quelle est la forme du passé de كَتَبَ pour نَحْنُ (nous) ?","options":[{"id":"b","ar":"كَتَبُوا","label":"katabū","why":"كَتَبُوا correspond à هُمْ (ils)."},{"id":"a","ar":"كَتَبْنَا","label":"katabnā"},{"id":"c","ar":"كَتَبْنَ","label":"katabna","why":"كَتَبْنَ correspond à هُنَّ (elles)."}],"answer":"a","explanation":"نَحْنُ (nous) → كَتَبْنَا (katabnā).","reviewKey":"conj:past:katabnā"},{"id":"m6l3-dual","type":"choice","format":"mcq","prompt":"Que désigne le duel ?","options":[{"id":"c","label":"Trois personnes ou plus","why":"Trois et plus = pluriel."},{"id":"a","label":"Deux personnes ou deux choses"},{"id":"b","label":"Un pluriel de politesse","why":"L’arabe n’a pas de « vous » de politesse grammatical ; le duel désigne exactement deux."}],"answer":"a","explanation":"Le duel est un nombre à part entière : exactement deux."}],"summary":["Pluriel : كَتَبُوا (ils), كَتَبْنَا (nous).","Duel : كَتَبَا (eux deux)."]}'::jsonb) on conflict (lesson_id) do update set content = excluded.content, version = public.lesson_contents.version + 1, updated_at = now();
insert into public.lessons (id, module_id, position, title_fr, objective_fr, difficulty, est_minutes, kind, published) values ('m6l4', 6, 4, 'Le présent (inaccompli)', 'Conjuguer يَكْتُبُ', 2, 9, 'lesson', true) on conflict (id) do update set title_fr = excluded.title_fr, objective_fr = excluded.objective_fr, difficulty = excluded.difficulty, est_minutes = excluded.est_minutes, kind = excluded.kind, position = excluded.position;
insert into public.lesson_contents (lesson_id, content) values ('m6l4', '{"steps":[{"kind":"explain","text":"L’inaccompli (al-muḍāriʿ) exprime une action en cours, habituelle ou à venir. Il se forme avec des préfixes (et parfois des suffixes) autour de la racine : يَـ, تَـ, أَ, نَـ."},{"kind":"table","caption":"Inaccompli de كَتَبَ","head":["Pronom","Sens","Verbe","Lecture"],"rows":[["هُوَ","il","يَكْتُبُ","yaktubu"],["هِيَ","elle","تَكْتُبُ","taktubu"],["أَنْتَ","tu (masc.)","تَكْتُبُ","taktubu"],["أَنْتِ","tu (fém.)","تَكْتُبِينَ","taktubīna"],["أَنَا","je","أَكْتُبُ","aktubu"],["هُمْ","ils","يَكْتُبُونَ","yaktubūna"],["هُنَّ","elles","يَكْتُبْنَ","yaktubna"],["أَنْتُمْ","vous (masc.)","تَكْتُبُونَ","taktubūna"],["أَنْتُنَّ","vous (fém.)","تَكْتُبْنَ","taktubna"],["نَحْنُ","nous","نَكْتُبُ","naktubu"],["هُمَا","eux deux","يَكْتُبَانِ","yaktubāni"]],"arCols":[0,2]},{"kind":"explain","text":"La voyelle de la 2e consonne au présent varie selon les verbes et s’apprend avec eux : يَكْتُبُ (u), يَجْلِسُ (i), يَذْهَبُ (a)."},{"kind":"example","ar":"يَجْلِسُ","translit":"yajlisu","fr":"il s’assoit","audio":"word:yajlisu"},{"kind":"example","ar":"يَذْهَبُ","translit":"yadhhabu","fr":"il va","audio":"word:yadhhabu"}],"exercises":[{"id":"m6l4-1","type":"choice","format":"mcq","prompt":"Quel préfixe marque « je » à l’inaccompli ?","options":[{"id":"c","ar":"يَـ","why":"يَـ marque « il » (et « ils ») : يَكْتُبُ."},{"id":"b","ar":"نَـ","why":"نَـ marque « nous » : نَكْتُبُ."},{"id":"a","ar":"أَ"}],"answer":"a","explanation":"أَكْتُبُ = « j’écris ».","reviewKey":"conj:present:prefix"},{"id":"m6l4-2","type":"choice","format":"mcq","prompt":"Que signifie نَكْتُبُ ?","options":[{"id":"c","label":"nous avons écrit","why":"« nous avons écrit » = كَتَبْنَا (passé)."},{"id":"a","label":"nous écrivons"},{"id":"b","label":"il écrit","why":"« il écrit » = يَكْتُبُ (préfixe يَـ)."}],"answer":"a","explanation":"Préfixe نَـ = « nous ».","ar":"نَكْتُبُ","reviewKey":"conj:present:naktubu"},{"id":"m6l4-3","type":"choice","format":"mcq","prompt":"تَكْتُبُ peut signifier :","options":[{"id":"b","label":"uniquement « tu écris »","why":"تَكْتُبُ sert aussi pour « elle » : le contexte tranche."},{"id":"a","label":"« elle écrit » ou « tu (masc.) écris »"},{"id":"c","label":"« ils écrivent »","why":"« ils écrivent » = يَكْتُبُونَ."}],"answer":"a","explanation":"تَكْتُبُ est commun à هِيَ et أَنْتَ.","ar":"تَكْتُبُ"},{"id":"m6l4-4","type":"choice","format":"mcq","prompt":"Quelle forme correspond à « ils écrivent » ?","options":[{"id":"c","ar":"تَكْتُبُونَ","why":"تَكْتُبُونَ = « vous écrivez »."},{"id":"a","ar":"يَكْتُبُونَ"},{"id":"b","ar":"كَتَبُوا","why":"كَتَبُوا = « ils ont écrit » (passé)."}],"answer":"a","explanation":"يَـ + كْتُبُ + ونَ = يَكْتُبُونَ.","reviewKey":"conj:present:yaktubuna"}],"summary":["Inaccompli = préfixes يَـ تَـ أَ نَـ (+ suffixes).","يَكْتُبُ = il écrit."]}'::jsonb) on conflict (lesson_id) do update set content = excluded.content, version = public.lesson_contents.version + 1, updated_at = now();
insert into public.lessons (id, module_id, position, title_fr, objective_fr, difficulty, est_minutes, kind, published) values ('m6l5', 6, 5, 'Exprimer le futur', 'Former le futur avec سَـ et سَوْفَ', 2, 9, 'lesson', true) on conflict (id) do update set title_fr = excluded.title_fr, objective_fr = excluded.objective_fr, difficulty = excluded.difficulty, est_minutes = excluded.est_minutes, kind = excluded.kind, position = excluded.position;
insert into public.lesson_contents (lesson_id, content) values ('m6l5', '{"steps":[{"kind":"explain","text":"L’arabe n’a pas de temps futur distinct. On exprime le futur en plaçant سَـ (collé) ou سَوْفَ (séparé) devant l’inaccompli. سَوْفَ indique souvent un futur plus lointain."},{"kind":"example","ar":"سَيَكْتُبُ","translit":"sayaktubu","fr":"il écrira","audio":"word:sayaktubu"},{"kind":"example","ar":"سَوْفَ يَكْتُبُ","translit":"sawfa yaktubu","fr":"il écrira (plus tard)","audio":"word:sawfayaktubu"},{"kind":"tip","text":"Sans سَـ ni سَوْفَ, l’inaccompli peut déjà avoir un sens futur selon le contexte."}],"exercises":[{"id":"m6l5-1","type":"choice","format":"mcq","prompt":"Que signifie سَيَكْتُبُ ?","options":[{"id":"a","label":"il écrira"},{"id":"c","label":"écris !","why":"L’impératif est اُكْتُبْ."},{"id":"b","label":"il a écrit","why":"« il a écrit » = كَتَبَ."}],"answer":"a","explanation":"سَـ + inaccompli = futur.","ar":"سَيَكْتُبُ","reviewKey":"conj:future"},{"id":"m6l5-2","type":"choice","format":"mcq","prompt":"L’arabe classique possède-t-il un temps futur propre ?","options":[{"id":"b","label":"Oui, avec ses propres terminaisons","why":"Il n’existe que deux formes temporelles : accompli et inaccompli."},{"id":"a","label":"Non : on ajoute سَـ ou سَوْفَ à l’inaccompli"}],"answer":"a","explanation":"Le futur se construit sur l’inaccompli."},{"id":"m6l5-3","type":"choice","format":"mcq","prompt":"Comment dire « nous écrirons » ?","options":[{"id":"c","ar":"سَيَكْتُبُونَ","why":"سَيَكْتُبُونَ = « ils écriront »."},{"id":"a","ar":"سَنَكْتُبُ"},{"id":"b","ar":"كَتَبْنَا","why":"كَتَبْنَا = « nous avons écrit »."}],"answer":"a","explanation":"سَـ + نَكْتُبُ = سَنَكْتُبُ."}],"summary":["Futur = سَـ / سَوْفَ + inaccompli."]}'::jsonb) on conflict (lesson_id) do update set content = excluded.content, version = public.lesson_contents.version + 1, updated_at = now();
insert into public.lessons (id, module_id, position, title_fr, objective_fr, difficulty, est_minutes, kind, published) values ('m6l6', 6, 6, 'L’impératif', 'Former l’impératif de كَتَبَ, جَلَسَ, ذَهَبَ', 3, 9, 'lesson', true) on conflict (id) do update set title_fr = excluded.title_fr, objective_fr = excluded.objective_fr, difficulty = excluded.difficulty, est_minutes = excluded.est_minutes, kind = excluded.kind, position = excluded.position;
insert into public.lesson_contents (lesson_id, content) values ('m6l6', '{"steps":[{"kind":"explain","text":"L’impératif se forme à partir de l’inaccompli de la 2e personne : on retire le préfixe تَـ, on met un sukūn à la fin, et on ajoute une voyelle d’appui (hamzat al-waṣl) au début, car un mot arabe ne commence pas par une consonne sans voyelle."},{"kind":"explain","text":"La voyelle d’appui est « u » si la 2e consonne de l’inaccompli a une ḍamma (تَكْتُبُ → اُكْتُبْ), sinon « i » (تَجْلِسُ → اِجْلِسْ, تَذْهَبُ → اِذْهَبْ)."},{"kind":"table","caption":"Impératif de كَتَبَ","head":["Destinataire","Forme","Lecture"],"rows":[["toi (masc.)","اُكْتُبْ","uktub"],["toi (fém.)","اُكْتُبِي","uktubī"],["vous (masc.)","اُكْتُبُوا","uktubū"],["vous (fém.)","اُكْتُبْنَ","uktubna"],["vous deux","اُكْتُبَا","uktubā"]],"arCols":[1]},{"kind":"tip","text":"Dans le Coran, une forme impérative adressée à Dieu exprime une demande ou une invocation, pas un ordre : on parle alors de supplication (duʿāʾ)."}],"exercises":[{"id":"m6l6-1","type":"choice","format":"mcq","prompt":"Impératif masculin singulier de جَلَسَ / يَجْلِسُ ?","options":[{"id":"b","ar":"اُجْلُسْ","why":"L’inaccompli est يَجْلِسُ (kasra) : la voyelle d’appui est « i » et la kasra reste."},{"id":"c","ar":"جَلَسَ","why":"جَلَسَ est le passé."},{"id":"a","ar":"اِجْلِسْ"}],"answer":"a","explanation":"تَجْلِسُ → اِجْلِسْ.","reviewKey":"conj:imperative"},{"id":"m6l6-2","type":"choice","format":"mcq","prompt":"Pourquoi l’impératif commence-t-il par une voyelle d’appui ?","options":[{"id":"c","label":"Pour indiquer le féminin","why":"Le féminin est marqué par la terminaison ـِي."},{"id":"a","label":"Un mot arabe ne commence pas par une consonne sans voyelle"},{"id":"b","label":"Pour marquer la politesse","why":"La voyelle d’appui est une contrainte phonétique, pas une marque de politesse."}],"answer":"a","explanation":"كْتُبْ commencerait par deux consonnes sans voyelle : on ajoute اُ."},{"id":"m6l6-3","type":"choice","format":"mcq","prompt":"Comment dire « écrivez ! » à plusieurs hommes ?","options":[{"id":"c","ar":"كَتَبُوا","why":"كَتَبُوا = « ils ont écrit »."},{"id":"a","ar":"اُكْتُبُوا"},{"id":"b","ar":"اُكْتُبِي","why":"اُكْتُبِي s’adresse à une femme."}],"answer":"a","explanation":"Terminaison ـُوا pour le masculin pluriel."}],"summary":["Impératif = inaccompli de la 2e personne − préfixe + sukūn + voyelle d’appui."]}'::jsonb) on conflict (lesson_id) do update set content = excluded.content, version = public.lesson_contents.version + 1, updated_at = now();
insert into public.lessons (id, module_id, position, title_fr, objective_fr, difficulty, est_minutes, kind, published) values ('m6-test', 6, 99, 'Test du module 6 : la conjugaison', 'Valider les acquis du module : 80 % de bonnes réponses sont nécessaires.', 2, 8, 'module_test', true) on conflict (id) do update set title_fr = excluded.title_fr, objective_fr = excluded.objective_fr, difficulty = excluded.difficulty, est_minutes = excluded.est_minutes, kind = excluded.kind, position = excluded.position;
insert into public.lesson_contents (lesson_id, content) values ('m6-test', '{"steps":[{"kind":"explain","text":"Ce test reprend les notions des leçons du module. Prenez votre temps : il n’y a pas de limite de durée et vous pourrez le repasser."}],"exercises":[{"id":"module_test-m6-m6l1-2","type":"choice","format":"mcq","prompt":"Quelle est la racine de خَلَقَ ?","options":[{"id":"c","ar":"ح ل ق","why":"La première lettre porte un point au-dessus : c’est خ, pas ح."},{"id":"b","ar":"خ ل ك","why":"La dernière lettre est ق (deux points, tête ronde), pas ك."},{"id":"a","ar":"خ ل ق"}],"answer":"a","explanation":"خَلَقَ : racine خ ل ق, « créer ».","ar":"خَلَقَ","reviewKey":"root:خ ل ق"},{"id":"module_test-m6-m6l1-3","type":"choice","format":"mcq","prompt":"Par quelles lettres les grammairiens représentent-ils la racine ?","options":[{"id":"c","ar":"ق و ل","why":"ق و ل est la racine de « dire »."},{"id":"a","ar":"ف ع ل"},{"id":"b","ar":"ك ت ب","why":"ك ت ب est une racine réelle (écrire), pas le modèle conventionnel."}],"answer":"a","explanation":"Le modèle conventionnel est ف ع ل, d’où le schème فَعَلَ."},{"id":"module_test-m6-m6-past-2","type":"choice","format":"mcq","prompt":"Quelle est la forme du passé de كَتَبَ pour أَنْتَ (tu (masc.)) ?","options":[{"id":"a","ar":"كَتَبْتَ","label":"katabta"},{"id":"b","ar":"كَتَبَ","label":"kataba","why":"كَتَبَ correspond à هُوَ (il)."},{"id":"c","ar":"كَتَبَتْ","label":"katabat","why":"كَتَبَتْ correspond à هِيَ (elle)."}],"answer":"a","explanation":"أَنْتَ (tu (masc.)) → كَتَبْتَ (katabta).","reviewKey":"conj:past:katabta"},{"id":"module_test-m6-m6-past-3","type":"choice","format":"mcq","prompt":"Quelle est la forme du passé de كَتَبَ pour أَنْتِ (tu (fém.)) ?","options":[{"id":"c","ar":"كَتَبَتْ","label":"katabat","why":"كَتَبَتْ correspond à هِيَ (elle)."},{"id":"a","ar":"كَتَبْتِ","label":"katabti"},{"id":"b","ar":"كَتَبَ","label":"kataba","why":"كَتَبَ correspond à هُوَ (il)."}],"answer":"a","explanation":"أَنْتِ (tu (fém.)) → كَتَبْتِ (katabti).","reviewKey":"conj:past:katabti"},{"id":"module_test-m6-m6-past-12","type":"choice","format":"mcq","prompt":"Quelle est la forme du passé de كَتَبَ pour أَنْتُمْ (vous (masc.)) ?","options":[{"id":"c","ar":"كَتَبْنَ","label":"katabna","why":"كَتَبْنَ correspond à هُنَّ (elles)."},{"id":"b","ar":"كَتَبُوا","label":"katabū","why":"كَتَبُوا correspond à هُمْ (ils)."},{"id":"a","ar":"كَتَبْتُمْ","label":"katabtum"}],"answer":"a","explanation":"أَنْتُمْ (vous (masc.)) → كَتَبْتُمْ (katabtum).","reviewKey":"conj:past:katabtum"},{"id":"module_test-m6-m6-past-14","type":"choice","format":"mcq","prompt":"Quelle est la forme du passé de كَتَبَ pour نَحْنُ (nous) ?","options":[{"id":"b","ar":"كَتَبُوا","label":"katabū","why":"كَتَبُوا correspond à هُمْ (ils)."},{"id":"a","ar":"كَتَبْنَا","label":"katabnā"},{"id":"c","ar":"كَتَبْنَ","label":"katabna","why":"كَتَبْنَ correspond à هُنَّ (elles)."}],"answer":"a","explanation":"نَحْنُ (nous) → كَتَبْنَا (katabnā).","reviewKey":"conj:past:katabnā"},{"id":"module_test-m6-m6l4-2","type":"choice","format":"mcq","prompt":"Que signifie نَكْتُبُ ?","options":[{"id":"c","label":"nous avons écrit","why":"« nous avons écrit » = كَتَبْنَا (passé)."},{"id":"a","label":"nous écrivons"},{"id":"b","label":"il écrit","why":"« il écrit » = يَكْتُبُ (préfixe يَـ)."}],"answer":"a","explanation":"Préfixe نَـ = « nous ».","ar":"نَكْتُبُ","reviewKey":"conj:present:naktubu"},{"id":"module_test-m6-m6l4-1","type":"choice","format":"mcq","prompt":"Quel préfixe marque « je » à l’inaccompli ?","options":[{"id":"c","ar":"يَـ","why":"يَـ marque « il » (et « ils ») : يَكْتُبُ."},{"id":"b","ar":"نَـ","why":"نَـ marque « nous » : نَكْتُبُ."},{"id":"a","ar":"أَ"}],"answer":"a","explanation":"أَكْتُبُ = « j’écris ».","reviewKey":"conj:present:prefix"},{"id":"module_test-m6-m6l5-2","type":"choice","format":"mcq","prompt":"L’arabe classique possède-t-il un temps futur propre ?","options":[{"id":"b","label":"Oui, avec ses propres terminaisons","why":"Il n’existe que deux formes temporelles : accompli et inaccompli."},{"id":"a","label":"Non : on ajoute سَـ ou سَوْفَ à l’inaccompli"}],"answer":"a","explanation":"Le futur se construit sur l’inaccompli."},{"id":"module_test-m6-m6l5-3","type":"choice","format":"mcq","prompt":"Comment dire « nous écrirons » ?","options":[{"id":"c","ar":"سَيَكْتُبُونَ","why":"سَيَكْتُبُونَ = « ils écriront »."},{"id":"a","ar":"سَنَكْتُبُ"},{"id":"b","ar":"كَتَبْنَا","why":"كَتَبْنَا = « nous avons écrit »."}],"answer":"a","explanation":"سَـ + نَكْتُبُ = سَنَكْتُبُ."},{"id":"module_test-m6-m6l6-1","type":"choice","format":"mcq","prompt":"Impératif masculin singulier de جَلَسَ / يَجْلِسُ ?","options":[{"id":"b","ar":"اُجْلُسْ","why":"L’inaccompli est يَجْلِسُ (kasra) : la voyelle d’appui est « i » et la kasra reste."},{"id":"c","ar":"جَلَسَ","why":"جَلَسَ est le passé."},{"id":"a","ar":"اِجْلِسْ"}],"answer":"a","explanation":"تَجْلِسُ → اِجْلِسْ.","reviewKey":"conj:imperative"},{"id":"module_test-m6-m6l6-3","type":"choice","format":"mcq","prompt":"Comment dire « écrivez ! » à plusieurs hommes ?","options":[{"id":"c","ar":"كَتَبُوا","why":"كَتَبُوا = « ils ont écrit »."},{"id":"a","ar":"اُكْتُبُوا"},{"id":"b","ar":"اُكْتُبِي","why":"اُكْتُبِي s’adresse à une femme."}],"answer":"a","explanation":"Terminaison ـُوا pour le masculin pluriel."}],"summary":["Résultat enregistré dans votre progression.","Les notions manquées sont ajoutées à vos révisions."]}'::jsonb) on conflict (lesson_id) do update set content = excluded.content, version = public.lesson_contents.version + 1, updated_at = now();
insert into public.modules (id, course_id, position, title_fr, subtitle_fr, tier, published) values (7, 1, 7, 'Grammaire approfondie', 'Phrases, pronoms, prépositions, cas', 'premium', true) on conflict (id) do update set title_fr = excluded.title_fr, subtitle_fr = excluded.subtitle_fr, tier = excluded.tier;
insert into public.lessons (id, module_id, position, title_fr, objective_fr, difficulty, est_minutes, kind, published) values ('m7l1', 7, 1, 'Nom, verbe et particule', 'Classer un mot dans l’une des trois catégories', 1, 9, 'lesson', true) on conflict (id) do update set title_fr = excluded.title_fr, objective_fr = excluded.objective_fr, difficulty = excluded.difficulty, est_minutes = excluded.est_minutes, kind = excluded.kind, position = excluded.position;
insert into public.lesson_contents (lesson_id, content) values ('m7l1', '{"steps":[{"kind":"explain","text":"La grammaire arabe classique répartit tous les mots en trois catégories : le nom (ism), qui inclut aussi les adjectifs et les pronoms ; le verbe (fiʿl) ; la particule (ḥarf), mot qui n’a de sens complet qu’avec d’autres mots (prépositions, conjonctions…)."},{"kind":"table","caption":"Les trois catégories","head":["Catégorie","Exemple","Sens"],"rows":[["nom (ism)","كِتَاب","livre"],["verbe (fiʿl)","كَتَبَ","il a écrit"],["particule (ḥarf)","فِي","dans"]],"arCols":[1]},{"kind":"tip","text":"Indices d’un nom : il peut recevoir l’article الـ ou le tanwīn."}],"exercises":[{"id":"m7l1-sort","type":"sort","prompt":"Classez ces mots","buckets":[{"id":"ism","label":"Nom"},{"id":"fil","label":"Verbe"},{"id":"harf","label":"Particule"}],"items":[{"id":"a","ar":"قَلْب","label":"cœur","bucket":"ism"},{"id":"b","ar":"خَلَقَ","label":"il a créé","bucket":"fil"},{"id":"c","ar":"مِنْ","label":"de","bucket":"harf"},{"id":"d","ar":"عَلِيم","label":"omniscient","bucket":"ism","why":"Les adjectifs font partie des noms en grammaire arabe."},{"id":"e","ar":"يَكْتُبُ","label":"il écrit","bucket":"fil"},{"id":"f","ar":"عَلَى","label":"sur","bucket":"harf"}],"explanation":"Noms : قَلْب, عَلِيم. Verbes : خَلَقَ, يَكْتُبُ. Particules : مِنْ, عَلَى."},{"id":"m7l1-2","type":"choice","format":"mcq","prompt":"Dans quelle catégorie l’adjectif est-il classé ?","options":[{"id":"a","label":"Nom (ism)"},{"id":"c","label":"Verbe (fiʿl)","why":"Le verbe exprime une action liée à un temps."},{"id":"b","label":"Particule (ḥarf)","why":"Les particules n’ont pas de sens autonome ; un adjectif en a un."}],"answer":"a","explanation":"En grammaire arabe, adjectifs et pronoms sont des noms."}],"summary":["Trois catégories : ism, fiʿl, ḥarf."]}'::jsonb) on conflict (lesson_id) do update set content = excluded.content, version = public.lesson_contents.version + 1, updated_at = now();
insert into public.lessons (id, module_id, position, title_fr, objective_fr, difficulty, est_minutes, kind, published) values ('m7l2', 7, 2, 'L’article et l’annexion', 'Rendre un nom défini ; construire « le livre de Dieu »', 2, 9, 'lesson', true) on conflict (id) do update set title_fr = excluded.title_fr, objective_fr = excluded.objective_fr, difficulty = excluded.difficulty, est_minutes = excluded.est_minutes, kind = excluded.kind, position = excluded.position;
insert into public.lesson_contents (lesson_id, content) values ('m7l2', '{"steps":[{"kind":"explain","text":"Un nom est indéfini avec le tanwīn (كِتَابٌ, « un livre ») et défini avec l’article الـ (الْكِتَابُ, « le livre »). On n’a jamais les deux à la fois."},{"kind":"explain","text":"L’annexion (iḍāfa) relie deux noms : « le livre de Dieu » se dit كِتَابُ اللَّهِ. Le premier nom ne prend ni article ni tanwīn ; le second est au cas indirect (kasra)."},{"kind":"example","ar":"كِتَابُ اللَّهِ","translit":"kitābu llāhi","fr":"le livre de Dieu"},{"kind":"example","ar":"يَوْمُ الدِّينِ","translit":"yawmu d-dīni","fr":"le jour de la rétribution"}],"exercises":[{"id":"m7l2-1","type":"choice","format":"mcq","prompt":"Comment dire « le livre » ?","options":[{"id":"a","ar":"الْكِتَابُ"},{"id":"c","ar":"الْكِتَابٌ","why":"L’article et le tanwīn ne se combinent jamais."},{"id":"b","ar":"كِتَابٌ","why":"كِتَابٌ (tanwīn) = « un livre »."}],"answer":"a","explanation":"Article الـ = défini.","reviewKey":"gram:article"},{"id":"m7l2-2","type":"choice","format":"mcq","prompt":"Dans كِتَابُ اللَّهِ, pourquoi كِتَابُ n’a-t-il ni article ni tanwīn ?","options":[{"id":"c","label":"Parce que c’est un verbe","why":"كِتَاب est un nom."},{"id":"b","label":"C’est une erreur d’écriture","why":"C’est la règle : le premier terme de l’iḍāfa est défini par le second."},{"id":"a","label":"Il est le premier terme d’une annexion"}],"answer":"a","explanation":"Le premier terme de l’iḍāfa ne prend ni الـ ni tanwīn.","reviewKey":"gram:idafa"}],"summary":["Défini : الـ ; indéfini : tanwīn.","Iḍāfa : nom1 (sans article) + nom2 (cas indirect)."]}'::jsonb) on conflict (lesson_id) do update set content = excluded.content, version = public.lesson_contents.version + 1, updated_at = now();
insert into public.lessons (id, module_id, position, title_fr, objective_fr, difficulty, est_minutes, kind, published) values ('m7l3', 7, 3, 'La phrase nominale', 'Construire et analyser une phrase sans verbe', 2, 9, 'lesson', true) on conflict (id) do update set title_fr = excluded.title_fr, objective_fr = excluded.objective_fr, difficulty = excluded.difficulty, est_minutes = excluded.est_minutes, kind = excluded.kind, position = excluded.position;
insert into public.lesson_contents (lesson_id, content) values ('m7l3', '{"steps":[{"kind":"explain","text":"La phrase nominale commence par un nom. Elle comporte un sujet (mubtadaʾ), en général défini, et un prédicat (khabar) qui dit quelque chose de lui. Le verbe « être » au présent n’est pas exprimé."},{"kind":"example","ar":"اللَّهُ عَلِيمٌ","translit":"Allāhu ʿalīmun","fr":"Dieu est omniscient"},{"kind":"example","ar":"الْبَيْتُ كَبِيرٌ","translit":"al-baytu kabīrun","fr":"la maison est grande"},{"kind":"tip","text":"Les deux termes sont au cas direct (marfūʿ), marqué ici par la ḍamma."}],"exercises":[{"id":"m7l3-1","type":"choice","format":"mcq","prompt":"Dans الْبَيْتُ كَبِيرٌ, quel mot est le mubtadaʾ (sujet) ?","options":[{"id":"a","ar":"الْبَيْتُ"},{"id":"b","ar":"كَبِيرٌ","why":"كَبِيرٌ est le khabar : il dit quelque chose du sujet."}],"answer":"a","explanation":"Le sujet défini vient en tête : الْبَيْتُ.","reviewKey":"gram:nominal"},{"id":"m7l3-2","type":"choice","format":"mcq","prompt":"Comment traduire اللَّهُ عَلِيمٌ ?","options":[{"id":"a","label":"Dieu est omniscient"},{"id":"b","label":"Le Dieu omniscient","why":"Pour une simple qualification, l’adjectif serait défini : اللَّهُ الْعَلِيمُ. Ici l’indéfini en fait un prédicat."},{"id":"c","label":"Dieu a su","why":"« il a su » serait le verbe عَلِمَ."}],"answer":"a","explanation":"Sujet défini + prédicat indéfini = phrase complète avec « est » sous-entendu."}],"summary":["Phrase nominale = mubtadaʾ + khabar.","« être » au présent est sous-entendu."]}'::jsonb) on conflict (lesson_id) do update set content = excluded.content, version = public.lesson_contents.version + 1, updated_at = now();
insert into public.lessons (id, module_id, position, title_fr, objective_fr, difficulty, est_minutes, kind, published) values ('m7l4', 7, 4, 'La phrase verbale', 'Identifier verbe, sujet et complément', 2, 9, 'lesson', true) on conflict (id) do update set title_fr = excluded.title_fr, objective_fr = excluded.objective_fr, difficulty = excluded.difficulty, est_minutes = excluded.est_minutes, kind = excluded.kind, position = excluded.position;
insert into public.lesson_contents (lesson_id, content) values ('m7l4', '{"steps":[{"kind":"explain","text":"La phrase verbale commence par un verbe. Ordre habituel : verbe (fiʿl) + sujet (fāʿil, cas direct) + complément d’objet (mafʿūl bihi, cas direct-objet, marqué par la fatḥa)."},{"kind":"example","ar":"كَتَبَ الطَّالِبُ الدَّرْسَ","translit":"kataba ṭ-ṭālibu d-darsa","fr":"l’étudiant a écrit la leçon"},{"kind":"tip","text":"Quand le sujet est un nom placé après le verbe, le verbe reste au singulier, même si le sujet est pluriel."}],"exercises":[{"id":"m7l4-1","type":"choice","format":"mcq","prompt":"Dans كَتَبَ الطَّالِبُ الدَّرْسَ, quel est le sujet ?","options":[{"id":"c","ar":"كَتَبَ","why":"كَتَبَ est le verbe."},{"id":"b","ar":"الدَّرْسَ","why":"الدَّرْسَ porte une fatḥa : c’est le complément d’objet."},{"id":"a","ar":"الطَّالِبُ"}],"answer":"a","explanation":"Le sujet est au cas direct (ḍamma) : الطَّالِبُ.","reviewKey":"gram:verbal"},{"id":"m7l4-2","type":"choice","format":"mcq","prompt":"Quelle voyelle finale marque ici le complément d’objet ?","options":[{"id":"b","label":"la ḍamma","why":"La ḍamma marque le cas direct du sujet."},{"id":"a","label":"la fatḥa"},{"id":"c","label":"la kasra","why":"La kasra marque le cas indirect (après préposition, en iḍāfa)."}],"answer":"a","explanation":"Complément d’objet = manṣūb, marqué par la fatḥa."}],"summary":["Verbe + sujet (ḍamma) + complément (fatḥa)."]}'::jsonb) on conflict (lesson_id) do update set content = excluded.content, version = public.lesson_contents.version + 1, updated_at = now();
insert into public.lessons (id, module_id, position, title_fr, objective_fr, difficulty, est_minutes, kind, published) values ('m7l5', 7, 5, 'Les pronoms', 'Reconnaître pronoms isolés et suffixes', 2, 9, 'lesson', true) on conflict (id) do update set title_fr = excluded.title_fr, objective_fr = excluded.objective_fr, difficulty = excluded.difficulty, est_minutes = excluded.est_minutes, kind = excluded.kind, position = excluded.position;
insert into public.lesson_contents (lesson_id, content) values ('m7l5', '{"steps":[{"kind":"explain","text":"L’arabe a des pronoms isolés (sujets) et des pronoms suffixes attachés à un nom (possessif), à un verbe (complément) ou à une préposition."},{"kind":"table","caption":"Pronoms","head":["Personne","Isolé","Suffixe","Exemple"],"rows":[["il","هُوَ","ـهُ","كِتَابُهُ (son livre)"],["elle","هِيَ","ـهَا","كِتَابُهَا (son livre à elle)"],["tu (m.)","أَنْتَ","ـكَ","كِتَابُكَ (ton livre)"],["je","أَنَا","ـي","كِتَابِي (mon livre)"],["nous","نَحْنُ","ـنَا","كِتَابُنَا (notre livre)"],["ils","هُمْ","ـهُمْ","كِتَابُهُمْ (leur livre)"]],"arCols":[1,2,3]}],"exercises":[{"id":"m7l5-1","type":"choice","format":"mcq","prompt":"Que signifie كِتَابُنَا ?","options":[{"id":"b","label":"nous avons écrit","why":"« nous avons écrit » = كَتَبْنَا (verbe)."},{"id":"c","label":"leur livre","why":"« leur livre » = كِتَابُهُمْ."},{"id":"a","label":"notre livre"}],"answer":"a","explanation":"Suffixe ـنَا = « notre / nous ».","reviewKey":"gram:pronouns"},{"id":"m7l5-2","type":"choice","format":"mcq","prompt":"Quel est le pronom isolé « elle » ?","options":[{"id":"c","ar":"ـهَا","why":"ـهَا est le suffixe, pas le pronom isolé."},{"id":"b","ar":"هُوَ","why":"هُوَ = « il »."},{"id":"a","ar":"هِيَ"}],"answer":"a","explanation":"هِيَ = elle ; suffixe ـهَا."}],"summary":["Isolés : هُوَ هِيَ أَنْتَ أَنَا نَحْنُ هُمْ…","Suffixes : ـهُ ـهَا ـكَ ـي ـنَا ـهُمْ…"]}'::jsonb) on conflict (lesson_id) do update set content = excluded.content, version = public.lesson_contents.version + 1, updated_at = now();
insert into public.lessons (id, module_id, position, title_fr, objective_fr, difficulty, est_minutes, kind, published) values ('m7l6', 7, 6, 'Prépositions et cas', 'Reconnaître les trois cas et l’effet des prépositions', 3, 9, 'lesson', true) on conflict (id) do update set title_fr = excluded.title_fr, objective_fr = excluded.objective_fr, difficulty = excluded.difficulty, est_minutes = excluded.est_minutes, kind = excluded.kind, position = excluded.position;
insert into public.lesson_contents (lesson_id, content) values ('m7l6', '{"steps":[{"kind":"explain","text":"Les noms arabes portent une marque de cas : direct (marfūʿ, ḍamma), direct-objet (manṣūb, fatḥa), indirect (majrūr, kasra). Après une préposition, le nom est toujours majrūr."},{"kind":"table","caption":"Prépositions fréquentes","head":["Préposition","Sens","Exemple"],"rows":[["فِي","dans","فِي الْبَيْتِ"],["مِنْ","de","مِنَ السَّمَاءِ"],["إِلَى","vers","إِلَى اللَّهِ"],["عَلَى","sur","عَلَى الْأَرْضِ"],["بِـ","avec, par","بِالْقَلَمِ"],["لِـ","à, pour","لِلَّهِ"]],"arCols":[0,2]},{"kind":"tip","text":"مِنْ devient مِنَ devant l’article : on ajoute une voyelle pour enchaîner."}],"exercises":[{"id":"m7l6-1","type":"choice","format":"mcq","prompt":"Après فِي, le nom est au cas…","options":[{"id":"a","label":"indirect (majrūr, kasra)"},{"id":"c","label":"direct-objet (manṣūb)","why":"Le manṣūb marque notamment le complément d’objet."},{"id":"b","label":"direct (marfūʿ)","why":"Le cas direct marque le sujet ; une préposition impose le majrūr."}],"answer":"a","explanation":"Préposition + nom majrūr : فِي الْبَيْتِ.","reviewKey":"gram:cases"},{"id":"m7l6-2","type":"choice","format":"mcq","prompt":"Que signifie لِلَّهِ ?","options":[{"id":"b","label":"vers Dieu","why":"« vers Dieu » = إِلَى اللَّهِ."},{"id":"a","label":"à Dieu, pour Dieu"},{"id":"c","label":"de Dieu","why":"« de » se dit مِنْ."}],"answer":"a","explanation":"لِـ + اللَّه = لِلَّهِ."}],"summary":["Trois cas : ḍamma / fatḥa / kasra.","Préposition → majrūr."]}'::jsonb) on conflict (lesson_id) do update set content = excluded.content, version = public.lesson_contents.version + 1, updated_at = now();
insert into public.lessons (id, module_id, position, title_fr, objective_fr, difficulty, est_minutes, kind, published) values ('m7-test', 7, 99, 'Test du module 7 : la grammaire', 'Valider les acquis du module : 80 % de bonnes réponses sont nécessaires.', 2, 8, 'module_test', true) on conflict (id) do update set title_fr = excluded.title_fr, objective_fr = excluded.objective_fr, difficulty = excluded.difficulty, est_minutes = excluded.est_minutes, kind = excluded.kind, position = excluded.position;
insert into public.lesson_contents (lesson_id, content) values ('m7-test', '{"steps":[{"kind":"explain","text":"Ce test reprend les notions des leçons du module. Prenez votre temps : il n’y a pas de limite de durée et vous pourrez le repasser."}],"exercises":[{"id":"module_test-m7-m7l1-2","type":"choice","format":"mcq","prompt":"Dans quelle catégorie l’adjectif est-il classé ?","options":[{"id":"a","label":"Nom (ism)"},{"id":"c","label":"Verbe (fiʿl)","why":"Le verbe exprime une action liée à un temps."},{"id":"b","label":"Particule (ḥarf)","why":"Les particules n’ont pas de sens autonome ; un adjectif en a un."}],"answer":"a","explanation":"En grammaire arabe, adjectifs et pronoms sont des noms."},{"id":"module_test-m7-m7l1-sort","type":"sort","prompt":"Classez ces mots","buckets":[{"id":"ism","label":"Nom"},{"id":"fil","label":"Verbe"},{"id":"harf","label":"Particule"}],"items":[{"id":"a","ar":"قَلْب","label":"cœur","bucket":"ism"},{"id":"b","ar":"خَلَقَ","label":"il a créé","bucket":"fil"},{"id":"c","ar":"مِنْ","label":"de","bucket":"harf"},{"id":"d","ar":"عَلِيم","label":"omniscient","bucket":"ism","why":"Les adjectifs font partie des noms en grammaire arabe."},{"id":"e","ar":"يَكْتُبُ","label":"il écrit","bucket":"fil"},{"id":"f","ar":"عَلَى","label":"sur","bucket":"harf"}],"explanation":"Noms : قَلْب, عَلِيم. Verbes : خَلَقَ, يَكْتُبُ. Particules : مِنْ, عَلَى."},{"id":"module_test-m7-m7l2-1","type":"choice","format":"mcq","prompt":"Comment dire « le livre » ?","options":[{"id":"a","ar":"الْكِتَابُ"},{"id":"c","ar":"الْكِتَابٌ","why":"L’article et le tanwīn ne se combinent jamais."},{"id":"b","ar":"كِتَابٌ","why":"كِتَابٌ (tanwīn) = « un livre »."}],"answer":"a","explanation":"Article الـ = défini.","reviewKey":"gram:article"},{"id":"module_test-m7-m7l2-2","type":"choice","format":"mcq","prompt":"Dans كِتَابُ اللَّهِ, pourquoi كِتَابُ n’a-t-il ni article ni tanwīn ?","options":[{"id":"c","label":"Parce que c’est un verbe","why":"كِتَاب est un nom."},{"id":"b","label":"C’est une erreur d’écriture","why":"C’est la règle : le premier terme de l’iḍāfa est défini par le second."},{"id":"a","label":"Il est le premier terme d’une annexion"}],"answer":"a","explanation":"Le premier terme de l’iḍāfa ne prend ni الـ ni tanwīn.","reviewKey":"gram:idafa"},{"id":"module_test-m7-m7l3-1","type":"choice","format":"mcq","prompt":"Dans الْبَيْتُ كَبِيرٌ, quel mot est le mubtadaʾ (sujet) ?","options":[{"id":"a","ar":"الْبَيْتُ"},{"id":"b","ar":"كَبِيرٌ","why":"كَبِيرٌ est le khabar : il dit quelque chose du sujet."}],"answer":"a","explanation":"Le sujet défini vient en tête : الْبَيْتُ.","reviewKey":"gram:nominal"},{"id":"module_test-m7-m7l3-2","type":"choice","format":"mcq","prompt":"Comment traduire اللَّهُ عَلِيمٌ ?","options":[{"id":"a","label":"Dieu est omniscient"},{"id":"b","label":"Le Dieu omniscient","why":"Pour une simple qualification, l’adjectif serait défini : اللَّهُ الْعَلِيمُ. Ici l’indéfini en fait un prédicat."},{"id":"c","label":"Dieu a su","why":"« il a su » serait le verbe عَلِمَ."}],"answer":"a","explanation":"Sujet défini + prédicat indéfini = phrase complète avec « est » sous-entendu."},{"id":"module_test-m7-m7l4-1","type":"choice","format":"mcq","prompt":"Dans كَتَبَ الطَّالِبُ الدَّرْسَ, quel est le sujet ?","options":[{"id":"c","ar":"كَتَبَ","why":"كَتَبَ est le verbe."},{"id":"b","ar":"الدَّرْسَ","why":"الدَّرْسَ porte une fatḥa : c’est le complément d’objet."},{"id":"a","ar":"الطَّالِبُ"}],"answer":"a","explanation":"Le sujet est au cas direct (ḍamma) : الطَّالِبُ.","reviewKey":"gram:verbal"},{"id":"module_test-m7-m7l4-2","type":"choice","format":"mcq","prompt":"Quelle voyelle finale marque ici le complément d’objet ?","options":[{"id":"b","label":"la ḍamma","why":"La ḍamma marque le cas direct du sujet."},{"id":"a","label":"la fatḥa"},{"id":"c","label":"la kasra","why":"La kasra marque le cas indirect (après préposition, en iḍāfa)."}],"answer":"a","explanation":"Complément d’objet = manṣūb, marqué par la fatḥa."},{"id":"module_test-m7-m7l5-1","type":"choice","format":"mcq","prompt":"Que signifie كِتَابُنَا ?","options":[{"id":"b","label":"nous avons écrit","why":"« nous avons écrit » = كَتَبْنَا (verbe)."},{"id":"c","label":"leur livre","why":"« leur livre » = كِتَابُهُمْ."},{"id":"a","label":"notre livre"}],"answer":"a","explanation":"Suffixe ـنَا = « notre / nous ».","reviewKey":"gram:pronouns"},{"id":"module_test-m7-m7l5-2","type":"choice","format":"mcq","prompt":"Quel est le pronom isolé « elle » ?","options":[{"id":"c","ar":"ـهَا","why":"ـهَا est le suffixe, pas le pronom isolé."},{"id":"b","ar":"هُوَ","why":"هُوَ = « il »."},{"id":"a","ar":"هِيَ"}],"answer":"a","explanation":"هِيَ = elle ; suffixe ـهَا."},{"id":"module_test-m7-m7l6-2","type":"choice","format":"mcq","prompt":"Que signifie لِلَّهِ ?","options":[{"id":"b","label":"vers Dieu","why":"« vers Dieu » = إِلَى اللَّهِ."},{"id":"a","label":"à Dieu, pour Dieu"},{"id":"c","label":"de Dieu","why":"« de » se dit مِنْ."}],"answer":"a","explanation":"لِـ + اللَّه = لِلَّهِ."},{"id":"module_test-m7-m7l6-1","type":"choice","format":"mcq","prompt":"Après فِي, le nom est au cas…","options":[{"id":"a","label":"indirect (majrūr, kasra)"},{"id":"c","label":"direct-objet (manṣūb)","why":"Le manṣūb marque notamment le complément d’objet."},{"id":"b","label":"direct (marfūʿ)","why":"Le cas direct marque le sujet ; une préposition impose le majrūr."}],"answer":"a","explanation":"Préposition + nom majrūr : فِي الْبَيْتِ.","reviewKey":"gram:cases"}],"summary":["Résultat enregistré dans votre progression.","Les notions manquées sont ajoutées à vos révisions."]}'::jsonb) on conflict (lesson_id) do update set content = excluded.content, version = public.lesson_contents.version + 1, updated_at = now();
insert into public.modules (id, course_id, position, title_fr, subtitle_fr, tier, published) values (8, 1, 8, 'Compréhension approfondie du Coran', 'Analyse de mots et de versets', 'premium', true) on conflict (id) do update set title_fr = excluded.title_fr, subtitle_fr = excluded.subtitle_fr, tier = excluded.tier;
insert into public.lessons (id, module_id, position, title_fr, objective_fr, difficulty, est_minutes, kind, published) values ('m8l1', 8, 1, 'Méthode d’analyse d’un mot', 'Analyser un mot : racine, catégorie, fonction', 2, 9, 'lesson', true) on conflict (id) do update set title_fr = excluded.title_fr, objective_fr = excluded.objective_fr, difficulty = excluded.difficulty, est_minutes = excluded.est_minutes, kind = excluded.kind, position = excluded.position;
insert into public.lesson_contents (lesson_id, content) values ('m8l1', '{"steps":[{"kind":"explain","text":"Pour analyser un mot du Coran, posez quatre questions : 1) Quelle est sa catégorie (nom, verbe, particule) ? 2) Quelle est sa racine ? 3) Quelle est sa forme (défini, indéfini, temps du verbe…) ? 4) Quelle est sa fonction dans la phrase ?"},{"kind":"explain","text":"Les analyses présentées ici suivent l’analyse grammaticale (iʿrāb) la plus répandue. Lorsque les grammairiens divergent, nous le signalons. Une analyse grammaticale n’est pas une interprétation religieuse du verset."},{"kind":"quran","ref":{"surah":1,"ayah":2},"fr":"Traduction indicative : « Louange à Dieu, Seigneur des mondes. »"},{"kind":"table","caption":"Analyse de 1:2","head":["Mot","Catégorie","Racine","Fonction"],"rows":[["الْحَمْدُ","nom défini","ح م د","sujet (mubtadaʾ), cas direct"],["لِلَّهِ","préposition لِـ + nom","—","groupe prépositionnel formant le prédicat (khabar)"],["رَبِّ","nom","ر ب ب","qualificatif (naʿt) ou apposition (badal) de اللَّه selon les grammairiens, cas indirect"],["الْعَالَمِينَ","nom pluriel","ع ل م","complément du nom (muḍāf ilayhi), cas indirect"]],"arCols":[0]}],"exercises":[{"id":"m8l1-1","type":"choice","format":"mcq","prompt":"Dans 1:2, quelle est la fonction de الْحَمْدُ ?","options":[{"id":"b","label":"Verbe","why":"الْحَمْدُ porte l’article : c’est un nom."},{"id":"a","label":"Sujet de la phrase nominale (mubtadaʾ)"},{"id":"c","label":"Complément d’objet","why":"Il porte une ḍamma (cas direct) et ouvre une phrase nominale."}],"answer":"a","explanation":"الْحَمْدُ : nom défini au cas direct, sujet de la phrase nominale.","quranRef":{"surah":1,"ayah":2,"wordFrom":1,"wordTo":1},"reviewKey":"analysis:1:2"},{"id":"m8l1-2","type":"choice","format":"mcq","prompt":"Quelle est la racine de رَبِّ ?","options":[{"id":"a","ar":"ر ب ب"},{"id":"b","ar":"ر ب ي","why":"La shadda sur ب indique un ب doublé : la racine est ر ب ب."},{"id":"c","ar":"ع ر ب","why":"Aucun ع dans ce mot."}],"answer":"a","explanation":"رَبّ : racine ر ب ب (la shadda révèle la 2e et la 3e consonne identiques).","quranRef":{"surah":1,"ayah":2,"wordFrom":3,"wordTo":3}},{"id":"m8l1-3","type":"choice","format":"mcq","prompt":"Pourquoi الْعَالَمِينَ est-il au cas indirect ?","options":[{"id":"c","label":"C’est le sujet","why":"Le sujet est الْحَمْدُ."},{"id":"a","label":"Il est le second terme d’une annexion (« Seigneur des mondes »)"},{"id":"b","label":"Il suit un verbe","why":"Il n’y a pas de verbe dans ce verset."}],"answer":"a","explanation":"رَبِّ الْعَالَمِينَ est une iḍāfa : le second terme est majrūr.","quranRef":{"surah":1,"ayah":2,"wordFrom":4,"wordTo":4}}],"summary":["4 questions : catégorie, racine, forme, fonction.","Analyse ≠ interprétation religieuse."]}'::jsonb) on conflict (lesson_id) do update set content = excluded.content, version = public.lesson_contents.version + 1, updated_at = now();
insert into public.lessons (id, module_id, position, title_fr, objective_fr, difficulty, est_minutes, kind, published) values ('m8l2', 8, 2, 'Analyse de 1:3 et 1:4', 'Reconnaître qualificatifs et annexions', 3, 9, 'lesson', true) on conflict (id) do update set title_fr = excluded.title_fr, objective_fr = excluded.objective_fr, difficulty = excluded.difficulty, est_minutes = excluded.est_minutes, kind = excluded.kind, position = excluded.position;
insert into public.lesson_contents (lesson_id, content) values ('m8l2', '{"steps":[{"kind":"quran","ref":{"surah":1,"ayah":3},"fr":"Traduction indicative : « le Tout-Miséricordieux, le Très-Miséricordieux »"},{"kind":"quran","ref":{"surah":1,"ayah":4},"fr":"Traduction indicative : « Maître du Jour de la rétribution »"},{"kind":"table","caption":"Analyse","head":["Mot","Racine","Fonction"],"rows":[["الرَّحْمَٰنِ","ر ح م","qualificatif (naʿt) de اللَّه, cas indirect"],["الرَّحِيمِ","ر ح م","second qualificatif, cas indirect"],["مَالِكِ","م ل ك","qualificatif, cas indirect ; premier terme d’une annexion"],["يَوْمِ","ي و م","second terme d’annexion, puis premier terme de la suivante"],["الدِّينِ","د ي ن","second terme d’annexion, cas indirect"]],"arCols":[0,1]},{"kind":"explain","text":"Variante de lecture vérifiée : dans la lecture de Ḥafṣ ʿan ʿĀṣim (celle du texte affiché), on lit مَالِكِ (« maître, possesseur ») ; d’autres lectures canoniques lisent مَلِكِ (« roi »)."}],"exercises":[{"id":"m8l2-1","type":"choice","format":"mcq","prompt":"Pourquoi الرَّحْمَٰنِ et الرَّحِيمِ sont-ils au cas indirect ?","options":[{"id":"b","label":"Ils suivent une préposition","why":"Aucune préposition ne les précède directement ; ils s’accordent avec le nom qualifié."},{"id":"a","label":"Ce sont des qualificatifs qui s’accordent avec اللَّه (cas indirect au verset précédent)"},{"id":"c","label":"Ce sont des verbes","why":"Ils portent l’article : ce sont des noms."}],"answer":"a","explanation":"Le naʿt s’accorde en cas avec le nom qu’il qualifie.","quranRef":{"surah":1,"ayah":3}},{"id":"m8l2-2","type":"choice","format":"mcq","prompt":"Combien d’annexions successives y a-t-il dans 1:4 ?","options":[{"id":"a","label":"Deux : مَالِكِ يَوْمِ puis يَوْمِ الدِّينِ"},{"id":"c","label":"Une seule","why":"يَوْمِ est à la fois second terme et premier terme."},{"id":"b","label":"Aucune","why":"Trois noms enchaînés sans article sauf le dernier : c’est une chaîne d’annexions."}],"answer":"a","explanation":"Chaîne d’iḍāfa : مَالِكِ ← يَوْمِ ← الدِّينِ.","quranRef":{"surah":1,"ayah":4}}],"summary":["Le naʿt s’accorde avec le nom qualifié.","Chaîne d’annexions : seul le dernier terme porte l’article."]}'::jsonb) on conflict (lesson_id) do update set content = excluded.content, version = public.lesson_contents.version + 1, updated_at = now();
insert into public.lessons (id, module_id, position, title_fr, objective_fr, difficulty, est_minutes, kind, published) values ('m8l3', 8, 3, 'Analyse de 1:5', 'Repérer un complément antéposé et l’inaccompli', 3, 9, 'lesson', true) on conflict (id) do update set title_fr = excluded.title_fr, objective_fr = excluded.objective_fr, difficulty = excluded.difficulty, est_minutes = excluded.est_minutes, kind = excluded.kind, position = excluded.position;
insert into public.lesson_contents (lesson_id, content) values ('m8l3', '{"steps":[{"kind":"quran","ref":{"surah":1,"ayah":5},"fr":"Traduction indicative : « C’est Toi que nous adorons, et c’est Toi dont nous implorons le secours. »"},{"kind":"table","caption":"Analyse","head":["Mot","Catégorie","Fonction"],"rows":[["إِيَّاكَ","pronom isolé (complément)","complément d’objet placé avant le verbe"],["نَعْبُدُ","verbe inaccompli, « nous », racine ع ب د","verbe ; sujet inclus « nous »"],["وَإِيَّاكَ","particule de coordination وَ + pronom isolé","relie les deux propositions ; second complément placé avant le verbe"],["نَسْتَعِينُ","verbe inaccompli, « nous », racine ع و ن (forme dérivée istafʿala)","verbe ; sujet inclus « nous »"]],"arCols":[0]},{"kind":"explain","text":"Placer le complément إِيَّاكَ avant le verbe produit, selon les grammairiens, un effet de restriction : « Toi, et nul autre »."}],"exercises":[{"id":"m8l3-1","type":"choice","format":"mcq","prompt":"Quel est le temps de نَعْبُدُ ?","options":[{"id":"b","label":"Passé","why":"Le préfixe نَـ caractérise l’inaccompli « nous »."},{"id":"a","label":"Inaccompli (présent), 1re personne du pluriel"},{"id":"c","label":"Impératif","why":"L’impératif n’a pas de préfixe نَـ."}],"answer":"a","explanation":"نَـ + عْبُدُ : inaccompli de عَبَدَ, « nous adorons ».","quranRef":{"surah":1,"ayah":5,"wordFrom":2,"wordTo":2},"reviewKey":"analysis:1:5"},{"id":"m8l3-2","type":"choice","format":"mcq","prompt":"Quelle est la racine de نَسْتَعِينُ ?","options":[{"id":"c","ar":"ن س ت","why":"نَـ est le préfixe de personne."},{"id":"b","ar":"س ت ع","why":"سْتَ fait partie du schème dérivé (istafʿala), pas de la racine."},{"id":"a","ar":"ع و ن"}],"answer":"a","explanation":"Racine ع و ن (aide) ; le schème istafʿala ajoute l’idée de « demander ».","quranRef":{"surah":1,"ayah":5,"wordFrom":4,"wordTo":4}},{"id":"m8l3-3","type":"choice","format":"mcq","prompt":"Quel effet produit l’antéposition de إِيَّاكَ ?","options":[{"id":"a","label":"Une restriction : « Toi seul »"},{"id":"c","label":"Un futur","why":"Le futur se marque par سَـ / سَوْفَ."},{"id":"b","label":"Une question","why":"Il n’y a pas de particule interrogative."}],"answer":"a","explanation":"Complément placé en tête = restriction, selon l’analyse grammaticale courante.","quranRef":{"surah":1,"ayah":5,"wordFrom":1,"wordTo":1}}],"summary":["إِيَّاكَ antéposé = restriction.","نَعْبُدُ / نَسْتَعِينُ : inaccompli « nous »."]}'::jsonb) on conflict (lesson_id) do update set content = excluded.content, version = public.lesson_contents.version + 1, updated_at = now();
insert into public.lessons (id, module_id, position, title_fr, objective_fr, difficulty, est_minutes, kind, published) values ('m8l4', 8, 4, 'Analyse de 1:6', 'Reconnaître l’impératif de supplication et le double complément', 3, 9, 'lesson', true) on conflict (id) do update set title_fr = excluded.title_fr, objective_fr = excluded.objective_fr, difficulty = excluded.difficulty, est_minutes = excluded.est_minutes, kind = excluded.kind, position = excluded.position;
insert into public.lesson_contents (lesson_id, content) values ('m8l4', '{"steps":[{"kind":"quran","ref":{"surah":1,"ayah":6},"fr":"Traduction indicative : « Guide-nous sur le chemin droit. »"},{"kind":"table","caption":"Analyse","head":["Mot","Catégorie","Fonction"],"rows":[["اهْدِنَا","verbe à l’impératif (racine ه د ي) + suffixe ـنَا","supplication (duʿāʾ) ; ـنَا = premier complément « nous »"],["الصِّرَاطَ","nom défini","second complément d’objet, cas direct-objet (fatḥa)"],["الْمُسْتَقِيمَ","participe actif (racine ق و م, forme istafʿala)","qualificatif de الصِّرَاطَ, même cas"]],"arCols":[0]},{"kind":"tip","text":"Adressé à Dieu, l’impératif exprime une demande : les grammairiens parlent de duʿāʾ et non d’ordre."}],"exercises":[{"id":"m8l4-1","type":"choice","format":"mcq","prompt":"Que représente le suffixe ـنَا dans اهْدِنَا ?","options":[{"id":"a","label":"« nous » (complément : guide-nous)"},{"id":"c","label":"Le sujet « nous »","why":"Le sujet de l’impératif est « toi » ; ـنَا est le complément."},{"id":"b","label":"« notre » (possessif)","why":"Attaché à un verbe, le suffixe est complément, pas possessif."}],"answer":"a","explanation":"اهْدِ + نَا = « guide-nous ».","quranRef":{"surah":1,"ayah":6,"wordFrom":1,"wordTo":1},"reviewKey":"analysis:1:6"},{"id":"m8l4-2","type":"choice","format":"mcq","prompt":"Pourquoi الْمُسْتَقِيمَ porte-t-il une fatḥa ?","options":[{"id":"c","label":"Il suit une préposition","why":"Aucune préposition ici ; une préposition imposerait la kasra."},{"id":"a","label":"Il qualifie الصِّرَاطَ et s’accorde avec lui (cas direct-objet)"},{"id":"b","label":"C’est un verbe au passé","why":"Il porte l’article : c’est un nom (participe)."}],"answer":"a","explanation":"Le naʿt prend le cas du nom qualifié.","quranRef":{"surah":1,"ayah":6,"wordFrom":3,"wordTo":3}}],"summary":["Impératif adressé à Dieu = supplication.","Le qualificatif s’accorde en cas."]}'::jsonb) on conflict (lesson_id) do update set content = excluded.content, version = public.lesson_contents.version + 1, updated_at = now();
insert into public.lessons (id, module_id, position, title_fr, objective_fr, difficulty, est_minutes, kind, published) values ('m8-test', 8, 99, 'Test du module 8 : l’analyse', 'Valider les acquis du module : 80 % de bonnes réponses sont nécessaires.', 2, 5, 'module_test', true) on conflict (id) do update set title_fr = excluded.title_fr, objective_fr = excluded.objective_fr, difficulty = excluded.difficulty, est_minutes = excluded.est_minutes, kind = excluded.kind, position = excluded.position;
insert into public.lesson_contents (lesson_id, content) values ('m8-test', '{"steps":[{"kind":"explain","text":"Ce test reprend les notions des leçons du module. Prenez votre temps : il n’y a pas de limite de durée et vous pourrez le repasser."}],"exercises":[{"id":"module_test-m8-m8l1-3","type":"choice","format":"mcq","prompt":"Pourquoi الْعَالَمِينَ est-il au cas indirect ?","options":[{"id":"c","label":"C’est le sujet","why":"Le sujet est الْحَمْدُ."},{"id":"a","label":"Il est le second terme d’une annexion (« Seigneur des mondes »)"},{"id":"b","label":"Il suit un verbe","why":"Il n’y a pas de verbe dans ce verset."}],"answer":"a","explanation":"رَبِّ الْعَالَمِينَ est une iḍāfa : le second terme est majrūr.","quranRef":{"surah":1,"ayah":2,"wordFrom":4,"wordTo":4}},{"id":"module_test-m8-m8l1-2","type":"choice","format":"mcq","prompt":"Quelle est la racine de رَبِّ ?","options":[{"id":"a","ar":"ر ب ب"},{"id":"b","ar":"ر ب ي","why":"La shadda sur ب indique un ب doublé : la racine est ر ب ب."},{"id":"c","ar":"ع ر ب","why":"Aucun ع dans ce mot."}],"answer":"a","explanation":"رَبّ : racine ر ب ب (la shadda révèle la 2e et la 3e consonne identiques).","quranRef":{"surah":1,"ayah":2,"wordFrom":3,"wordTo":3}},{"id":"module_test-m8-m8l2-1","type":"choice","format":"mcq","prompt":"Pourquoi الرَّحْمَٰنِ et الرَّحِيمِ sont-ils au cas indirect ?","options":[{"id":"b","label":"Ils suivent une préposition","why":"Aucune préposition ne les précède directement ; ils s’accordent avec le nom qualifié."},{"id":"a","label":"Ce sont des qualificatifs qui s’accordent avec اللَّه (cas indirect au verset précédent)"},{"id":"c","label":"Ce sont des verbes","why":"Ils portent l’article : ce sont des noms."}],"answer":"a","explanation":"Le naʿt s’accorde en cas avec le nom qu’il qualifie.","quranRef":{"surah":1,"ayah":3}},{"id":"module_test-m8-m8l2-2","type":"choice","format":"mcq","prompt":"Combien d’annexions successives y a-t-il dans 1:4 ?","options":[{"id":"a","label":"Deux : مَالِكِ يَوْمِ puis يَوْمِ الدِّينِ"},{"id":"c","label":"Une seule","why":"يَوْمِ est à la fois second terme et premier terme."},{"id":"b","label":"Aucune","why":"Trois noms enchaînés sans article sauf le dernier : c’est une chaîne d’annexions."}],"answer":"a","explanation":"Chaîne d’iḍāfa : مَالِكِ ← يَوْمِ ← الدِّينِ.","quranRef":{"surah":1,"ayah":4}},{"id":"module_test-m8-m8l3-3","type":"choice","format":"mcq","prompt":"Quel effet produit l’antéposition de إِيَّاكَ ?","options":[{"id":"a","label":"Une restriction : « Toi seul »"},{"id":"c","label":"Un futur","why":"Le futur se marque par سَـ / سَوْفَ."},{"id":"b","label":"Une question","why":"Il n’y a pas de particule interrogative."}],"answer":"a","explanation":"Complément placé en tête = restriction, selon l’analyse grammaticale courante.","quranRef":{"surah":1,"ayah":5,"wordFrom":1,"wordTo":1}},{"id":"module_test-m8-m8l3-2","type":"choice","format":"mcq","prompt":"Quelle est la racine de نَسْتَعِينُ ?","options":[{"id":"c","ar":"ن س ت","why":"نَـ est le préfixe de personne."},{"id":"b","ar":"س ت ع","why":"سْتَ fait partie du schème dérivé (istafʿala), pas de la racine."},{"id":"a","ar":"ع و ن"}],"answer":"a","explanation":"Racine ع و ن (aide) ; le schème istafʿala ajoute l’idée de « demander ».","quranRef":{"surah":1,"ayah":5,"wordFrom":4,"wordTo":4}},{"id":"module_test-m8-m8l4-2","type":"choice","format":"mcq","prompt":"Pourquoi الْمُسْتَقِيمَ porte-t-il une fatḥa ?","options":[{"id":"c","label":"Il suit une préposition","why":"Aucune préposition ici ; une préposition imposerait la kasra."},{"id":"a","label":"Il qualifie الصِّرَاطَ et s’accorde avec lui (cas direct-objet)"},{"id":"b","label":"C’est un verbe au passé","why":"Il porte l’article : c’est un nom (participe)."}],"answer":"a","explanation":"Le naʿt prend le cas du nom qualifié.","quranRef":{"surah":1,"ayah":6,"wordFrom":3,"wordTo":3}},{"id":"module_test-m8-m8l4-1","type":"choice","format":"mcq","prompt":"Que représente le suffixe ـنَا dans اهْدِنَا ?","options":[{"id":"a","label":"« nous » (complément : guide-nous)"},{"id":"c","label":"Le sujet « nous »","why":"Le sujet de l’impératif est « toi » ; ـنَا est le complément."},{"id":"b","label":"« notre » (possessif)","why":"Attaché à un verbe, le suffixe est complément, pas possessif."}],"answer":"a","explanation":"اهْدِ + نَا = « guide-nous ».","quranRef":{"surah":1,"ayah":6,"wordFrom":1,"wordTo":1},"reviewKey":"analysis:1:6"}],"summary":["Résultat enregistré dans votre progression.","Les notions manquées sont ajoutées à vos révisions."]}'::jsonb) on conflict (lesson_id) do update set content = excluded.content, version = public.lesson_contents.version + 1, updated_at = now();
